insert into public.transaction_municipal_requirements
  (municipality_code, municipality_name, county, requirement_key, requirement_state, title, requirements, fees, application_url, department_url, source_urls, source_excerpt, source_hash, last_verified_at, metadata, curated_note, curated_override)
values
  ($t$1601$t$, $t$Bloomingdale Borough$t$, $t$PASSAIC$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Continued Certificate of Occupancy (CCO)$t$, $j$["Issued by: Borough of Bloomingdale Construction Department (Construction Official; inspection by the CCO Officer)","Contact: Mark Lime, CCO Officer (Construction and Zoning Official: Leonard Perre, 973-838-7995, constructionofficial@bloomingdalenj.net) · 973, 838, 7995 ext. 4 · mlime@bloomingdalenj.net","How to apply: Fill out the Borough's residential Continued Certificate of Occupancy application completely (check Resale), and submit it with the $200 fee to the Construction Department, 182 Union Avenue. The CCO Officer (Mark Lime) then contacts you to schedule the inspection, or you can call or email him for an appointment. Per Borough Ordinance 11-1.6(g), payment must be cash or cashier's check payable to the Borough of Bloomingdale.","Smoke alarms on each level including the basement, outside bedroom areas, and in the laundry room over the dryer","Battery-only smoke and CO alarms must be 10-year sealed battery units (UL listed); hardwired alarms must not be replaced with battery alarms","Smoke alarms (hardwired too) over 10 years old must be replaced; CO alarms replaced at end of life","Carbon monoxide alarm near the sleeping areas if the home has a fuel-burning appliance or an attached garage","Secondary power source label (for example CAUTION MULTIPLE SOURCES OF POWER) within 18 inches of the main electrical panel and electric meter if the home has a generator, solar panels or battery storage","House number on the house, 4 to 12 inches high","Graspable handrails on steps with four or more risers","Guardrails (at least 36 inches) on porches and stoops more than 30 inches above grade","GFCI outlets within 6 feet of any water source inside and on all outside outlets","No double-cylinder (keyed both sides) lock on the front entrance door","All bedroom windows open and close easily","Door from an attached garage into the house must be 20-minute fire rated (steel, 1 3/8 inch solid wood or sheet metal on the garage side, no glass)","Heating and water heater flue pipes in good repair and sealed to the chimney; relief valves piped to within 6 inches of the floor","Decks in good condition and to NJ building code; pools (24 inches or deeper) to code and zoning","Accessory structures in good repair and zoning compliant; yard clean and free of rubbish","Also: Open permits and approvals: The CCO application asks for construction permits issued in the last five years and any Planning Board or Board of Adjustment approvals; the office checks for open permits.","Also: Abandoned wells, septic or fuel tanks: The CCO application asks whether there are any abandoned wells, septic systems or fuel tanks on the property."]$j$::jsonb, $j$[{"label":"Continued Certificate of Occupancy, residential single-family dwelling (ordinance)","amount":"$200"},{"label":"Continued Certificate of Occupancy, per unit for commercial, industrial, multifamily or residential rental units (ordinance)","amount":"$100 per unit"},{"label":"Continued Certificate of Occupancy inspection, resale or refinance, per dwelling (residential application form)","amount":"$ 200.00 per dwelling"}]$j$::jsonb, $t$https://www.bloomingdalenj.net/FCpdf/2025%20CCOApp%20residential%2Epdf$t$, $t$https://www.bloomingdalenj.net/cn/webpage.cfm?tpid=13069$t$, $j$[{"url":"https://www.bloomingdalenj.net/uppages/ORD%2024%2D2023%20AMEND%20CH%5F%2011%20%28CERT%20OF%20OCCUPANCY%29%20CLEAN%2EDOC","label":"Official source (bloomingdalenj.net)"},{"url":"https://www.bloomingdalenj.net/cn/webpage.cfm?tpid=13069","label":"Official source (bloomingdalenj.net)"},{"url":"https://www.bloomingdalenj.net/FCpdf/2025%20CCOApp%20residential%2Epdf","label":"Official source (bloomingdalenj.net)"},{"url":"https://www.bloomingdalenj.net/FCpdf/2025%20CCO%20requirements%2Epdf","label":"Official source (bloomingdalenj.net)"}]$j$::jsonb, $t$No person shall occupy or use any portion of a commercial, industrial or residential building after such building or portion thereof has been vacated or sold, or which there has been a change of occupancy, until the owner/landlord shall have applied for and secured a certificate of occupancy therefor from the Construction Official or his designee of the Borough.$t$, $t$ddb02b87251ebd5afc83c8c0586dc1cfa6948797fc814cdc0d0837c419ee671c$t$, $t$2026-10-02T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-02","approved_on":"2026-10-02","needs_lookup":false,"flag_reasons":[],"verification":{"fees":3,"fee_ok":3,"fee_bad":0,"fee_unchecked":0,"quotes":13,"q_ok":13,"q_bad":0,"q_unchecked":0},"source":"property/data/municipal-requirements/checked/1601.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-02 and approved in the NJ Resale Certificate Tracker on 2026-10-02. Source: property/data/municipal-requirements/checked/1601.json$t$, true),
  ($t$1601$t$, $t$Bloomingdale Borough$t$, $t$PASSAIC$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Bloomingdale Fire Prevention Bureau (Bloomingdale Fire Department, local enforcing agency); smoke detector inspections are scheduled through the Building Department (town fire bureau)","Contact: Mark Lime, Fire Official & Bureau Secretary · 973-838-9484 · fireprevention@bloomingdalenj.net","How to apply: The Fire Prevention Bureau page says smoke detector inspections go through the Building Department (973-838-7995). The Borough's resale CCO inspection by Mark Lime (who is also the Fire Official) checks smoke alarms, CO alarms and the secondary power label. Call the Building Department to confirm whether the CCO covers the smoke and CO certificate or a separate application and fee are needed.","Fire official in the NJ state directory, updated 2/19/2026: Mark Lime · (973) 838-9484 · bfprevention@optonline.net","Smoke alarms on each level including the basement, outside bedroom areas, and in the laundry room over the dryer (Borough CCO checklist)","Battery-only smoke and CO alarms must be 10-year sealed battery units, UL listed","Hardwired smoke alarms must not be over 10 years old and must not be replaced with battery alarms","Carbon monoxide alarm near the sleeping areas if the home has a fuel-burning appliance or an attached garage","Secondary power source label within 18 inches of the main electrical panel and electric meter for homes with a generator, solar panels or battery storage (printed, not handwritten)","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[]$j$::jsonb, null, $t$https://www.bloomingdalenj.net/cn/webpage.cfm?tpid=13066$t$, $j$[{"url":"https://www.bloomingdalenj.net/cn/webpage.cfm?tpid=13066","label":"Official source (bloomingdalenj.net)"},{"url":"https://www.bloomingdalenj.net/cn/webpage.cfm?TPID=13065","label":"Official source (bloomingdalenj.net)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$Fire Prevention Bureau fireprevention@bloomingdalenj.net 190 Union Ave , Bloomingdale, NJ 07403 Tel 973-838-9484 Fax 973-838-9485 (Hours by Appointment Only)$t$, $t$e674301813513357b62eb0022efcd526c62bdb2ee5a5085684df9f916e414a7a$t$, $t$2026-10-02T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-02","approved_on":"2026-10-02","needs_lookup":false,"flag_reasons":[],"verification":{"fees":3,"fee_ok":3,"fee_bad":0,"fee_unchecked":0,"quotes":13,"q_ok":13,"q_bad":0,"q_unchecked":0},"source":"property/data/municipal-requirements/checked/1601.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-02 and approved in the NJ Resale Certificate Tracker on 2026-10-02. Source: property/data/municipal-requirements/checked/1601.json$t$, true),
  ($t$1602$t$, $t$Clifton City$t$, $t$PASSAIC$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Dwelling Certificate (Certificate of Inspection for 1 & 2 family dwellings, sale)$t$, $j$["Issued by: Clifton Fire Department, Fire Prevention Bureau, after Building, Tax and Zoning Department sign-off","Contact: Michael Pressler, Fire Marshal (Building Department open-permit check: Ernest Tedesco, Construction Official, 973-470-5809) · (973) 470-5801 · mpressler@cliftonnj.org","Apply: Standard certificate: call the office 7 business days after the inspection; inspections are on Wednesdays 9am to 12 noon. Faster certificates cost more (within 4 to 20 days, or within 4 business days).","How to apply: Fill out the Application for Dwelling Smoke Detector and Carbon Monoxide Compliance completely (check Sale), signed by both seller and buyer. Call the Building Department (973-470-5809) to make sure there are no open permits and ask when and where to get the application stamped. Bring the stamped application, the fee (payable to the City of Clifton) and, if digital signatures are not verified, a copy of the sales contract to Clifton Fire Headquarters (Yellow House on the City Hall property, 900 Clifton Avenue). After-hours drop-off is available in the Fire Headquarters drop box. Certificates must be picked up in person.","Valid for: 6 months after the Fire Department inspection","No open permits on the property (Building Department check and stamp on the application)","Tax and Zoning Department approval (the Zoning Officer reviews and approves all Dwelling Certificates)","Smoke alarms on every level (basement, each floor), excluding crawl spaces and unfinished attics with pull-down stairs","Smoke alarm within 10 feet of the bedroom doors on any floor with bedrooms","All smoke alarms less than 10 years old; battery-only alarms must be 10-year sealed battery units; existing hardwired systems must be kept","Carbon monoxide alarms within 10 feet outside all sleeping areas, with more on each floor that has sleeping areas","Central station fire alarm must be tested beforehand by a Division of Fire Safety certified company; bring the test record or the inspection fails","Multiple sources of power label within 18 inches of the electrical panel and meter for homes with a generator, solar or battery storage (the Bureau supplies and installs the label at the inspection)","An adult over 18 must be present and all areas (unit, basement, attic, common areas) must be accessible","Also: Open permits: Call the Building Department (973-470-5809) to make sure there are no open permits; the application needs the Building Department stamp.","Also: Tax and zoning sign-off: Certificates are contingent on passing the Building, Tax and Zoning Departments."]$j$::jsonb, $j$[{"label":"Dwelling certificate, sale, per unit (one certificate covers the town requirement and the smoke and carbon monoxide certificate; paid once)","amount":"$125.00 per unit"},{"label":"Expedited: certificate available within 4 to 20 days, per unit (paid instead of the standard fee)","amount":"$200 per unit"},{"label":"Expedited: certificate available within 4 business days, per unit (paid instead of the standard fee)","amount":"$300 per unit"},{"label":"Dwelling certificate (smoke and carbon monoxide compliance), sale, per unit (same certificate and fee as the town requirement; paid once)","amount":"$125.00 per unit"},{"label":"Expedited: certificate available within 4 to 20 days, per unit","amount":"$200 per unit"},{"label":"Expedited: certificate available within 4 business days, per unit","amount":"$300 per unit"}]$j$::jsonb, $t$https://www.cliftonnj.org/DocumentCenter/View/127/Dwelling-Application-Packet-PDF$t$, $t$https://www.cliftonnj.org/174/Fire-Department$t$, $j$[{"url":"https://www.cliftonnj.org/DocumentCenter/View/127/Dwelling-Application-Packet-PDF","label":"Official source (cliftonnj.org)"},{"url":"https://www.cliftonnj.org/242/Zoning","label":"Official source (cliftonnj.org)"},{"url":"https://www.cliftonnj.org/227/Building","label":"Official source (cliftonnj.org)"}]$j$::jsonb, $t$No closing shall take place without a VALID Certificate of Inspection. No tenant rental shall take occupancy without a VALID Certificate of Inspection. CERTIFICATES ARE CONTINGENT ON PASSING BUILDING, TAX & ZONING DEPTS.$t$, $t$5a15649f4b68e7747f0d58c8b21778e8008c3e04eefa54cc298c70da436d83ba$t$, $t$2026-10-02T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-02","approved_on":"2026-10-02","needs_lookup":false,"flag_reasons":[],"verification":{"fees":6,"fee_ok":6,"fee_bad":0,"fee_unchecked":0,"quotes":14,"q_ok":14,"q_bad":0,"q_unchecked":0},"source":"property/data/municipal-requirements/checked/1602.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-02 and approved in the NJ Resale Certificate Tracker on 2026-10-02. Source: property/data/municipal-requirements/checked/1602.json$t$, true),
  ($t$1602$t$, $t$Clifton City$t$, $t$PASSAIC$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Clifton Fire Department, Fire Prevention Bureau (town fire bureau)","Contact: Michael Pressler, Fire Marshal · (973) 470-5801 · mpressler@cliftonnj.org","Apply: Standard: certificate ready about 7 business days after the Wednesday inspection. Expedited options: within 4 to 20 days, or within 4 business days, at higher fees.","How to apply: Same application as the Dwelling Certificate: get the Building Department stamp, then bring the application and payment to Fire Headquarters (Yellow House, City Hall property, 900 Clifton Avenue) or use the after-hours drop box with a contact name and phone number on the envelope.","Fire official in the NJ state directory, updated 1/12/2026: Micahel K Pressler · (973) 470-5804 · MPressler@Cliftonnj.org","Smoke alarms on every level and within 10 feet of bedroom doors; all under 10 years old","Battery-only smoke alarms must be 10-year sealed battery units; existing hardwired systems must be maintained","CO alarms (UL 2034) within 10 feet outside all sleeping areas, on each floor with sleeping areas","Central station fire alarm test record from a Division of Fire Safety certified company is required at the inspection; inspectors will not test it","Multiple sources of power label for homes with a generator, solar or battery storage (supplied and installed by the Bureau at the inspection)","The City's Fire Department FAQ still says a dry chemical fire extinguisher, at least 10BC rated and no more than 10 pounds, is needed for the dwelling inspection; the May 2025 packet does not list one","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Dwelling certificate (smoke and carbon monoxide compliance), sale, per unit (same certificate and fee as the town requirement; paid once)","amount":"$125.00 per unit"},{"label":"Expedited: certificate available within 4 to 20 days, per unit","amount":"$200 per unit"},{"label":"Expedited: certificate available within 4 business days, per unit","amount":"$300 per unit"}]$j$::jsonb, $t$https://www.cliftonnj.org/DocumentCenter/View/127/Dwelling-Application-Packet-PDF$t$, $t$https://www.cliftonnj.org/174/Fire-Department$t$, $j$[{"url":"https://www.cliftonnj.org/DocumentCenter/View/127/Dwelling-Application-Packet-PDF","label":"Official source (cliftonnj.org)"},{"url":"https://www.cliftonnj.org/Faq.aspx?QID=110","label":"Official source (cliftonnj.org)"},{"url":"https://www.cliftonnj.org/174/Fire-Department","label":"Official source (cliftonnj.org)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$APPLICATION FOR DWELLING SMOKE DETECTOR & CARBON MONOXIDE COMPLIANCE THE CITY OF CLIFTON | 900 CLIFTON AVENUE, CLIFTON, NJ 07013 PHONE: 973-470-5801 | FAX: 973-470-5844$t$, $t$4c3cd5e650bfe6d735c2cc28f2ec09a93c965e71780f264e4c8598fbd5735cdc$t$, $t$2026-10-02T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-02","approved_on":"2026-10-02","needs_lookup":false,"flag_reasons":[],"verification":{"fees":6,"fee_ok":6,"fee_bad":0,"fee_unchecked":0,"quotes":14,"q_ok":14,"q_bad":0,"q_unchecked":0},"source":"property/data/municipal-requirements/checked/1602.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-02 and approved in the NJ Resale Certificate Tracker on 2026-10-02. Source: property/data/municipal-requirements/checked/1602.json$t$, true),
  ($t$1603$t$, $t$Haledon Borough$t$, $t$PASSAIC$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Certificate of Occupancy for sale (Certificate of Sale; Selling of Property Certificate of Compliance)$t$, $j$["Issued by: Borough of Haledon Construction Department, Office of Code Enforcement","Contact: Arianna Manla, Code Enforcement Officer (Construction and Building Subcode Official and Zoning Officer: Jim Booth… · 973-595-7766, Ext: 133 · amanla@haledonboronj.com","How to apply: Fill out the Certificate of Sale Application (Construction Department, Office of Code Enforcement) and bring it with payment (cash or check) to the Municipal Building, 510 Belmont Avenue. Write one check for the sale certificate and a separate check for the smoke and carbon monoxide inspection ($85). Inspections are held 11 to 1, Tuesday to Thursday.","Also: Landlord registration: If the home will be rented, landlord registration is required (the sale form asks); absentee landlord registration is $100.00."]$j$::jsonb, $j$[{"label":"Selling of property certificate of compliance, one family","amount":"$100.00"},{"label":"Selling of property certificate of compliance, two family","amount":"$200.00"},{"label":"Certificate of Sale application fee, one family / two families (form)","amount":"$100.00 for one family, $200.00 for two families"},{"label":"Smoke and carbon monoxide inspection, added to the sale certificate (separate check)","amount":"$85"},{"label":"Smoke and carbon monoxide, per alarm with a minimum fee (Building/Code Department fee list)","amount":"$6.00 each (Min fee of $85.00)"}]$j$::jsonb, $t$https://www.haledonboronj.com/s/CO-sale-new.pdf$t$, $t$https://www.haledonboronj.com/building$t$, $j$[{"url":"https://www.haledonboronj.com/building","label":"Official source (haledonboronj.com)"},{"url":"https://www.haledonboronj.com/s/CO-sale-new.pdf","label":"Official source (haledonboronj.com)"}]$j$::jsonb, $t$Certificate of Occupancy Requirements A Certificate of Occupancy (CO) is required for: All residential property sales All residential rentals All commercial property sales All commercial rentals$t$, $t$8a40c5de60e2884f1263258f8a49b3c5ddee97f46566ceb706e5fd97c8336f38$t$, $t$2026-10-02T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-02","approved_on":"2026-10-02","needs_lookup":false,"flag_reasons":[],"verification":{"fees":5,"fee_ok":5,"fee_bad":0,"fee_unchecked":0,"quotes":11,"q_ok":11,"q_bad":0,"q_unchecked":0},"source":"property/data/municipal-requirements/checked/1603.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-02 and approved in the NJ Resale Certificate Tracker on 2026-10-02. Source: property/data/municipal-requirements/checked/1603.json$t$, true),
  ($t$1603$t$, $t$Haledon Borough$t$, $t$PASSAIC$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Borough of Haledon Construction Department / Office of Code Enforcement (smoke and carbon monoxide inspection for the Haledon Fire Department enforcing agency) (town fire bureau)","Contact: Arianna Manla, Code Enforcement Officer · 973-595-7766, Ext: 133 · amanla@haledonboronj.com","How to apply: Requested on the same Certificate of Sale Application at the Construction / Code Enforcement office, 510 Belmont Avenue; pay the $85 smoke and carbon monoxide fee with a separate check.","Fire official in the NJ state directory, updated 2/4/2025: Shawn Allen · (973) 595-7766 · Sallen@haledonboronj.com","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Smoke and carbon monoxide inspection, added to the sale certificate (separate check)","amount":"$85"},{"label":"Smoke and carbon monoxide, per alarm with a minimum fee (Building/Code Department fee list)","amount":"$6.00 each (Min fee of $85.00)"}]$j$::jsonb, $t$https://www.haledonboronj.com/s/CO-sale-new.pdf$t$, $t$https://www.haledonboronj.com/building$t$, $j$[{"url":"https://www.haledonboronj.com/fire-prevention-bureau","label":"Official source (haledonboronj.com)"},{"url":"https://www.haledonboronj.com/building","label":"Official source (haledonboronj.com)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"},{"url":"https://www.haledonboronj.com/s/CO-sale-new.pdf","label":"Official source (haledonboronj.com)"}]$j$::jsonb, $t$The Haledon Fire Prevention Bureau is responsible for enforcing the New Jersey Uniform Fire Code in all buildings except owner occupied 1 and 2 family homes.$t$, $t$6e3e688d114f284cb6e497bc840f0a1ade38f86aa3edfc0df8094a60b4eb1935$t$, $t$2026-10-02T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-02","approved_on":"2026-10-02","needs_lookup":false,"flag_reasons":[],"verification":{"fees":5,"fee_ok":5,"fee_bad":0,"fee_unchecked":0,"quotes":11,"q_ok":11,"q_bad":0,"q_unchecked":0},"source":"property/data/municipal-requirements/checked/1603.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-02 and approved in the NJ Resale Certificate Tracker on 2026-10-02. Source: property/data/municipal-requirements/checked/1603.json$t$, true),
  ($t$1604$t$, $t$Hawthorne Borough$t$, $t$PASSAIC$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Certificate of Continuing Compliance (Continued Certificate of Compliance, Transfer of Ownership)$t$, $j$["Issued by: Borough of Hawthorne Fire Prevention Bureau (combined with the smoke detector and carbon monoxide alarm certificate)","Contact: Laura Single, Clerk, Fire Prevention (Fire Official / Fire Subcode Official: Christopher DiBella, 973-427-4590… · 973-427-7544 · lsingle@hawthornenj.org","Apply: Apply at least 14 days before closing; an inspection is required. Applications made less than 5 days before closing pay an extra rush fee.","How to apply: Fill out the Continued Certificate of Compliance / Transfer of Ownership / Smoke Detector and Carbon Monoxide Alarm Certificate residential resale application (all seller, buyer and attorney details are required or it is rejected). Bring it with the fee to the Fire Prevention office, 445 Lafayette Avenue, 2nd Floor, where you also schedule the inspection.","Inspection for compliance with NJ State fire codes and Borough ordinances for continued use","Smoke detector on every level of the home","Carbon monoxide alarm within 10 feet of each sleeping room","Attic and basement may not be used as sleeping rooms or separate dwelling units unless noted on the certificate","In-person appointment inspection (remote or picture inspections ended July 1, 2022)"]$j$::jsonb, $j$[{"label":"Residential resale, per unit (one combined certificate with the smoke and CO certificate; paid once)","amount":"$75"},{"label":"Residential resale, two family home","amount":"$150"},{"label":"Rush: applied less than 5 days before closing (additional)","amount":"$125"},{"label":"Reinspection, per unit (application form)","amount":"$ 20.00 per unit"},{"label":"Residential resale smoke and carbon monoxide certificate, per unit (same combined certificate as the town requirement; paid once)","amount":"$75"},{"label":"Two family home","amount":"$150"},{"label":"Rush: applied less than 5 days before closing (additional)","amount":"$125"},{"label":"Reinspection, per unit","amount":"$ 20.00 per unit"}]$j$::jsonb, $t$https://www.hawthornenj.org/DocumentCenter/View/6245/Smoke-Cert_COC-Transfer-Resale-$t$, $t$https://www.hawthornenj.org/268/Fire-Prevention$t$, $j$[{"url":"https://www.hawthornenj.org/415/Building-DeptConstruction-Inspection","label":"Official source (hawthornenj.org)"},{"url":"https://www.hawthornenj.org/DocumentCenter/View/6245/Smoke-Cert_COC-Transfer-Resale-","label":"Official source (hawthornenj.org)"},{"url":"https://www.hawthornenj.org/DocumentCenter/View/6243/Fee-Schedule","label":"Official source (hawthornenj.org)"},{"url":"https://www.hawthornenj.org/268/Fire-Prevention","label":"Official source (hawthornenj.org)"}]$j$::jsonb, $t$PROPERTY RESALES/Certificate of Continuing Compliance - A Certificate of Continuing Compliance (COO) is required for all property sales in the Borough. This includes residential as well as commercial properties.$t$, $t$4a2fb62ab9406b6fed812bc3fc15bbd3a5e7abf2a79b2021d7ec7f7272206294$t$, $t$2026-10-02T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-02","approved_on":"2026-10-02","needs_lookup":false,"flag_reasons":[],"verification":{"fees":8,"fee_ok":8,"fee_bad":0,"fee_unchecked":0,"quotes":12,"q_ok":12,"q_bad":0,"q_unchecked":0},"source":"property/data/municipal-requirements/checked/1604.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-02 and approved in the NJ Resale Certificate Tracker on 2026-10-02. Source: property/data/municipal-requirements/checked/1604.json$t$, true),
  ($t$1604$t$, $t$Hawthorne Borough$t$, $t$PASSAIC$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Borough of Hawthorne Fire Prevention Bureau (town fire bureau)","Contact: Christopher DiBella, Fire Official / Fire Subcode Official (Bureau Chief); clerk Laura Single, 973-427-7544, lsingle@hawthornenj.org · 973-427-4590 · cdibella@hawthornenj.org","Apply: Apply at least 14 days before closing; less than 5 days before closing adds a $125 rush fee.","How to apply: Bring the completed resale application and fee to the Fire Prevention office, 445 Lafayette Avenue, 2nd Floor, and schedule the inspection there.","Fire official in the NJ state directory, updated 8/25/2025: Christopher Di Bella, Sr. · (973) 427-7544 · cdibella@hawthornenj.org","Smoke detector on every level of the home","Carbon monoxide alarm within 10 feet of each sleeping room","Portable fire extinguisher no longer required as of February 15, 2025 (per the Fire Prevention page)","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Residential resale smoke and carbon monoxide certificate, per unit (same combined certificate as the town requirement; paid once)","amount":"$75"},{"label":"Two family home","amount":"$150"},{"label":"Rush: applied less than 5 days before closing (additional)","amount":"$125"},{"label":"Reinspection, per unit","amount":"$ 20.00 per unit"}]$j$::jsonb, $t$https://www.hawthornenj.org/DocumentCenter/View/6245/Smoke-Cert_COC-Transfer-Resale-$t$, $t$https://www.hawthornenj.org/268/Fire-Prevention$t$, $j$[{"url":"https://www.hawthornenj.org/268/Fire-Prevention","label":"Official source (hawthornenj.org)"},{"url":"https://www.hawthornenj.org/DocumentCenter/View/6245/Smoke-Cert_COC-Transfer-Resale-","label":"Official source (hawthornenj.org)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"},{"url":"https://www.hawthornenj.org/DocumentCenter/View/6243/Fee-Schedule","label":"Official source (hawthornenj.org)"}]$j$::jsonb, $t$Another task performed by Fire Prevention is the certification of the operation of smoke detectors required by the State of New Jersey when a home is sold or there is a change of tenant.$t$, $t$df6e2b9ca3005f222edecbd9e9e84a99ab8215f42ba201d474ea416405ff90f1$t$, $t$2026-10-02T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-02","approved_on":"2026-10-02","needs_lookup":false,"flag_reasons":[],"verification":{"fees":8,"fee_ok":8,"fee_bad":0,"fee_unchecked":0,"quotes":12,"q_ok":12,"q_bad":0,"q_unchecked":0},"source":"property/data/municipal-requirements/checked/1604.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-02 and approved in the NJ Resale Certificate Tracker on 2026-10-02. Source: property/data/municipal-requirements/checked/1604.json$t$, true),
  ($t$1605$t$, $t$Little Falls Township$t$, $t$PASSAIC$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Township Certificate of Compliance (Code Enforcement, resale)$t$, $j$["Issued by: Township of Little Falls Code Enforcement (Building Department)","Contact: Donald Warnet, Code Enforcement (property maintenance, code enforcement and lead inspections); Building Department head: James DiMaria · (973) 256-6182 Ext. 2 · DWARNET@LITTLEFALLSNJ.GOV","Apply: The Township code says the inspection is made within 7 business days after a complete application and fees are submitted (search snippet).","How to apply: Fill out the Township Code Enforcement Certificate of Compliance form (check Resale and Single or Two Family), with current owner, new owner, closing date, inspection contact and new occupant details, signed by the applicant and current owner. File it with the fee (check) at Code Enforcement, Town Hall, 225 Main Street, 2nd floor.","Inspection for compliance with the Township code and the Property Maintenance Code (Chapter 163)","All violations and open permits must be closed before the certificate is issued","The property record card is attached and checked during the inspection","Access must be provided to the entire structure and property","Also: Open permits and violations: All violations and open permits must be closed before the Township Certificate of Compliance is issued."]$j$::jsonb, $j$[{"label":"Certificate of Compliance, single family","amount":"$100.00"},{"label":"Certificate of Compliance, two family","amount":"$100.00"},{"label":"Certificate of Compliance, multiple family, resale only (first 3 units, plus each additional unit)","amount":"$300.00 1st 3 units + $30.00 Every Additional Unit"},{"label":"Smoke detector and carbon monoxide alarm certificate, 10 business days before change of occupant","amount":"$45.00"},{"label":"4 to 10 business days before change of occupant","amount":"$90.00"},{"label":"Fewer than 4 days before change of occupant","amount":"$161.00"},{"label":"Re-inspection after a failed inspection because areas were not accessible","amount":"$20.00"}]$j$::jsonb, $t$https://littlefallsnj.gov/uploads/dm/23207/Residential%20Certificate%20of%20Compliance%202025.pdf$t$, $t$https://littlefallsnj.gov/building-department$t$, $j$[{"url":"https://ecode360.com/6921129","label":"Official source (ecode360.com)"},{"url":"https://littlefallsnj.gov/uploads/dm/23207/Residential%20Certificate%20of%20Compliance%202025.pdf","label":"Official source (littlefallsnj.gov)"},{"url":"https://littlefallsnj.gov/building-department","label":"Official source (littlefallsnj.gov)"},{"url":"https://littlefallsnj.gov/uploads/dm/22746/One%20and%20Two%20Family%20Dwelling%20SACMA%20Application%202025.pdf","label":"Official source (littlefallsnj.gov)"}]$j$::jsonb, $t$No person shall use, occupy, rent, lease, or otherwise occupy any building or land without first obtaining a Township certificate of compliance.$t$, $t$28c69d695bdb8a1c20d675e1a455cce35c09efbdfe87bad4ab29ed0621ef76d4$t$, $t$2026-10-02T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-02","approved_on":"2026-10-02","needs_lookup":false,"flag_reasons":[],"verification":{"fees":7,"fee_ok":7,"fee_bad":0,"fee_unchecked":0,"quotes":13,"q_ok":11,"q_bad":0,"q_unchecked":2},"source":"property/data/municipal-requirements/checked/1605.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-02 and approved in the NJ Resale Certificate Tracker on 2026-10-02. Source: property/data/municipal-requirements/checked/1605.json$t$, true),
  ($t$1605$t$, $t$Little Falls Township$t$, $t$PASSAIC$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Little Falls Bureau of Fire Prevention (Little Falls Fire Department, local enforcing agency) (town fire bureau)","Contact: Antonia Bertino, Office Staff, Fire Prevention Bureau (Fire Official: James DiMaria) · (973) 890-4524 · TBERTINO@LITTLEFALLSNJ.GOV","Apply: Apply 10 or more business days before the change of occupant for the lowest fee.","How to apply: Get the One and Two Family Dwelling application packet from the Fire Prevention Bureau (Town Hall, 2nd floor) or the Township website. Complete it in full, signed by both seller and buyer, and return it in person to the Fire Prevention Bureau with the fee; check or money order payable to Township of Little Falls only. The inspection date is set then; someone 18 or older must be present.","Fire official in the NJ state directory, updated 7/16/2026: James R Di Maria · (973) 890-4524 · JDiMaria@lfnj.com","Smoke alarms on each level including the basement and outside each separate sleeping area; a photoelectric smoke alarm if a bedroom is within 10 feet of the kitchen","Smoke alarms permanently mounted on the ceiling or within 12 inches of the ceiling on the wall","Battery-only smoke alarms must be 10-year sealed battery units (UL 217); hardwired alarms may not be replaced with battery alarms","Smoke alarms in service more than 10 years must be replaced","Central station fire alarm systems must be tested before the inspection and a test report submitted, or the inspection fails","CO alarm within 10 feet of each sleeping area when the home has a fuel-burning appliance or attached garage (battery, hardwired or plug-in)","Secondary power source label (for example CAUTION: MULTIPLE SOURCES OF POWER, not handwritten) within 18 inches of the main electrical panel and meter","Fire extinguishers are no longer required to pass inspection and are optional","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Smoke detector and carbon monoxide alarm certificate, 10 business days before change of occupant","amount":"$45.00"},{"label":"4 to 10 business days before change of occupant","amount":"$90.00"},{"label":"Fewer than 4 days before change of occupant","amount":"$161.00"},{"label":"Re-inspection after a failed inspection because areas were not accessible","amount":"$20.00"}]$j$::jsonb, $t$https://littlefallsnj.gov/uploads/dm/22746/One%20and%20Two%20Family%20Dwelling%20SACMA%20Application%202025.pdf$t$, $t$https://littlefallsnj.gov/fire-prevention-bureau$t$, $j$[{"url":"https://littlefallsnj.gov/uploads/dm/22746/One%20and%20Two%20Family%20Dwelling%20SACMA%20Application%202025.pdf","label":"Official source (littlefallsnj.gov)"},{"url":"https://littlefallsnj.gov/fire-prevention-bureau","label":"Official source (littlefallsnj.gov)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$The application fee for a certificate of smoke detector and carbon monoxide alarm as required by N.J.A.C. 5:70-2.3, shall be based upon the amount of time remaining before the lease or sale date of the dwelling unit is as follows:$t$, $t$64b843853da3104e6a649fec2a70ab2e7f8f338badad96d6eaa1c91000f3a6de$t$, $t$2026-10-02T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-02","approved_on":"2026-10-02","needs_lookup":false,"flag_reasons":[],"verification":{"fees":7,"fee_ok":7,"fee_bad":0,"fee_unchecked":0,"quotes":13,"q_ok":11,"q_bad":0,"q_unchecked":2},"source":"property/data/municipal-requirements/checked/1605.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-02 and approved in the NJ Resale Certificate Tracker on 2026-10-02. Source: property/data/municipal-requirements/checked/1605.json$t$, true),
  ($t$1606$t$, $t$North Haledon Borough$t$, $t$PASSAIC$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Certificate of Sale (Certificate of Re-occupancy)$t$, $j$["Issued by: Borough of North Haledon, Office of the Construction Official","Contact: Jim Booth, Construction Official / Electrical Sub-Code / Fire Sub-Code Official and Code Enforcement Officer (Technical Assistant… · 973-423-9422 · jbooth@northhaledon.gov","How to apply: Fill out the Borough Certificate of Sale application for a single family or two family dwelling (buyer details, new occupants, sewer or septic, well or public water) and the notarized smoke detector and carbon monoxide alarm certification in the same packet. Submit it with a survey, a clean well test if on a private well, and a check payable to the Borough of North Haledon to the Construction Office, 103 Overlook Avenue.","Address clearly marked on the house and mailbox","Smoke detector on every level and within 10 feet of sleeping areas (a room with a door counts as a bedroom)","Carbon monoxide detector within 10 feet of sleeping areas","Portable fire extinguisher (2 1/2 to 10 pound ABC) mounted within 10 feet of the kitchen near an exit, top no higher than 5 feet (still listed on the Borough checklist)","Copy of a survey of the property","Clean private well test (within six months on the single family checklist) if not on public water, or the certificate will not be issued","Check for open permits and illegal construction","Check for illegal two family or multiple family use","Gas-fired appliance vents installed properly","All meters installed (gas, electric, water)","Pools fenced with working gates; fences 4 feet high, 5 feet around in-ground pools","Also: Private well test: Homes on a private well need a clean well test (Private Well Testing Act) with the application, or a letter from buyer's and seller's attorneys noting the well condition.","Also: Survey: A copy of a survey of the property is required with the Certificate of Sale.","Also: Open permits and illegal construction: The office checks for open permits, illegal construction and illegal two family or multiple family use."]$j$::jsonb, $j$[{"label":"Certificate of Sale, single family","amount":"$100.00"},{"label":"Certificate of Sale, two family dwelling","amount":"$150.00"}]$j$::jsonb, $t$https://www.northhaledon.com/Document%20Center/Forms/Construction%20Permits%20and%20Applications/CERTIFICATE%20OF%20SAFE%20-%20ONE%20FAMILY.pdf$t$, $t$https://www.northhaledon.com/departments/construction_department/index.php$t$, $j$[{"url":"https://www.northhaledon.com/Document%20Center/Forms/Construction%20Permits%20and%20Applications/Certificate%20of%20sale%20%20-%20Two%20Family%20(1).pdf","label":"Official source (northhaledon.com)"},{"url":"https://www.northhaledon.com/Document%20Center/Forms/Construction%20Permits%20and%20Applications/CERTIFICATE%20OF%20SAFE%20-%20ONE%20FAMILY.pdf","label":"Official source (northhaledon.com)"},{"url":"https://www.northhaledon.com/departments/construction_department/index.php","label":"Official source (northhaledon.com)"}]$j$::jsonb, $t$NOTE: Chapter 600-78 of the Borough Ordinances requires that before the occupancy or possession of any building or structure may pass from one person to another a Certificate of Re-occupancy is required.$t$, $t$2205fd610bdf4814b12f1379f3aae0b3803df0c539165073c3fb291657d4c4a6$t$, $t$2026-10-02T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-02","approved_on":"2026-10-02","needs_lookup":false,"flag_reasons":[],"verification":{"fees":2,"fee_ok":2,"fee_bad":0,"fee_unchecked":0,"quotes":9,"q_ok":9,"q_bad":0,"q_unchecked":0},"source":"property/data/municipal-requirements/checked/1606.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-02 and approved in the NJ Resale Certificate Tracker on 2026-10-02. Source: property/data/municipal-requirements/checked/1606.json$t$, true),
  ($t$1606$t$, $t$North Haledon Borough$t$, $t$PASSAIC$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Borough of North Haledon Office of the Construction Official (smoke detector and carbon monoxide alarm compliance for the North Haledon Fire Department enforcing agency) (town fire bureau)","Contact: Jim Booth, Construction Official / Fire Sub-Code Official · 973-423-9422 · jbooth@northhaledon.gov","How to apply: The Borough's Certificate of Sale packet includes an 'Application and Certification for Certificate of Smoke Detector and Carbon Monoxide Alarm Compliance' that the owner signs before a notary; it is filed with the Certificate of Sale at the Construction Office, 103 Overlook Avenue. No separate fee is shown.","Fire official in the NJ state directory, updated 1/30/2020: James Booth · (973) 423-9422 · jbooth@northhaledon.com","Smoke detector on each level including basements (not unfinished attics or crawl spaces), outside each sleeping area and within 10 feet of bedrooms","Carbon monoxide alarm outside each sleeping area, within 10 feet of bedrooms","The Borough's certification form says detectors need not be interconnected and battery alarms are acceptable, but AC powered or interconnected alarms in homes built after January 1977 must be kept working","The Borough sale checklists still list a mounted 2 1/2 to 10 pound ABC portable fire extinguisher within 10 feet of the kitchen","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[]$j$::jsonb, $t$https://www.northhaledon.com/Document%20Center/Forms/Construction%20Permits%20and%20Applications/CERTIFICATE%20OF%20SAFE%20-%20ONE%20FAMILY.pdf$t$, $t$https://www.northhaledon.com/departments/construction_department/index.php$t$, $j$[{"url":"https://www.northhaledon.com/Document%20Center/Forms/Construction%20Permits%20and%20Applications/CERTIFICATE%20OF%20SAFE%20-%20ONE%20FAMILY.pdf","label":"Official source (northhaledon.com)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$APPLICATION AND CERTIFICATION FOR CERTIFICATE OF SMOKE DETECTOR AND CARBON MONOXIDE ALARM COMPLIANCE$t$, $t$82e4320fa8983ced51b56f7179edab7aa7e6d06a0be87dd8b15444d94b596a61$t$, $t$2026-10-02T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-02","approved_on":"2026-10-02","needs_lookup":false,"flag_reasons":[],"verification":{"fees":2,"fee_ok":2,"fee_bad":0,"fee_unchecked":0,"quotes":9,"q_ok":9,"q_bad":0,"q_unchecked":0},"source":"property/data/municipal-requirements/checked/1606.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-02 and approved in the NJ Resale Certificate Tracker on 2026-10-02. Source: property/data/municipal-requirements/checked/1606.json$t$, true),
  ($t$1607$t$, $t$Passaic City$t$, $t$PASSAIC$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Occupancy Certificate (Continued Occupancy Certificate)$t$, $j$["Issued by: City of Passaic Inspections & Code, Division of Housing","Contact: Jacqueline Cruz, Housing Secretary (Director of Inspection & Code: Joe Colon, 973-365-5551, jcolon@cityofpassaicnj.gov) · 973-365-5615 · jcruz@cityofpassaicnj.gov","Apply: Apply at least 2 weeks before closing. If the inspection passes and all final approvals are in, the Continued Occupancy Certificate is issued in 5 to 7 business days; expedited service (5 days or less) costs $300.00 extra.","How to apply: Fill out the Division of Housing Occupancy Certificate Application for a one family or two family home (seller, buyer and room details, signed affidavit), plus the notarized Purchaser's Form and the Fire Prevention Application for Fire Certification. Submit to the Division of Housing, City Hall, 330 Passaic Street, with the fee by money order, check or cash. Inspection and violation reports are emailed to the seller and buyer.","Inspection for compliance with Passaic's property maintenance and zoning laws","Buyer's full contact information on the application (otherwise it is put on hold); the certificate is issued in the buyer's name","Companies buying must give the registered agent's name and a copy of the certificate of formation","Buyer signs a notarized Purchaser's Form agreeing that the cellar is used only for storage (no sleeping, dwelling or rooming use, no partition walls)","Fire Prevention smoke detector and carbon monoxide alarm certification is part of the occupancy certificate requirements","Vacant properties are inspected even without utilities and must stay vacant until violations are fixed and permits are finalized with the Building Department","Cancel inspections at least 24 hours ahead; open applications are voided 60 days after the compliance date","Also: Cellar use affidavit: Buyer signs a notarized Purchaser's Form that the cellar will be used only for storage, not sleeping or dwelling use.","Also: Permits for violations: Vacant properties must stay vacant until violations are fixed and permit paperwork is finalized with the Building Department."]$j$::jsonb, $j$[{"label":"Occupancy Certificate, one family","amount":"$65.00"},{"label":"Occupancy Certificate, two family","amount":"$100.00"},{"label":"Expedited certificate (5 days or less), in addition to the certificate fee","amount":"$300.00"},{"label":"Re-inspection after a missed appointment or when fewer than 60% of units can be inspected ($50 or $20 per unit, whichever is less)","amount":"$50 or $20 per unit, whichever is less"},{"label":"Smoke detector and carbon monoxide alarm certification, initial inspection","amount":"$45.00"},{"label":"Re-inspection","amount":"$25.00"}]$j$::jsonb, $t$https://www.cityofpassaic.com/DocumentCenter/View/12159/One-Family---OC-Application$t$, $t$https://www.cityofpassaic.com/248/Housing$t$, $j$[{"url":"https://www.cityofpassaic.com/DocumentCenter/View/10397/Guidelines-to-Apply-for-Occupancy--Temporary-Occupancy-Certificates","label":"Official source (cityofpassaic.com)"},{"url":"https://www.cityofpassaic.com/DocumentCenter/View/12159/One-Family---OC-Application","label":"Official source (cityofpassaic.com)"},{"url":"https://www.cityofpassaic.com/DocumentCenter/View/12080/1-Family-Purchaser-Form","label":"Official source (cityofpassaic.com)"},{"url":"https://www.cityofpassaic.com/248/Housing","label":"Official source (cityofpassaic.com)"},{"url":"https://www.cityofpassaic.com/DocumentCenter/View/12160/Two-Family---OC-Application","label":"Official source (cityofpassaic.com)"},{"url":"https://www.cityofpassaic.com/DocumentCenter/View/12581/Application-for-Fire-Certification-","label":"Official source (cityofpassaic.com)"}]$j$::jsonb, $t$Occupancy Certificate (OC): Recommended to apply at least two (2) weeks prior to closing date.$t$, $t$728669504cdb8866eb09e4c8a943f5b321baf5f5778cb1d2f9cc90a48e2eacd3$t$, $t$2026-10-02T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-02","approved_on":"2026-10-02","needs_lookup":false,"flag_reasons":[],"verification":{"fees":6,"fee_ok":6,"fee_bad":0,"fee_unchecked":0,"quotes":13,"q_ok":13,"q_bad":0,"q_unchecked":0},"source":"property/data/municipal-requirements/checked/1607.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-02 and approved in the NJ Resale Certificate Tracker on 2026-10-02. Source: property/data/municipal-requirements/checked/1607.json$t$, true),
  ($t$1607$t$, $t$Passaic City$t$, $t$PASSAIC$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: City of Passaic Fire Prevention Bureau (Passaic Fire Department) (town fire bureau)","Contact: Capt. Hershel Rawls IV, Fire Prevention - Fire Official (Bureau office email: FIREPREVENTION@CITYOFPASSAICNJ.GOV) · 973-365-5687 · Hrawls@cityofpassaicnj.gov","Apply: Submitted with the Occupancy Certificate application (apply at least 2 weeks before closing). The certification is valid 3 months after approval.","How to apply: Fill out the Application for Certification of Smoke Detector and Carbon Monoxide Alarm Compliance (buyer's name and contact) and file it with the Occupancy Certificate package; the certification is part of the occupancy certificate and cannot be used alone for closing.","Fire official in the NJ state directory, updated 1/12/2026: Hershel Rawls · (973) 365-5687 · hrawls@cityofpassaicnj.gov","Smoke detectors and CO detectors on each level (basement, first and second floors; not crawl spaces or unfinished attics), battery or AC powered","Smoke and CO detectors outside each sleeping area and within 10 feet of bedrooms","Basement smoke detector as close to the stairwell as possible, not near the furnace; smoke detector in the stairwell to a finished attic","Smoke detectors in the common areas of two family homes","Occupied attics (where permitted): exterior flashing strobe connected to the smoke detectors at the roof peak on the street side (City Ordinance 125-3 L)","The City's current requirements sheet and form still call for a mounted, charged 2A-10BC fire extinguisher in or within 10 feet of the kitchen","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Smoke detector and carbon monoxide alarm certification, initial inspection","amount":"$45.00"},{"label":"Re-inspection","amount":"$25.00"}]$j$::jsonb, $t$https://www.cityofpassaic.com/DocumentCenter/View/12581/Application-for-Fire-Certification-$t$, $t$https://www.cityofpassaic.com/165/Fire-Prevention-Bureau$t$, $j$[{"url":"https://www.cityofpassaic.com/DocumentCenter/View/12581/Application-for-Fire-Certification-","label":"Official source (cityofpassaic.com)"},{"url":"https://www.cityofpassaic.com/DocumentCenter/View/12580/Requirements-for-Smoke-Detector-Carbon-Monoxide--Fire-Extinguisher","label":"Official source (cityofpassaic.com)"},{"url":"https://www.cityofpassaic.com/165/Fire-Prevention-Bureau","label":"Official source (cityofpassaic.com)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$NOTE: CERTIFICATION IS VALID FOR THREE (3) MONTHS AFTER APPROVAL DATE AND ONLY APPROVED FOR USE BY THE INDIVIDUAL LISTED ABOVE. THIS CERTIFICATION IS PART OF THE OCCUPANCY CERTIFICATE REQUIREMENTS FOR THE SALE/PURCHASE OF A PROPERTY AND NOT TO BE USED AS A STANDALONE DOCUMENT FOR CLOSING PURPOSES.$t$, $t$8c813cb3b0a0130deb44f6ba542eba890ddd7d556878f82dc6022f6016f3792f$t$, $t$2026-10-02T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-02","approved_on":"2026-10-02","needs_lookup":false,"flag_reasons":[],"verification":{"fees":6,"fee_ok":6,"fee_bad":0,"fee_unchecked":0,"quotes":13,"q_ok":13,"q_bad":0,"q_unchecked":0},"source":"property/data/municipal-requirements/checked/1607.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-02 and approved in the NJ Resale Certificate Tracker on 2026-10-02. Source: property/data/municipal-requirements/checked/1607.json$t$, true),
  ($t$1609$t$, $t$Pompton Lakes Borough$t$, $t$PASSAIC$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Certificate of Continued Occupancy (CCO), residential$t$, $j$["Issued by: Borough of Pompton Lakes Building Department (Construction Official), under Ordinance 91-30 (Borough Code Section 19-3)","Contact: Carmelina Fusaro, Assistant to Construction Official · 973-835-0143, ext. 223 · building@pomptonlakes-nj.gov","Apply: The Building Department page says to allow three weeks to complete the process; the application form says to allow a minimum of 5 business days for processing","How to apply: Complete the Residential CCO application (check Resale), sign it and submit it with a check payable to the Borough of Pompton Lakes to the Building Department, 25 Lenox Avenue. The office must have the completed application and fee before it schedules the inspection. Inspections are Tuesday through Friday, 3:30 to 5:30 pm. Contact the Fire Prevention Bureau separately for the smoke alarm and carbon monoxide alarm inspection.","Pressure relief (blow-off) pipe on the water heater and boiler must extend down to 6 inches above the floor","Grip-sized handrails on steps with 3 or more risers; no open stairways","Guardrails at least 36 inches high, with no more than 4 inches between balusters, on porches and landings more than 30 inches above grade","Visible house numbers on the house (not on doors)","Secure, firm and sealed chimney connection from the water heater, furnace, boiler or stove","No loose or unprotected electric wires or uncovered boxes","Sidewalks maintained by the homeowner to Borough Code","Separate smoke alarm, carbon monoxide alarm and fire extinguisher check by the Fire Prevention Bureau before resale","Someone 18 or older must be present at the inspection","Also: Zoning permit for change of use or tenant: The Building Department lists Change of Use / Tenant among projects needing zoning and/or construction permits; zoning is at ext. 241."]$j$::jsonb, $j$[{"label":"Residential Certificate of Continued Occupancy (application form)","amount":"$90.00"},{"label":"Residential Certificate of Continued Occupancy (ordinance Section 19-3.7 printed on the form)","amount":"$90.00"},{"label":"Additional follow-up inspections (one follow-up inspection is free)","amount":"$25.00"},{"label":"Each additional follow-up inspection after the free one (ordinance)","amount":"$25"},{"label":"Smoke alarm and carbon monoxide alarm certificate, request received more than 10 business days before the change of occupant (state Uniform Fire Code schedule, N.J.A.C. 5:70-2.9(d), which Borough Ordinance 23-23 adopts as the Borough fee)","amount":"$45.00"},{"label":"Request received 4 to 10 business days before the change of occupant (state schedule adopted by Ordinance 23-23)","amount":"$90.00"},{"label":"Request received fewer than 4 business days before the change of occupant (state schedule adopted by Ordinance 23-23)","amount":"$161.00"}]$j$::jsonb, $t$https://pomptonlakes-nj.gov/DocumentCenter/View/1577/CCO-Residential-Application$t$, $t$https://pomptonlakes-nj.gov/192/Building-Department$t$, $j$[{"url":"https://pomptonlakes-nj.gov/192/Building-Department","label":"Official source (pomptonlakes-nj.gov)"},{"url":"https://pomptonlakes-nj.gov/DocumentCenter/View/1577/CCO-Residential-Application","label":"Official source (pomptonlakes-nj.gov)"},{"url":"https://pomptonlakes-nj.gov/m/directory/department?did=21","label":"Official source (pomptonlakes-nj.gov)"},{"url":"https://www.nj.gov/dca/divisions/dfs/codes/regulations/adopted_amendment_5_10_2.9.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$Continued Certificate of Occupancy (CCO) are required for the resale of residential homes and businesses as well as for change of tenancy. Forms may be obtained at the Building Department and appointments must be scheduled for the CCO Inspector to perform inspections. Please allow three weeks to complete the process.$t$, $t$d5fcbc5d96a1a9ec81a70642aeaa755cd86883703fb2355c4c09f9d4b84ad9f3$t$, $t$2026-10-02T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-02","approved_on":"2026-10-02","needs_lookup":false,"flag_reasons":[],"verification":{"fees":7,"fee_ok":7,"fee_bad":0,"fee_unchecked":0,"quotes":17,"q_ok":17,"q_bad":0,"q_unchecked":0},"source":"property/data/municipal-requirements/checked/1609.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-02 and approved in the NJ Resale Certificate Tracker on 2026-10-02. Source: property/data/municipal-requirements/checked/1609.json$t$, true),
  ($t$1609$t$, $t$Pompton Lakes Borough$t$, $t$PASSAIC$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Pompton Lakes Fire Prevention Bureau (Fire Official) (town fire bureau)","Contact: John Keating, Fire Official · 973-616-5918 · jkeating@pomptonlakes-nj.gov","Apply: Lowest fee when the request is received more than 10 business days before the change of occupant","How to apply: No application form or online portal is posted. Call the Fire Prevention Bureau at 973-616-5918 (the Borough says to call this number for inspections, permits, CO inspections and real estate closing issues) or email the Fire Official. Fees are payable to the Borough of Pompton Lakes.","Fire official in the NJ state directory, updated n/a: John F Keating · (973) 616-5918 · JKeating@pomptonlakes-nj.gov","The Borough's residential CCO form (2025) still lists a fire extinguisher with the smoke alarm and carbon monoxide alarm check by the Fire Prevention Bureau before resale or rental; the state removed the extinguisher from the state certificate in February 2025 (P.L.2025, c.19), so confirm with the Fire Prevention Bureau","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Smoke alarm and carbon monoxide alarm certificate, request received more than 10 business days before the change of occupant (state Uniform Fire Code schedule, N.J.A.C. 5:70-2.9(d), which Borough Ordinance 23-23 adopts as the Borough fee)","amount":"$45.00"},{"label":"Request received 4 to 10 business days before the change of occupant (state schedule adopted by Ordinance 23-23)","amount":"$90.00"},{"label":"Request received fewer than 4 business days before the change of occupant (state schedule adopted by Ordinance 23-23)","amount":"$161.00"}]$j$::jsonb, null, $t$https://pomptonlakes-nj.gov/155/Fire-Department$t$, $j$[{"url":"https://pomptonlakes-nj.gov/155/Fire-Department","label":"Official source (pomptonlakes-nj.gov)"},{"url":"https://pomptonlakes-nj.gov/m/directory/department?did=9","label":"Official source (pomptonlakes-nj.gov)"},{"url":"https://pomptonlakes-nj.gov/DocumentCenter/View/1577/CCO-Residential-Application","label":"Official source (pomptonlakes-nj.gov)"},{"url":"https://www.pomptonlakes-nj.gov/AgendaCenter/ViewFile/Item/651?fileID=27158","label":"Official source (pomptonlakes-nj.gov)"},{"url":"https://www.nj.gov/dca/divisions/dfs/codes/regulations/adopted_amendment_5_10_2.9.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$Call 973-616-5918 for inspections, permits, CO inspections and Real Estate closing issues$t$, $t$1b55e3161c2daf4ebc5bcd64b4a66379b1b01790e686e71ddb54578415927e65$t$, $t$2026-10-02T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-02","approved_on":"2026-10-02","needs_lookup":false,"flag_reasons":[],"verification":{"fees":7,"fee_ok":7,"fee_bad":0,"fee_unchecked":0,"quotes":17,"q_ok":17,"q_bad":0,"q_unchecked":0},"source":"property/data/municipal-requirements/checked/1609.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-02 and approved in the NJ Resale Certificate Tracker on 2026-10-02. Source: property/data/municipal-requirements/checked/1609.json$t$, true),
  ($t$1610$t$, $t$Prospect Park Borough$t$, $t$PASSAIC$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Certificate of Compliance (for sale)$t$, $j$["Issued by: Borough of Prospect Park Housing Department / Building Department (Code Enforcement), under Borough Code Chapter 90-33","Contact: Nathaniel Hernandez, Housing Inspector / Code Enforcement Officer · (973) 790-7902 .ext 524 · code@prospectpark.net","How to apply: Fill out the Certificate of Compliance Application for Sale (owner, buyer, rooms, signature) and file it with the Building Department at Borough Hall, 106 Brown Avenue, with payment by cash, check or money order. Call for an inspection appointment. Certificate of Occupancy inspections are held Monday 1:30 to 2:30 pm and Tuesday and Thursday 2:00 to 2:30 pm.","Working smoke alarms and carbon monoxide alarms (the Housing Department inspects for both)","Ten-year sealed battery smoke alarms on each floor, including the basement and attic, and within 10 feet of all bedrooms","Battery smoke alarms cannot replace hardwired smoke alarms; hardwired systems must work","Carbon monoxide alarm within 10 feet of all bedrooms (plug-in, battery or combination units); the Housing Department page says one per floor","Fire extinguisher (4 to 10 lb) in every kitchen, wall-mounted no higher than 5 feet above the floor (listed on the fire safety sheet bundled with the 2026 sale form)","Compliance with the Borough's unfit buildings and housing standards ordinances"]$j$::jsonb, $j$[{"label":"Certificate of Compliance inspection, 1 family house","amount":"$75.00"},{"label":"Certificate of Compliance inspection, 2 family house","amount":"$150.00"},{"label":"Certificate of Compliance inspection, 3 family house","amount":"$225.00"},{"label":"Certificate of Compliance application for sale, 1 family / 2 family / 3 family (form)","amount":"$75.00 / $150.00 / 225.00"},{"label":"State online certificate, more than 10 business days before closing (only if the State issues the certificate for Prospect Park; the portal marks the Borough smoke-certificate exempt)","amount":"$45"},{"label":"State online certificate, 4 to 10 business days before closing (same caveat)","amount":"$90"},{"label":"State online certificate, less than 4 business days before closing (same caveat)","amount":"$161"}]$j$::jsonb, $t$https://www.prospectpark.net/Departments/Housing/Certificate%20of%20Compliance%20for%20Sale.pdf$t$, $t$https://www.prospectpark.net/departments/housing_department/index.php$t$, $j$[{"url":"https://www.prospectpark.net/departments/housing_department/index.php","label":"Official source (prospectpark.net)"},{"url":"https://www.prospectpark.net/Departments/Housing/Certificate%20of%20Compliance%20for%20Sale.pdf","label":"Official source (prospectpark.net)"},{"url":"https://www.prospectpark.net/contacts/index.php","label":"Official source (prospectpark.net)"},{"url":"https://firesolutions.dca.nj.gov/ultra-fire-home/smoke-application-create/","label":"Official source (firesolutions.dca.nj.gov)"}]$j$::jsonb, $t$A Certificate of Compliance is required when a house or business is about to be sold. We inspect for working smoke detectors and carbon monoxide detectors. Smoke detectors work best one in every bedroom. Carbon monoxide is required one per floor.$t$, $t$7be56084c73dd4cda514dbd11e758abb88e277230f907fd51173395fce671402$t$, $t$2026-10-02T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-02","approved_on":"2026-10-02","needs_lookup":false,"flag_reasons":[],"verification":{"fees":7,"fee_ok":4,"fee_bad":0,"fee_unchecked":3,"quotes":16,"q_ok":15,"q_bad":0,"q_unchecked":1},"source":"property/data/municipal-requirements/checked/1610.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-02 and approved in the NJ Resale Certificate Tracker on 2026-10-02. Source: property/data/municipal-requirements/checked/1610.json$t$, true),
  ($t$1610$t$, $t$Prospect Park Borough$t$, $t$PASSAIC$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Entire borough: issued by Borough of Prospect Park Housing Department / Building Department (Certificate of Compliance includes the smoke and carbon monoxide alarm inspection)","Entire borough contact: Nathaniel Hernandez, Housing Inspector / Code Enforcement Officer · (973) 790-7902 .ext 524 · code@prospectpark.net","Entire borough, how to apply: Covered by the Borough Certificate of Compliance for sale: file the application for sale with the Building Department and call for an inspection appointment. See the town certificate section for fees.","NJ DCA Division of Fire Safety, Bureau of Fire…: issued by NJ DCA Division of Fire Safety, Bureau of Fire Code Enforcement (State is the fire code enforcing agency) (NJ DCA, state). Covers: Entire borough (State enforces the fire code; whether the State issues resale smoke certificates here is doubtful, see notes)","NJ DCA Division of Fire Safety, Bureau of Fire… contact: Louis Kilmer, Fire Official (NJ Division of Fire Safety) · (609) 633-6132","NJ DCA Division of Fire Safety, Bureau of Fire…, apply: More than 10 business days before closing for the lowest state fee","NJ DCA Division of Fire Safety, Bureau of Fire…, how to apply: For towns where the State issues the certificate, apply online on the DCA Fire Safety portal and pay by e-check or credit card. The portal data flags Prospect Park as smoke-certificate exempt, so confirm with DCA or the Borough before applying there.","Fire official in the NJ state directory (NJ DCA, state), updated 1/12/2026: Louis Kilmer · (609)633-6132","Ten-year sealed battery smoke alarms on each floor, including the basement and attic, and within 10 feet of all bedrooms (Borough sheet)","Carbon monoxide alarm within 10 feet of all bedrooms (Borough sheet)","Fire extinguisher (4 to 10 lb) mounted in the kitchen no higher than 5 feet (still listed on the Borough's 2026 sheet even though the state dropped it from the state certificate in February 2025)","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"NJ DCA Division of Fire Safety, Bureau of Fire…: State online certificate, more than 10 business days before closing (only if the State issues the certificate for Prospect Park; the portal marks the Borough smoke-certificate exempt)","amount":"$45"},{"label":"NJ DCA Division of Fire Safety, Bureau of Fire…: State online certificate, 4 to 10 business days before closing (same caveat)","amount":"$90"},{"label":"NJ DCA Division of Fire Safety, Bureau of Fire…: State online certificate, less than 4 business days before closing (same caveat)","amount":"$161"}]$j$::jsonb, $t$https://www.prospectpark.net/Departments/Housing/Certificate%20of%20Compliance%20for%20Sale.pdf$t$, $t$https://www.prospectpark.net/departments/housing_department/index.php$t$, $j$[{"url":"https://www.prospectpark.net/Departments/Housing/Certificate%20of%20Compliance%20for%20Sale.pdf","label":"Official source (prospectpark.net)"},{"url":"https://firesolutions.dca.nj.gov/_odata/firedistricts","label":"Official source (firesolutions.dca.nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/state_towns%207_17_26.pdf","label":"Official source (nj.gov)"},{"url":"https://www.prospectpark.net/contacts/index.php","label":"Official source (prospectpark.net)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"},{"url":"https://firesolutions.dca.nj.gov/ultra-fire-home/smoke-application-create/","label":"Official source (firesolutions.dca.nj.gov)"}]$j$::jsonb, $t$Chapter 90-33 of the Borough Ordinances requires a certificate of compliance. A certificate of compliance certifying compliance with Borough Ordinances entitled “Buildings, Unfit, and Housing Standards, and inspection of smoke detector & carbon monoxide alarm compliance.$t$, $t$0e97cbd34f189e9d4386954bd16ff5fcda7ddd57a4730eb1f21069fe6427c5d1$t$, $t$2026-10-02T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-02","approved_on":"2026-10-02","needs_lookup":false,"flag_reasons":[],"verification":{"fees":7,"fee_ok":4,"fee_bad":0,"fee_unchecked":3,"quotes":16,"q_ok":15,"q_bad":0,"q_unchecked":1},"source":"property/data/municipal-requirements/checked/1610.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-02 and approved in the NJ Resale Certificate Tracker on 2026-10-02. Source: property/data/municipal-requirements/checked/1610.json$t$, true),
  ($t$1611$t$, $t$Ringwood Borough$t$, $t$PASSAIC$t$, $t$resale_cco$t$, $t$official_process_found$t$, $t$Resale / Continued Certificate of Occupancy (CCO)$t$, $j$["Not required for sales, per Ringwood Building Department. Confirm with the office if the buyer's lender or title company asks.","Issued by: Ringwood Building Department","Contact: Michael Hafner, Construction Official/Building Subcode Official/Zoning Officer/Code Enforcement Officer · 973-962-7880 · building@ringwoodnj.net","Apply: For the optional letter: request in writing and allow ample time before closing","How to apply: No resale certificate is needed. If a closing attorney or lender wants a letter saying no CCO is required, send a written request with a $15.00 payment to the Borough of Ringwood Building Department, 60 Margaret King Avenue, 1st floor.","Also: Open building permits: The fire inspection form's office section asks whether there are open building permits; the Building Department offers a 'Do I Have Any Open Permits?' email link (building@ringwoodnj.net)."]$j$::jsonb, $j$[{"label":"Optional letter stating that a Certificate of Continued Occupancy is not required","amount":"$15.00"},{"label":"More than 10 business days between application and inspection date","amount":"$50.00"},{"label":"Four to 10 business days between application and inspection date","amount":"$85.00"},{"label":"Three business days or less between application and inspection date","amount":"$140.00"},{"label":"Re-inspection: same rate as the initial inspection fee","amount":"$50.00 to $140.00"}]$j$::jsonb, null, $t$https://www.ringwoodnj.net/content/2347/2355/default.aspx$t$, $j$[{"url":"https://ringwoodnj.net/content/2347/2355/14086.aspx","label":"Official source (ringwoodnj.net)"},{"url":"https://www.ringwoodnj.net/content/2347/2355/default.aspx","label":"Official source (ringwoodnj.net)"},{"url":"https://www.ringwoodnj.net/filestorage/2347/20840/Fire_inspection_application_and_instructions_-09-2023_revision.pdf","label":"Official source (ringwoodnj.net)"}]$j$::jsonb, $t$Does Ringwood require a CCO inspection upon resale of a home? No, but you ARE required to have the smoke alarm devices inspected.$t$, $t$e0e8a099cf907f0f061603b8c13b2a14c6d83b53a981f0aadbff9f98496b1b8c$t$, $t$2026-10-02T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-02","approved_on":"2026-10-02","needs_lookup":false,"flag_reasons":[],"verification":{"fees":5,"fee_ok":5,"fee_bad":0,"fee_unchecked":0,"quotes":13,"q_ok":13,"q_bad":0,"q_unchecked":0},"source":"property/data/municipal-requirements/checked/1611.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-02 and approved in the NJ Resale Certificate Tracker on 2026-10-02. Source: property/data/municipal-requirements/checked/1611.json$t$, true),
  ($t$1611$t$, $t$Ringwood Borough$t$, $t$PASSAIC$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Ringwood Fire Prevention Bureau (Borough Fire Official) (town fire bureau)","Contact: Scott Conley, Fire Official · (973) 475-7132 · sconley@ringwoodnj.net","Apply: More than 10 business days between application and inspection for the lowest fee; inspections are on Wednesdays. The certificate is issued on site and is valid for 6 months or until another change of occupancy.","How to apply: Fill out page 1 of the Fire Prevention Bureau application (Application for Change of Residential Occupancy, revised 07/2026) and bring or mail it to the Ringwood Municipal Building, 60 Margaret King Avenue, with the fee in exact cash or a check payable to the Borough of Ringwood. Fees count from the next business day after the application and fee are received. A failed inspection needs a new application and fee.","Fire official in the NJ state directory (town), updated 6/27/2025: Scott R Conley · (973) 475-7132 · sconley@ringwoodnj.net","All smoke alarms must be less than 10 years old and UL listed; battery-only alarms must be sealed 10-year units; NEST battery alarms are not accepted","Homes with 110-volt interconnected smoke alarms must keep that system working and cannot switch to battery alarms","Older homes without hardwired alarms need at least one battery smoke alarm on every level, including the basement and a habitable attic","Any low-voltage fire alarm system must be active and monitored by an alarm company at the inspection","Smoke alarms in the hallway within 10 feet of all bedroom doors; basement alarm within 10 feet of the bottom of the stairs, not in the stairwell","Alarms mounted on the ceiling (or on the wall 4 to 12 inches from the ceiling), at least 4 inches from the wall-ceiling corner and at least 3 feet from steamy bathrooms, ceiling fan blades and HVAC supply vents","Carbon monoxide alarms on every level with sleeping areas, within 10 feet of bedroom doors (not inside bedrooms), less than 7 years old","Homes with solar panels, generators or battery backup need a durable printed label (letters at least 3/8 inch) within 18 inches of the main panel and the outside meter; handwritten labels are not accepted","Fire extinguishers are no longer required","Dogs must be contained when the inspector arrives","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"More than 10 business days between application and inspection date","amount":"$50.00"},{"label":"Four to 10 business days between application and inspection date","amount":"$85.00"},{"label":"Three business days or less between application and inspection date","amount":"$140.00"},{"label":"Re-inspection: same rate as the initial inspection fee","amount":"$50.00 to $140.00"}]$j$::jsonb, $t$https://www.ringwoodnj.net/filestorage/2347/20840/Fire_inspection_application_and_instructions_-09-2023_revision.pdf$t$, $t$https://ringwoodnj.net/content/2347/2355/14098.aspx$t$, $j$[{"url":"https://ringwoodnj.net/content/2347/2355/14098.aspx","label":"Official source (ringwoodnj.net)"},{"url":"https://www.ringwoodnj.net/filestorage/2347/20840/Fire_inspection_application_and_instructions_-09-2023_revision.pdf","label":"Official source (ringwoodnj.net)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$Scott Conley, Fire Official (973) 475-7132; sconley@ringwoodnj.net Office Hours: Wednesdays & Thursdays from 8:30am - 4:30pm$t$, $t$ae7e7d316c81faa087e36fb9f7e0c380852c1fa7557c01be81081892b0eaff15$t$, $t$2026-10-02T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-02","approved_on":"2026-10-02","needs_lookup":false,"flag_reasons":[],"verification":{"fees":5,"fee_ok":5,"fee_bad":0,"fee_unchecked":0,"quotes":13,"q_ok":13,"q_bad":0,"q_unchecked":0},"source":"property/data/municipal-requirements/checked/1611.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-02 and approved in the NJ Resale Certificate Tracker on 2026-10-02. Source: property/data/municipal-requirements/checked/1611.json$t$, true),
  ($t$1612$t$, $t$Totowa Borough$t$, $t$PASSAIC$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Certificate of Sale (Certificate of Re-sale)$t$, $j$["Issued by: Borough of Totowa, Office of the Construction Official (Building Department), under Borough Code Chapter 153-14","Contact: Allan Burghardt, Construction Code Official · (973) 956-1000 ext. 1016 · aburghardt@totowanj.org","Apply: Not stated for the certificate; the Water Department's meter compliance application in the same packet must be filed at least 2 weeks before closing","How to apply: Download the Certificate of Sale packet for 1 or 2 family dwellings from the Borough Forms page, complete the Certificate of Sale application (Office of the Construction Official), the Fire Bureau smoke/CO application and the Water Department meter compliance application, and submit them at the Municipal Complex, 537 Totowa Road, with two checks payable to the Borough of Totowa (one for the resale certificate, one for the fire certificate). Include a survey if available and a clean well test if the home has a private well.","Address clearly marked on the house and mailbox","Smoke alarm on every level and within 10 feet of sleeping areas; carbon monoxide alarm within 10 feet of sleeping areas (Fire Bureau certificate)","Copy of a property survey, if available","Private well: a clean well test (or a letter from both attorneys noting the well's condition)","Check for open permits, illegal construction and illegal 2-family or multi-family use","Gas appliance vents installed properly; water heater, furnace, boiler or stove chimney connection sealed and secure","All meters installed (gas, electric, water); water meter with an external reading device","Water heater pressure relief pipe extends to within 6 inches of the floor","Grip-size handrails on steps with 4 or more risers; guardrails on porches, steps and walkways more than 30 inches above grade","No loose or unprotected wires or open electric boxes; hardwired ground fault receptacle for pools and spas","All required fire separations installed and maintained","Buyers bring photo ID for all adults who will live in the home and birth certificates for minor children","The 2024 packet also lists a portable fire extinguisher (2.5 to 10 lb ABC within 10 feet of the kitchen); the Fire Bureau's current sheet says it is no longer required","Also: Water meter compliance (Water Department): Submit the Water Meter Compliance Application to the Water Department office at 537 Totowa Road at least 2 weeks before closing; a site inspection sets the cost of any required meter upgrade and checks the curb box (Ordinances 407-12, 407-17, 407-25).","Also: Open permits and illegal construction: The Certificate of Sale inspection checks for open permits, illegal construction and illegal 2-family or multi-family use.","Also: Private well test: Homes on private wells must submit a clean well test under the Private Well Testing Act, or a letter from both attorneys noting the well's condition."]$j$::jsonb, $j$[{"label":"Certificate of Re-sale, single family (one of two $100.00 checks: 1 for resale, 1 for the fire certificate)","amount":"$100.00"},{"label":"Certificate of Re-sale, two family (one of two $200.00 checks: 1 for resale, 1 for the fire certificate)","amount":"$200.00"},{"label":"Certificate of Sale application fee, single family / two family (application page)","amount":"$100.00 / $200.00"},{"label":"Fire Bureau smoke detector and carbon monoxide certificate, single family home","amount":"$100.00"},{"label":"Fire Bureau smoke detector and carbon monoxide certificate, two family home","amount":"$200.00"}]$j$::jsonb, $t$https://www.totowanj.org/_files/ugd/3cc0e2_33396db322df4c78b6f0ac77b6b35be5.pdf$t$, $t$https://www.totowanj.org/building$t$, $j$[{"url":"https://www.totowanj.org/_files/ugd/3cc0e2_33396db322df4c78b6f0ac77b6b35be5.pdf","label":"Official source (totowanj.org)"},{"url":"https://www.totowanj.org/forms","label":"Official source (totowanj.org)"},{"url":"https://www.totowanj.org/building","label":"Official source (totowanj.org)"}]$j$::jsonb, $t$Chapter 153-14 of the Borough Ordinances requires that before the occupancy or possession of any building or structure may pass from one person to another, a Certificate of Re-sale is required.$t$, $t$b059278666aa9531f82387d923bd2a4468bf83cd9503e30885fd9c53ec4fa187$t$, $t$2026-10-02T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-02","approved_on":"2026-10-02","needs_lookup":false,"flag_reasons":[],"verification":{"fees":5,"fee_ok":5,"fee_bad":0,"fee_unchecked":0,"quotes":13,"q_ok":13,"q_bad":0,"q_unchecked":0},"source":"property/data/municipal-requirements/checked/1612.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-02 and approved in the NJ Resale Certificate Tracker on 2026-10-02. Source: property/data/municipal-requirements/checked/1612.json$t$, true),
  ($t$1612$t$, $t$Totowa Borough$t$, $t$PASSAIC$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Totowa Fire Prevention Bureau (Fire Bureau, Fire Official / Fire Marshal) (town fire bureau)","Contact: Mark Henry, Fire Official (Fire Marshal) · (973) 956-1000 ext. 1013 · mhenry@totowanj.org","How to apply: Complete the Fire Bureau Application (smoke detector and carbon monoxide) in the Certificate of Sale packet and submit it with a separate check payable to the Borough of Totowa at the Municipal Complex, 537 Totowa Road, 2nd floor. No closing may take place without the completed certificate of inspection.","Fire official in the NJ state directory, updated 1/9/2026: Mark Henry · (973) 956-1000 · mhenry@totowanj.org","One smoke alarm in the basement and on each floor (unfinished attics excluded), and within 10 feet of the outside of bedroom doors","Battery-only smoke alarms must have a 10-year sealed lithium battery (since 1/1/19); all smoke alarms less than 10 years old and UL listed","Existing hardwired smoke or smoke/CO alarms must stay hardwired and cannot be replaced with battery alarms","Carbon monoxide alarm within 10 feet of bedrooms (outside the bedroom), less than 10 years old; CO alarms on all floors recommended","Monitored alarm systems must be tested or serviced first, with a report from the alarm company (detectors under 10 years old) available to the inspector","Fire extinguisher no longer required (per the Fire Bureau sheet); the 2024 Certificate of Sale packet still lists one","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Fire Bureau smoke detector and carbon monoxide certificate, single family home","amount":"$100.00"},{"label":"Fire Bureau smoke detector and carbon monoxide certificate, two family home","amount":"$200.00"}]$j$::jsonb, $t$https://www.totowanj.org/_files/ugd/3cc0e2_33396db322df4c78b6f0ac77b6b35be5.pdf$t$, $t$https://www.totowanj.org/firebureau$t$, $j$[{"url":"https://www.totowanj.org/firebureau","label":"Official source (totowanj.org)"},{"url":"https://www.totowanj.org/_files/ugd/3cc0e2_a477dd8d30d24c48bb42dc404f0d7863.pdf","label":"Official source (totowanj.org)"},{"url":"https://www.totowanj.org/_files/ugd/3cc0e2_33396db322df4c78b6f0ac77b6b35be5.pdf","label":"Official source (totowanj.org)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$Mark Henry, Fire Marshal mhenry@totowanj.org (973) 956-1000 ext. 1013 | fax (973) 956-8159$t$, $t$ccee18589da114d44adc6e5066d9b23f90b559d82f56d2848f847091fdede256$t$, $t$2026-10-02T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-02","approved_on":"2026-10-02","needs_lookup":false,"flag_reasons":[],"verification":{"fees":5,"fee_ok":5,"fee_bad":0,"fee_unchecked":0,"quotes":13,"q_ok":13,"q_bad":0,"q_unchecked":0},"source":"property/data/municipal-requirements/checked/1612.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-02 and approved in the NJ Resale Certificate Tracker on 2026-10-02. Source: property/data/municipal-requirements/checked/1612.json$t$, true),
  ($t$1613$t$, $t$Wanaque Borough$t$, $t$PASSAIC$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Residential resale certificate (Certificate of Smoke Alarm and Carbon Monoxide Alarm Compliance, issued by the Building Department)$t$, $j$["Issued by: Borough of Wanaque Building & Zoning Department","Contact: Jennifer Fiorito, Technical Assistant (Building & Zoning) · 973-839-3000 x 7120 · jennifer@wanaquenj.gov","Apply: Payment must reach the office before the inspection day; inspections are Monday 1pm to 3pm and Wednesday 7am to 9am","How to apply: Call the Building Department at 973-839-3000 x 7120 to schedule, and pay the $200 fee in exact cash or by check made out to 'Wanaque Borough' before the inspection day. Inspections are Monday 1pm to 3pm or Wednesday 7am to 9am with no set appointment time; the certificate is issued at the inspection.","Smoke alarms listed to UL217 on each level, including the basement (not required in attics or crawl spaces), and within 10 feet of any sleeping area","Battery-only smoke alarms must have a 10-year sealed battery; units with changeable batteries are no longer allowed","Existing hardwired (110 volt) smoke alarms must be maintained; any over 10 years old must be replaced before the inspection","Carbon monoxide alarms listed to UL2034 within 10 feet of any bedroom (battery, plug-in or combination); hardwired CO alarms must stay hardwired","Homes with solar panels, a standby generator or battery storage need permanent weatherproof, UV-resistant labels (ANSI Z535.4) within 18 inches of the electrical panel and the meter pan"]$j$::jsonb, $j$[{"label":"Resale certificate application fee (the same single Building Department certificate as the smoke/CO certificate; not charged twice)","amount":"$200"},{"label":"Certificate of smoke alarm and carbon monoxide alarm compliance, application fee (same combined certificate as the town resale certificate; not charged twice)","amount":"$200"}]$j$::jsonb, $t$https://www.wanaqueborough.com/vertical/Sites/%7B685BAF4D-C434-4DFB-94F4-1C8D180E9776%7D/uploads/CCO_Requirements_-_March_2025(1).pdf$t$, $t$https://www.wanaqueborough.com/buildingzoning$t$, $j$[{"url":"https://www.wanaqueborough.com/buildingzoning","label":"Official source (wanaqueborough.com)"},{"url":"https://www.wanaqueborough.com/vertical/Sites/%7B685BAF4D-C434-4DFB-94F4-1C8D180E9776%7D/uploads/CCO_Requirements_-_March_2025(1).pdf","label":"Official source (wanaqueborough.com)"}]$j$::jsonb, $t$This Department also issues Certificates for resale of single-family homes, two-family homes and change of tenancy in rental units.$t$, $t$9c124aa742d36827542dd2326e9fd379b4df4caf5975e2303b575b2233191256$t$, $t$2026-10-02T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-02","approved_on":"2026-10-02","needs_lookup":false,"flag_reasons":[],"verification":{"fees":2,"fee_ok":2,"fee_bad":0,"fee_unchecked":0,"quotes":9,"q_ok":9,"q_bad":0,"q_unchecked":0},"source":"property/data/municipal-requirements/checked/1613.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-02 and approved in the NJ Resale Certificate Tracker on 2026-10-02. Source: property/data/municipal-requirements/checked/1613.json$t$, true),
  ($t$1613$t$, $t$Wanaque Borough$t$, $t$PASSAIC$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Wanaque Building Department (Construction Office), which issues the smoke alarm and carbon monoxide alarm certificate (town fire bureau)","Contact: Jennifer Fiorito, Technical Assistant (Building & Zoning) · 973-839-3000 x 7120 · jennifer@wanaquenj.gov","Apply: Pay before the inspection day; the certificate is issued at the inspection","How to apply: Call 973-839-3000 x 7120 to schedule and pay $200 in exact cash or by check to 'Wanaque Borough' before the inspection day.","Fire official in the NJ state directory, updated 1/12/2026: Kevin L Platt · (973) 831-9752 · wfpb@optonline.net","Smoke alarms listed to UL217 on each level, including the basement (not required in attics or crawl spaces), and within 10 feet of any sleeping area","Battery-only smoke alarms must have a 10-year sealed battery; units with changeable batteries are no longer allowed","Existing hardwired (110 volt) smoke alarms must be maintained; any over 10 years old must be replaced before the inspection","Carbon monoxide alarms listed to UL2034 within 10 feet of any bedroom (battery, plug-in or combination); hardwired CO alarms must stay hardwired","Homes with solar panels, a standby generator or battery storage need permanent weatherproof, UV-resistant labels (ANSI Z535.4) within 18 inches of the electrical panel and the meter pan","The March 2025 Borough sheet does not list a fire extinguisher","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Certificate of smoke alarm and carbon monoxide alarm compliance, application fee (same combined certificate as the town resale certificate; not charged twice)","amount":"$200"}]$j$::jsonb, $t$https://www.wanaqueborough.com/vertical/Sites/%7B685BAF4D-C434-4DFB-94F4-1C8D180E9776%7D/uploads/CCO_Requirements_-_March_2025(1).pdf$t$, $t$https://www.wanaqueborough.com/buildingzoning$t$, $j$[{"url":"https://www.wanaqueborough.com/vertical/Sites/%7B685BAF4D-C434-4DFB-94F4-1C8D180E9776%7D/uploads/CCO_Requirements_-_March_2025(1).pdf","label":"Official source (wanaqueborough.com)"},{"url":"https://www.wanaqueborough.com/buildingzoning","label":"Official source (wanaqueborough.com)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$CERTIFICATE OF SMOKE ALARM and CARBON MONOXIDE ALARM COMPLIANCE$t$, $t$e08b4703f9e0186563d347856f16bb7b7f053a10ecaadb959790b7a96b5d274c$t$, $t$2026-10-02T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-02","approved_on":"2026-10-02","needs_lookup":false,"flag_reasons":[],"verification":{"fees":2,"fee_ok":2,"fee_bad":0,"fee_unchecked":0,"quotes":9,"q_ok":9,"q_bad":0,"q_unchecked":0},"source":"property/data/municipal-requirements/checked/1613.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-02 and approved in the NJ Resale Certificate Tracker on 2026-10-02. Source: property/data/municipal-requirements/checked/1613.json$t$, true),
  ($t$1615$t$, $t$West Milford Township$t$, $t$PASSAIC$t$, $t$resale_cco$t$, $t$official_process_found$t$, $t$Resale / Continued Certificate of Occupancy (CCO)$t$, $j$["Not required for sales, per West Milford Building Department. Confirm with the office if the buyer's lender or title company asks.","Issued by: West Milford Building Department","Contact: Adam Slufik, Construction Official, Building Inspector · 973-728-2725","Apply: For the optional letter: request in writing and allow ample time before closing","How to apply: No resale certificate is needed. If a letter confirming that is wanted, send a written request with the $40 fee to the Building Department, 1480 Union Valley Road."]$j$::jsonb, $j$[{"label":"Optional letter stating that a Certificate of Continued Occupancy is not required","amount":"$40"},{"label":"Certification requested more than 10 business days before closing","amount":"$55.00"},{"label":"Certification requested 4 to 10 business days before closing","amount":"$100.00"},{"label":"Certification requested less than 4 business days before closing","amount":"$165.00"},{"label":"Re-inspection (additional fee)","amount":"$50.00"}]$j$::jsonb, null, $t$https://westmilford.org/cn/faq/?did=435$t$, $j$[{"url":"https://westmilford.org/cn/faq/?did=435","label":"Official source (westmilford.org)"},{"url":"https://westmilford.org/cn/contactinfo/?did=435","label":"Official source (westmilford.org)"},{"url":"https://westmilford.org/FCpdf/Smoke%20Detector%20instructions%2D2%2D26%2D25%2Epdf","label":"Official source (westmilford.org)"}]$j$::jsonb, $t$Does West Milford require an inspection on resale of a home? No. We do not require a Certificate of Continued Occupancy on the resale of home. A Smoke Detector Certification is required and is performed by the Fire Prevention Department; Please call 973-728-2840 to schedule an appointment.$t$, $t$d1ce409b75922ee121dae2ded40a7b1005d908af694674163fd6083fa9928ae4$t$, $t$2026-10-02T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-02","approved_on":"2026-10-02","needs_lookup":false,"flag_reasons":[],"verification":{"fees":5,"fee_ok":5,"fee_bad":0,"fee_unchecked":0,"quotes":12,"q_ok":12,"q_bad":0,"q_unchecked":0},"source":"property/data/municipal-requirements/checked/1615.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-02 and approved in the NJ Resale Certificate Tracker on 2026-10-02. Source: property/data/municipal-requirements/checked/1615.json$t$, true),
  ($t$1615$t$, $t$West Milford Township$t$, $t$PASSAIC$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: West Milford Fire Prevention Bureau (Office of the Fire Marshal) (town fire bureau)","Contact: Michael Moscatello, Fire Marshal / Fire Investigator (Fire Official) · 973-728-2840 · fireoffice2@westmilford.org","Apply: More than 10 business days before closing for the lowest fee; certifications are done on Wednesdays, 9:00 a.m. to 3:30 p.m. Certificates are valid 6 months from issue and are not transferable.","How to apply: Apply through the Fire Prevention citizen services portal ('Apply for a Smoke Detector Cert', registration required) or call the Fire Prevention Bureau at 973-728-2840 to schedule; the office is at 13 Edgar Drive. Checks are payable to the Township of West Milford Fire Marshal. Scheduling hours are 8:30 a.m. to 4:30 p.m., Monday through Friday.","Fire official in the NJ state directory (town), updated 1/12/2026: Michael J Moscatello · (973) 728-2840 · fireoffice2@westmilford.org","Minimum 4-inch house numbers visible from the street (Township Ordinance 2009-021); no certificate without them","Smoke and CO alarms must be UL listed, less than 10 years old, and tested by the owner or agent before the inspection","Single-station battery smoke alarms must be 10-year sealed units; existing hardwired alarms must work and cannot be replaced with battery alarms","Hardwired requirements by build date: before 1977 sealed battery alarms on each level; 1977 to Feb 21, 1983 hardwired on sleeping levels and basement; Feb 22, 1983 to Apr 30, 1993 interconnected hardwired on every level; May 1, 1993 and later also inside every bedroom","Smoke alarm on each level within 10 feet of every bedroom door; basement alarm on the ceiling within 3 feet of the stairwell; wall-mounted alarms 6 to 12 inches below the ceiling; cathedral ceilings need an alarm within 12 inches of the peak","CO alarms required with any fuel-burning appliance, fireplace, woodstove or attached garage, centrally outside each sleeping area within 10 feet of every bedroom door (UL 2034)","A central-station monitored fire alarm installed at construction must be kept working; an NFPA 72 test report and proof of monitoring are required","Homes with solar, a backup generator or battery storage need a durable label (for example 'CAUTION: MULTIPLE SOURCES OF POWER') within 18 inches of the main panel and the meter","Fire extinguishers no longer required (since February 3, 2025)","Units opening onto a common hallway (for example Bald Eagle Commons) need working self-closers","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Certification requested more than 10 business days before closing","amount":"$55.00"},{"label":"Certification requested 4 to 10 business days before closing","amount":"$100.00"},{"label":"Certification requested less than 4 business days before closing","amount":"$165.00"},{"label":"Re-inspection (additional fee)","amount":"$50.00"}]$j$::jsonb, $t$https://westmilfordfireprevention.prophoenix.com/Default.aspx$t$, $t$https://westmilford.org/cn/webpage.cfm?tpid=16166$t$, $j$[{"url":"https://westmilford.org/cn/webpage.cfm?tpid=16166","label":"Official source (westmilford.org)"},{"url":"https://westmilford.org/FCpdf/Smoke%20Detector%20instructions%2D2%2D26%2D25%2Epdf","label":"Official source (westmilford.org)"},{"url":"https://westmilford.org/cn/contactinfo/?did=435","label":"Official source (westmilford.org)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$The public can apply for a certificate of smoke alarm and carbon monoxide alarm compliance inspections, apply for permits, make payments, file complaints, by registering for the citizen services account by clicking the link below.$t$, $t$19bdcd222a27b015deede6e3d0b47586510b2dd8cc70c481d24cd990ed5a48f5$t$, $t$2026-10-02T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-02","approved_on":"2026-10-02","needs_lookup":false,"flag_reasons":[],"verification":{"fees":5,"fee_ok":5,"fee_bad":0,"fee_unchecked":0,"quotes":12,"q_ok":12,"q_bad":0,"q_unchecked":0},"source":"property/data/municipal-requirements/checked/1615.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-02 and approved in the NJ Resale Certificate Tracker on 2026-10-02. Source: property/data/municipal-requirements/checked/1615.json$t$, true),
  ($t$1616$t$, $t$Woodland Park Borough$t$, $t$PASSAIC$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Residential Resale Continued Certificate of Occupancy / Dwelling Certificate$t$, $j$["Issued by: Borough of Woodland Park Department of Inspections (Code Enforcement / Construction Code Enforcing Agency), under Borough Ordinances 14-14 and 22-50.2","Contact: Allan Burghardt, Construction Code Official/Bldg. Subcode Official/Bldg. Inspector/Code Enforcement Officer/Zoning Official · 973-345-8100 ext. 103 · aburghardt@wpnj.us","Apply: Inspections are Monday to Friday, 10 am to 12 pm once the paperwork is complete; the water meter compliance application must reach the Water office at least 2 weeks before closing","How to apply: Download the Residential Resale packet from the Borough's Residential C.O. Forms page. Fill out the resale application and the Dwelling Certificate listing all occupants with photo IDs, file the Water Meter Compliance Application with the Water office at 5 Brophy Lane at least 2 weeks before closing, and file the separate Fire Prevention application. Pay with two separate checks payable to the Borough of Woodland Park (one for the certificate of occupancy, one for fire), or cash; no debit or credit cards. Call Code Enforcement at 973-345-8100 ext 103 for the inspection.","Walkways not broken or lifted; exterior stairs in good condition with handrails; interior stairs with handrails","Roof, gutters and leaders in good condition; exterior paint at least fair; no broken window glass","Street number posted on or close to the door","Garbage removed, overgrowth cut back, no unregistered vehicles or car parts stored on the property","Smoke detectors on each level and within 10 feet of bedrooms; carbon monoxide detectors within 10 feet of bedrooms (separate Fire Prevention certificate required first)","Dead bolts on exterior doors must have inside thumb latches (no double-keyed locks)","Basement kitchens or bathrooms built without a permit must be removed","Plumbing waste and supply lines in good condition and not leaking; sump pump must drain outside, not into the sewer","Heating equipment and water heaters properly vented into the chimney; water heater relief valve extension to within 12 inches of the floor","Septic systems: a licensed professional must certify the system works and meets DEP rules (resale only)","Open permits must be closed out before the certificate is issued","Water meter compliance sign-off from DPW (wireless reading meter if on Woodland Park water)","Photo ID of the buyer and a list of all occupants (Dwelling Certificate) with IDs","The 2026 checklist still says fire extinguishers are required to meet NJ Division of Fire Safety rules","Also: Water meter compliance (DPW sign-off): File the Water Meter Compliance Application at the Water office, 5 Brophy Lane, at least 2 weeks before closing; homes on Woodland Park water need wireless meter reading, and DPW sign-off must be shown to Code Enforcement before the certificate is granted (DPW 973-256-1264).","Also: Open permits: Any open permits must be closed out and inspected before the certificate of occupancy is issued.","Also: Septic certification (resale only): A licensed professional must certify that a septic system works properly and meets DEP requirements."]$j$::jsonb, $j$[{"label":"Residential resale certificate, one-family (resale application form, 2026)","amount":"$100.00"},{"label":"Residential resale certificate, two-family (resale application form, 2026; the procedures sheet in the same packet says $100.00 for a one- or two-family resale)","amount":"$200.00"},{"label":"Resale of a one- or two-family home (procedures and fees sheet in the same packet)","amount":"$ 100.00"},{"label":"Multi-family (3 or more units) resale, per unit","amount":"$100.00"},{"label":"Inspection more than 10 business days after the application and payment are received (a failed inspection needs a new application and another $50.00)","amount":"$50.00"},{"label":"Inspection within 4 to 10 business days after the application and payment are received (one free re-inspection)","amount":"$100.00"},{"label":"Inspection within 4 business days after the application and payment are received (one free re-inspection)","amount":"$150.00"}]$j$::jsonb, $t$https://wpnj.us/filestorage/485/2229/WP-Residential-CO-Resale-2026-03.pdf$t$, $t$https://wpnj.us/building$t$, $j$[{"url":"https://wpnj.us/filestorage/485/2229/WP-Residential-CO-Resale-2026-03.pdf","label":"Official source (wpnj.us)"},{"url":"https://wpnj.us/filestorage/485/2229/WP-Residential-CO-Application-Process-2026.pdf","label":"Official source (wpnj.us)"},{"url":"https://wpnj.us/building","label":"Official source (wpnj.us)"},{"url":"https://wpnj.us/content/80/403/417/default.aspx","label":"Official source (wpnj.us)"},{"url":"https://wpnj.us/filestorage/169/2877/WP-Fire-Prevention-Application-For-Permit-1-Or-2-Family-Dwelling.pdf","label":"Official source (wpnj.us)"}]$j$::jsonb, $t$Continued Certificate of Occupancy /Dwelling Certificate Pursuant to Borough Ordinances 22-50.2 & 14.14 RESIDENTIAL RESALE$t$, $t$ff3320de10839b6b79bb24fbd6ec86faf16b9a904d4bca27cff66468510afb46$t$, $t$2026-10-02T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-02","approved_on":"2026-10-02","needs_lookup":false,"flag_reasons":[],"verification":{"fees":7,"fee_ok":7,"fee_bad":0,"fee_unchecked":0,"quotes":16,"q_ok":16,"q_bad":0,"q_unchecked":0},"source":"property/data/municipal-requirements/checked/1616.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-02 and approved in the NJ Resale Certificate Tracker on 2026-10-02. Source: property/data/municipal-requirements/checked/1616.json$t$, true),
  ($t$1616$t$, $t$Woodland Park Borough$t$, $t$PASSAIC$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Woodland Park Bureau of Fire Prevention (Fire Official) (town fire bureau)","Contact: Michael Muccio, Fire Official (Administrator of the Woodland Park Bureau of Fire Prevention) · (973) 345-8100 x106 · fireprevention@wpnj.us","Apply: Fee tier depends on how soon after the application and payment the inspection is held: more than 10 business days ($50), 4 to 10 business days ($100), within 4 business days ($150). The certificate is issued at the inspection if it passes.","How to apply: Fill out the Application for One-Two Family Dwelling for Certificate of Smoke Alarm Carbon Monoxide Alarm Compliance, pick the fee tier, and submit it with full payment (check payable to the Borough of Woodland Park) to the Bureau of Fire Prevention, Municipal Building basement level, 5 Brophy Lane (elevator access only). The Bureau calls the person listed on the application to schedule. Office hours are Monday to Thursday, 8:30 AM to 4:30 PM; closed Fridays.","Fire official in the NJ state directory, updated 8/13/2025: Michael J Muccio · (973) 345-3899 · fireprevention@wpnj.us","Battery smoke alarms must be 10-year sealed units (since 1/1/2019); hardwired 110V smoke alarms and CO alarms no more than 10 years old","Hardwired interconnected smoke alarms must work and cannot be replaced by battery alarms; alarm systems with a keypad need the code and monitoring company number at the inspection","Smoke and CO alarms on all floors with sleeping areas (including the basement), within 10 feet of sleeping areas; smoke alarms at least 4 inches from the wall or ceiling","Bedrooms directly off the kitchen need the alarm inside the bedroom, not in the kitchen","CO alarm on any level with an attached garage or a gas-fired device (stove, boiler, dryer, fireplace)","Homes with a secondary power source need 'CAUTION: MULTIPLE SOURCES OF POWER' marking within 18 inches of the main panel and electric meter","Someone over 18 must be present; the full fee is due with the application before an inspection is scheduled","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Inspection more than 10 business days after the application and payment are received (a failed inspection needs a new application and another $50.00)","amount":"$50.00"},{"label":"Inspection within 4 to 10 business days after the application and payment are received (one free re-inspection)","amount":"$100.00"},{"label":"Inspection within 4 business days after the application and payment are received (one free re-inspection)","amount":"$150.00"}]$j$::jsonb, $t$https://wpnj.us/filestorage/169/2877/WP-Fire-Prevention-Application-For-Permit-1-Or-2-Family-Dwelling.pdf$t$, $t$https://wpnj.us/fire$t$, $j$[{"url":"https://wpnj.us/fire","label":"Official source (wpnj.us)"},{"url":"https://wpnj.us/filestorage/169/2877/WP-Fire-Prevention-Application-For-Permit-1-Or-2-Family-Dwelling.pdf","label":"Official source (wpnj.us)"},{"url":"https://wpnj.us/content/80/403/417/default.aspx","label":"Official source (wpnj.us)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$To schedule a dwelling inspection due to a sale or re-rental, complete the form below, picking the fee level you wish to pay$t$, $t$6382385349dc77486f553f36a74c31a8f73bd39533ff86638f48a1d3c4886590$t$, $t$2026-10-02T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-02","approved_on":"2026-10-02","needs_lookup":false,"flag_reasons":[],"verification":{"fees":7,"fee_ok":7,"fee_bad":0,"fee_unchecked":0,"quotes":16,"q_ok":16,"q_bad":0,"q_unchecked":0},"source":"property/data/municipal-requirements/checked/1616.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-02 and approved in the NJ Resale Certificate Tracker on 2026-10-02. Source: property/data/municipal-requirements/checked/1616.json$t$, true),
  ($t$2001$t$, $t$Berkeley Heights Township$t$, $t$UNION$t$, $t$resale_cco$t$, $t$official_process_found$t$, $t$Resale / Continued Certificate of Occupancy (CCO)$t$, $j$["Not required for sales, per Berkeley Heights Township. Confirm with the office if the buyer's lender or title company asks.","Contact: Joe Popolo, Construction Official, Fire Official · 908-464-2700 x2138 · jpopolo@bhtwp.com","How to apply: No Township certificate of occupancy is needed to sell a home. The seller needs only the fire certificate (smoke alarm, carbon monoxide alarm and fire extinguisher certificate of approval) from the Fire Prevention Bureau before closing."]$j$::jsonb, $j$[]$j$::jsonb, null, $t$https://www.berkeleyheights.gov/156/Building$t$, $j$[{"url":"https://www.berkeleyheights.gov/Faq.aspx?QID=80","label":"Official source (berkeleyheights.gov)"},{"url":"https://library.municode.com/nj/berkeley_heights_township/codes/code_of_ordinances?nodeId=TIT15BUCO_CH15.32CECOOCNOPR","label":"Official source (library.municode.com)"},{"url":"https://www.berkeleyheights.gov/156/Building","label":"Official source (berkeleyheights.gov)"}]$j$::jsonb, $t$The Township of Berkeley Heights does NOT require a CO (Certificate of Occupancy) prior to selling your home.$t$, $t$cbbeabcf03740c18adfb6d18a7b129f298fda90ff6d891846461f0eff66c4410$t$, $t$2026-10-02T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-02","approved_on":"2026-10-02","needs_lookup":false,"flag_reasons":[],"verification":{"fees":3,"fee_ok":3,"fee_bad":0,"fee_unchecked":0,"quotes":15,"q_ok":15,"q_bad":0,"q_unchecked":0},"source":"property/data/municipal-requirements/checked/2001.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-02 and approved in the NJ Resale Certificate Tracker on 2026-10-02. Source: property/data/municipal-requirements/checked/2001.json$t$, true),
  ($t$2001$t$, $t$Berkeley Heights Township$t$, $t$UNION$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Berkeley Heights Fire Prevention Bureau (Township Bureau of Fire Prevention) (town fire bureau)","Contact: Joe Popolo, Construction Official, Fire Official · 908-464-0800 ext. 13 · jpopolo@bhtwp.com","Apply: Apply more than 10 business days before the change of occupant for the lowest fee. Inspections are Tuesday and Thursday, 9 a.m. to noon. The certificate is valid for 6 months from the date of issue.","How to apply: Fill out the Application for Carbon Monoxide / Smoke Detector Fire Extinguisher Certificate of Approval (PDF on the Township Forms page, or pick one up from the Township Clerk at the Municipal Building, 29 Park Avenue), pay the fee and schedule the inspection. The Township also lists an online Form Center version. One re-inspection is allowed per application after a failure. To cancel, call 908-464-2700 ext. 1 at least 48 hours ahead.","Fire official in the NJ state directory, updated 1/7/2026: Joseph Popolo · (908) 464-0800 · jpopolo@bhtwp.com","Smoke alarms on each level including basements (not crawl spaces or attics without habitable space), and outside each separate sleeping area","All smoke alarms must be listed to UL 217, in working order and less than 10 years old","Battery-only smoke alarms must be 10-year sealed battery units (since January 1, 2019)","Homes built or altered after 1977 with AC powered or interconnected alarms must keep them working; they cannot be replaced with battery units","Two-family homes also need a smoke alarm at the highest level of each common stairwell","Carbon monoxide alarm outside the sleeping area, within 10 feet of bedroom doors, if the home has a fuel-burning appliance, a fireplace or an attached garage","Alarms must be mounted securely; double-sided tape is not allowed","Fire extinguisher (still listed on the 2019 Township form): one ABC extinguisher, 2A:10BC to 10 pounds, on its bracket within 10 feet of the kitchen, top no more than 5 feet above the floor, with the owner's manual; a new extinguisher needs proof of purchase","Required fire protection systems such as sprinklers must stay fully working","The owner or the owner's representative must be at the home for the inspection","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Smoke alarm, carbon monoxide alarm and fire extinguisher certificate, request received more than 10 business days before change of occupant","amount":"$45.00"},{"label":"Request received 4 to 10 business days before change of occupant","amount":"$90.00"},{"label":"Request received fewer than 4 business days before change of occupant","amount":"$161.00"}]$j$::jsonb, $t$https://www.berkeleyheights.gov/DocumentCenter/View/832/Property-Fire-Inspection-Required-for-Change-of-Occupancy$t$, $t$http://www.berkeleyheightsfire.com/fire-dept.html$t$, $j$[{"url":"https://www.berkeleyheights.gov/DocumentCenter/View/832/Property-Fire-Inspection-Required-for-Change-of-Occupancy","label":"Official source (berkeleyheights.gov)"},{"url":"http://www.berkeleyheightsfire.com/images/pdf/SmokeDetInspectionRequirmentsNew.pdf","label":"Official source (berkeleyheightsfire.com)"},{"url":"https://www.berkeleyheights.gov/171/Forms-Permits-Licenses","label":"Official source (berkeleyheights.gov)"},{"url":"https://www.berkeleyheights.gov/156/Building","label":"Official source (berkeleyheights.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$A Certificate of Smoke Detector, Carbon Monoxide Alarm and Fire Extinguisher Compliance (CSDCMAFEC) is required before any "Use Group R-3 or R-4" dwelling unit is sold, leased or otherwise made subject to change of occupancy for residential purposes.$t$, $t$46aafdea02e70d5e96f6b5d7bf0add3a2cd471d1000942400244790d6c93100a$t$, $t$2026-10-02T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-02","approved_on":"2026-10-02","needs_lookup":false,"flag_reasons":[],"verification":{"fees":3,"fee_ok":3,"fee_bad":0,"fee_unchecked":0,"quotes":15,"q_ok":15,"q_bad":0,"q_unchecked":0},"source":"property/data/municipal-requirements/checked/2001.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-02 and approved in the NJ Resale Certificate Tracker on 2026-10-02. Source: property/data/municipal-requirements/checked/2001.json$t$, true),
  ($t$2002$t$, $t$Clark Township$t$, $t$UNION$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Certificate of Resale (online Certificate of Compliance application)$t$, $j$["Issued by: Clark Township Construction Department","Contact: Art Figueiredo, Construction Official / Building Subcode Official / Zoning Officer · 732-428-8401 · afigueiredo@ourclark.com","How to apply: Complete the Township's online Certificate of Resale (Certificate of Compliance) application and pay online, attaching a current survey. Then call the Construction Department at 732-428-8401 to schedule the inspection. Residential sellers must also file the separate online Smoke Detector Inspection form.","Valid for: 180 days from the date of issuance","A current survey must be submitted with the application","The owner certifies the home and all other structures on the lot meet Township zoning","No rubbish, debris or bulk garbage may be left on the property before the new occupancy","List any deck, fence, shed, pool, garage or finished basement on the application","Smoke alarms by year built: before 1984 on all levels and outside each sleeping area (battery alarms OK); 1984 to 1990 also interconnected; after 1990 on all levels and in each bedroom, interconnected, with battery backup","Carbon monoxide alarms (UL 2034 listed) near each sleeping area","No door locks that need a key to get out","House numbers at least 3 inches high, contrasting color, readable from the curb","Fire extinguisher: at least 5 lb ABC dry chemical in the kitchen area (listed on the resale application)","A separate Smoke Detector Inspection application and fee are also required for residential properties","Also: Current survey: All Certificate of Resale (Certificate of Compliance) applications require a current survey.","Also: No debris at new occupancy: The owner attests no rubbish, debris or bulk garbage will be left on the property before the new occupancy, or the certificate can be retracted and a summons issued."]$j$::jsonb, $j$[{"label":"Certificate of Resale, residential resale","amount":"$125"},{"label":"Smoke Detector Inspection, per unit","amount":"$50"},{"label":"Reinspection after a failed inspection","amount":"$25.00"}]$j$::jsonb, $t$https://main.govpilot.com/web/public/26a4b45a-ab7_Certificate-of-Compliance-Township-of-Clark?uid=7353&ust=NJ&pu=1&id=0$t$, $t$https://www.ourclark.com/330/Residential-Housing$t$, $j$[{"url":"https://www.ourclark.com/330/Residential-Housing","label":"Official source (ourclark.com)"},{"url":"https://main.govpilot.com/web/public/26a4b45a-ab7_Certificate-of-Compliance-Township-of-Clark?uid=7353&ust=NJ&pu=1&id=0","label":"Official source (main.govpilot.com)"},{"url":"https://www.ourclark.com/152/Construction","label":"Official source (ourclark.com)"},{"url":"https://main.govpilot.com/web/public/5e7a16db-78f_Smoke-and-CO-Inspection-Township-of-Clark?uid=7353&ust=NJ&pu=1&id=0","label":"Official source (main.govpilot.com)"}]$j$::jsonb, $t$Residential, industrial or commercial properties must secure a Certificate of Resale before sale of the property.$t$, $t$ddf3927c83e3fa18192ffe4dd7bb38581d8eb0a13116030892057e021240c831$t$, $t$2026-10-02T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-02","approved_on":"2026-10-02","needs_lookup":false,"flag_reasons":[],"verification":{"fees":3,"fee_ok":3,"fee_bad":0,"fee_unchecked":0,"quotes":17,"q_ok":17,"q_bad":0,"q_unchecked":0},"source":"property/data/municipal-requirements/checked/2002.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-02 and approved in the NJ Resale Certificate Tracker on 2026-10-02. Source: property/data/municipal-requirements/checked/2002.json$t$, true),
  ($t$2002$t$, $t$Clark Township$t$, $t$UNION$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Clark Township Fire Prevention (Code Enforcement Office), Smoke and CO Inspection (town fire bureau)","Contact: Frank J Cerasa, Fire Official · 732-381-1158","How to apply: Complete the Township's online Smoke and CO Inspection form and pay online (the form says a Certificate of Resale must also be filed). After the alarms meet the requirements, call the Code Enforcement Office at 732-381-1158 for an appointment. The same form also tells applicants to call the Construction Department at 732-428-8401 to schedule an inspection.","Fire official in the NJ state directory, updated 1/12/2026: Frank J Cerasa · (732) 904-7251 · fcerasa@comcast.net","Smoke alarms by year built: before 1984 on all levels and outside each sleeping area (battery alarms OK); 1984 to 1990 interconnected; after 1990 on all levels and in each bedroom, interconnected, with battery backup","Carbon monoxide alarms listed to UL 2034 in the immediate vicinity of each sleeping area (battery alarms OK)","Front door locks that need a key to exit must be replaced before the inspection","House numbers at least 3 inches high, contrasting, readable from the curb","A Certificate of Resale must also be filed","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Smoke Detector Inspection, per unit","amount":"$50"},{"label":"Reinspection after a failed inspection","amount":"$25.00"}]$j$::jsonb, $t$https://main.govpilot.com/web/public/5e7a16db-78f_Smoke-and-CO-Inspection-Township-of-Clark?uid=7353&ust=NJ&pu=1&id=0$t$, $t$https://www.ourclark.com/330/Residential-Housing$t$, $j$[{"url":"https://main.govpilot.com/web/public/5e7a16db-78f_Smoke-and-CO-Inspection-Township-of-Clark?uid=7353&ust=NJ&pu=1&id=0","label":"Official source (main.govpilot.com)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$PLEASE NOTE: YOU MUST ALSO FILE A CERTIFICATE OF RESALE.$t$, $t$e06b8bb0c7382f229e469a4360d1b1de8355dd5e266aac3f7b9060c6253bba7d$t$, $t$2026-10-02T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-02","approved_on":"2026-10-02","needs_lookup":false,"flag_reasons":[],"verification":{"fees":3,"fee_ok":3,"fee_bad":0,"fee_unchecked":0,"quotes":17,"q_ok":17,"q_bad":0,"q_unchecked":0},"source":"property/data/municipal-requirements/checked/2002.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-02 and approved in the NJ Resale Certificate Tracker on 2026-10-02. Source: property/data/municipal-requirements/checked/2002.json$t$, true),
  ($t$2003$t$, $t$Cranford Township$t$, $t$UNION$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Certificate of Continued Occupancy (CCO)$t$, $j$["Issued by: Cranford Fire Department, Bureau of Fire Prevention & Risk Management","Contact: Matthew Lubin, Battalion Chief/Fire Official · 908-709-7360 · m-lubin@cranfordnj.org","Apply: Not stated. Give at least two requested inspection dates; inspections are between 4 and 5 p.m. on business days and are confirmed by the office.","How to apply: Apply online through the Township's SDL Portal (a free account is needed): choose Certificate of Continued Occupancy under Online Requests, enter the property, put at least two requested inspection dates in the comments, and pay through the portal. Or fill out the paper CCO application (June 2025 form) and leave it with payment in the drop box at the Fire Department, 7 Springfield Avenue. Checks are payable to Township of Cranford; major credit cards are accepted with a fee. The certificate can be picked up, emailed or mailed.","Ten-year sealed battery or hardwired interconnected smoke alarms on each level and in the bedroom area, including basements and finished attics","Carbon monoxide detection in all sleeping areas, and wherever the home has a fuel-burning furnace or boiler or an attached garage","House numbers clearly visible from the street, securely fastened, weatherproof and on a contrasting background (a sign within 25 feet of the street if the house is set back more than 150 feet)","Sump pumps must discharge to a storm sewer or the street gutter line, never into the sanitary sewer","Homes with a generator, solar panels, battery storage or other secondary power source need a printed (not handwritten) label within 18 inches of the main electrical panel and the electric meter","All building permits must be closed (final inspections through the Building Department) before the certificate is issued","Buildings must comply with zoning for their area","Also: Open building permits: All building permits must be closed by scheduling final inspections with the Building Department, (908) 709-7213, before the CCO is issued.","Also: Sump pump discharge: Sump pumps must discharge to a storm sewer or the street gutter, not the sanitary sewer; Engineering Department (908) 709-7218.","Also: Zoning compliance: Buildings must comply with the zoning for their area."]$j$::jsonb, $j$[{"label":"Certificate of Continued Occupancy, sale of home (includes the smoke and carbon monoxide inspection)","amount":"$100"},{"label":"Certificate of Continued Occupancy application fee, resale / conveyance of ownership (fee notice effective June 10, 2025)","amount":"$100"},{"label":"Certificate of Continued Occupancy application fee (Code Section 223-10 D, Ordinance 2025-07)","amount":"$100"},{"label":"Smoke and carbon monoxide certificate, included in the Certificate of Continued Occupancy fee for a sale","amount":"$100"}]$j$::jsonb, $t$https://www.cranfordnj.org/DocumentCenter/View/929/cco_application_3$t$, $t$https://www.cranfordnj.org/2066/Fire-Department$t$, $j$[{"url":"https://www.cranfordnj.org/DocumentCenter/View/929/cco_application_3","label":"Official source (cranfordnj.org)"},{"url":"https://www.cranfordnj.org/DocumentCenter/View/919/fire_prevention_fee_increase_notice_06042025","label":"Official source (cranfordnj.org)"},{"url":"https://www.cranfordnj.org/DocumentCenter/View/915/cco_requirement_sheet_0","label":"Official source (cranfordnj.org)"},{"url":"https://www.cranfordnj.org/DocumentCenter/View/927/submit_your_cco_application_online_rev_0121","label":"Official source (cranfordnj.org)"},{"url":"https://www.cranfordnj.org/2066/Fire-Department","label":"Official source (cranfordnj.org)"},{"url":"https://www.cranfordnj.org/Directory.aspx?EID=233","label":"Official source (cranfordnj.org)"}]$j$::jsonb, $t$APPLICATION FOR CERTIFICATE OF CONTINUED OCCUPANCY [ ] Sale of Home [ ] Change of Tenant (Rental)$t$, $t$35a10bd36d0d87946b74e15e47bba59d5047ccdaf73c39db59139663fdc0ae68$t$, $t$2026-10-02T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-02","approved_on":"2026-10-02","needs_lookup":false,"flag_reasons":[],"verification":{"fees":4,"fee_ok":4,"fee_bad":0,"fee_unchecked":0,"quotes":17,"q_ok":17,"q_bad":0,"q_unchecked":0},"source":"property/data/municipal-requirements/checked/2003.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-02 and approved in the NJ Resale Certificate Tracker on 2026-10-02. Source: property/data/municipal-requirements/checked/2003.json$t$, true),
  ($t$2003$t$, $t$Cranford Township$t$, $t$UNION$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Cranford Fire Department, Bureau of Fire Prevention & Risk Management (town fire bureau)","Contact: Matthew Lubin, Battalion Chief/Fire Official · 908-709-7360 · m-lubin@cranfordnj.org","Apply: Not stated. Inspections are between 4 and 5 p.m. on business days.","How to apply: Apply for the Certificate of Continued Occupancy (online through the SDL Portal or on the paper form); the Fire Department inspects the smoke and carbon monoxide alarms as part of the CCO inspection.","Fire official in the NJ state directory, updated 1/8/2026: Matthew J Lubin · (908) 709-7360 · m-lubin@cranfordnj.org","Ten-year sealed battery or hardwired interconnected smoke alarms on each level and in the bedroom area, including basements and finished attics","Carbon monoxide detection in all sleeping areas, and wherever the home has a fuel-burning furnace or boiler or an attached garage","Secondary power source label (generator, solar, battery storage) within 18 inches of the main electrical panel and the electric meter; no handwritten labels","Handled as part of the Township Certificate of Continued Occupancy inspection (sump pump, house number, open permit and zoning items are checked at the same time)","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Smoke and carbon monoxide certificate, included in the Certificate of Continued Occupancy fee for a sale","amount":"$100"}]$j$::jsonb, $t$https://www.cranfordnj.org/DocumentCenter/View/929/cco_application_3$t$, $t$https://www.cranfordnj.org/2066/Fire-Department$t$, $j$[{"url":"https://www.cranfordnj.org/DocumentCenter/View/919/fire_prevention_fee_increase_notice_06042025","label":"Official source (cranfordnj.org)"},{"url":"https://www.cranfordnj.org/DocumentCenter/View/915/cco_requirement_sheet_0","label":"Official source (cranfordnj.org)"},{"url":"https://www.cranfordnj.org/Directory.aspx?EID=233","label":"Official source (cranfordnj.org)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://www.cranfordnj.org/DocumentCenter/View/929/cco_application_3","label":"Official source (cranfordnj.org)"}]$j$::jsonb, $t$shall have a fee of $35 $50, which is included within the fee for Applications for a Certificate of Continued Occupancy.$t$, $t$608ac51e33798481758458e7c827307dc02138cd046b095c1421fd9f482e36bc$t$, $t$2026-10-02T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-02","approved_on":"2026-10-02","needs_lookup":false,"flag_reasons":[],"verification":{"fees":4,"fee_ok":4,"fee_bad":0,"fee_unchecked":0,"quotes":17,"q_ok":17,"q_bad":0,"q_unchecked":0},"source":"property/data/municipal-requirements/checked/2003.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-02 and approved in the NJ Resale Certificate Tracker on 2026-10-02. Source: property/data/municipal-requirements/checked/2003.json$t$, true),
  ($t$2004$t$, $t$Elizabeth City$t$, $t$UNION$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Certificate of Occupancy for Resale (Resale Certificate)$t$, $j$["Issued by: City of Elizabeth Bureau of Zoning (Office of Zoning)","Contact: Vanessa Ferrara, Zoning office staff (Zoning Board of Adjustments, Rm. 101); named as the resale certificate contact on the application · 908-820-4096 · vanessa.ferrara@elizabethnj.org","How to apply: Apply online with the City's Resale Certificates application (GovPilot) and pay by credit card, or pay by mail or in person at City Hall, 50 Winfield Scott Plaza, Elizabeth, NJ 07201. Attach a copy of the smoke and carbon monoxide certificate from Fire Prevention, which is applied for separately. Only affidavits on an attorney's letterhead may be attached online; notarized affidavits must be handed in as originals.","Valid for: A temporary certificate of occupancy for resale, when violations remain, may be issued for up to 90 days","Inspection by the Zoning Officer for compliance with the City code (Health and Safety, Buildings and Construction, and Land Development chapters)","Smoke and carbon monoxide certificate from Elizabeth Fire Prevention for 1 and 2 family homes (submit a copy of the original)","All outstanding construction permits and construction violation notices must be closed","Any vacant, abandoned or foreclosing property registration fees must be paid","Lead-free or lead-safe certificate for rental single-family, rental two-family and multiple dwelling units built before 1978","Owner certifies the home and other structures meet zoning and that no rubbish, debris or bulk garbage will be left before the new occupancy","List any garage, deck, fence, shed, pool or finished basement on the application","Also: Open permits: All open construction permits and construction violation notices must be closed before the resale certificate is issued.","Also: Vacant property registration fees: Any vacant, abandoned or foreclosing property registration fees must be paid before the resale certificate is issued."]$j$::jsonb, $j$[{"label":"Resale certificate, condo or 1 family","amount":"$60.00"},{"label":"Resale certificate, 2 family","amount":"$80.00"},{"label":"Resale certificate, each additional unit","amount":"$20"},{"label":"Certificate of occupancy for resale, residential or commercial use (Code Section 17.52.060)","amount":"$60.00"},{"label":"Smoke alarm, carbon monoxide alarm and fire extinguisher certificate, inspection scheduled 11 or more days after the application","amount":"$40.00"},{"label":"Inspection scheduled 5 to 10 days after the application","amount":"$75.00"},{"label":"Inspection scheduled 1 to 4 days after the application","amount":"$130.00"}]$j$::jsonb, $t$https://main.govpilot.com/web/public/9d6798fe-b48_Resale-Certificates-City-of-Elizabeth?uid=7414&ust=NJ&pu=1&id=0$t$, $t$https://eforms-main.govpilot.com/NJ/elizabeth$t$, $j$[{"url":"https://main.govpilot.com/web/public/9d6798fe-b48_Resale-Certificates-City-of-Elizabeth?uid=7414&ust=NJ&pu=1&id=0","label":"Official source (main.govpilot.com)"},{"url":"https://library.municode.com/nj/elizabeth/codes/code_of_ordinances?nodeId=TIT15BUCO_CH15.12HOCO_ARTXIEN_15.12.860CEOCRERE","label":"Official source (library.municode.com)"},{"url":"https://library.municode.com/nj/elizabeth/codes/code_of_ordinances?nodeId=TIT17LADECO_CH17.08BUPECEOC_17.08.070CEOCRE","label":"Official source (library.municode.com)"},{"url":"https://library.municode.com/nj/elizabeth/codes/code_of_ordinances?nodeId=TIT17LADECO_CH17.52FE_17.52.060FESCCEOCRE","label":"Official source (library.municode.com)"},{"url":"https://www.elizabethnj.org/Directory.aspx","label":"Official source (elizabethnj.org)"},{"url":"https://main.govpilot.com/web/public/ca7813f5-211_Smoke-Detector-City-of-Elizabeth?uid=7414&ust=NJ&pu=1&id=0","label":"Official source (main.govpilot.com)"}]$j$::jsonb, $t$A Resale Certificate is required when selling a home and is the responsibility of the seller.$t$, $t$2ef81ff1c71fa7c2512022c699329914d74ce9507f27ac6c2d4e1d199e40339d$t$, $t$2026-10-02T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-02","approved_on":"2026-10-02","needs_lookup":false,"flag_reasons":[],"verification":{"fees":7,"fee_ok":7,"fee_bad":0,"fee_unchecked":0,"quotes":24,"q_ok":23,"q_bad":0,"q_unchecked":1},"source":"property/data/municipal-requirements/checked/2004.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-02 and approved in the NJ Resale Certificate Tracker on 2026-10-02. Source: property/data/municipal-requirements/checked/2004.json$t$, true),
  ($t$2004$t$, $t$Elizabeth City$t$, $t$UNION$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Elizabeth Fire Prevention Bureau (Elizabeth Fire Department) (town fire bureau)","Contact: Dennis Guiro, Fire Official · 908-820-4040 · dennis.guiro@elizabethnj.org","Apply: Fee depends on business days between the application and the inspection date: 11 or more days for the lowest fee. Applications are taken 9 a.m. to 3 p.m. on business days. No inspection after the closing date. The certificate is good for 90 days.","How to apply: Apply online with the City's Smoke Detector application (GovPilot) and pay in full; the application is not processed until paid. Have the address, block and lot, expected closing date, responsible party and dwelling type ready. A failed inspection, a cancellation or a missed appointment needs a new online application and a new fee. Cancel at least 24 hours ahead; fees are non-refundable.","Fire official in the NJ state directory, updated 1/7/2026: Dennis Guiro · (908) 820-4040 · dennis.guiro@elizabethnj.org","Smoke alarms on each level, including basements and attics with built-up walls or gas or electric utilities, and outside each sleeping area within 10 feet of bedrooms; listed to UL 217","Carbon monoxide alarms (UL 2034) on each level and outside each sleeping area; combination smoke/CO and plug-in units are allowed","Battery smoke alarms must be 10-year sealed units; carbon monoxide alarms may not be more than 10 years old","Hardwired (AC powered) alarms must work on AC power and cannot be replaced with battery-only alarms","Fire extinguisher rated 2A-10B:C, mounted and visible within 10 feet of the stove (still listed on the City page and online form)","No security bars or gates on windows unless they have a quick-release, and only on the first floor","Illegal basement or attic tenancy, or major cooking appliances in basements or attics, will delay the certificate","Only the applicant, the realtor or the realtor's representative may accompany the inspector, not a tenant","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Smoke alarm, carbon monoxide alarm and fire extinguisher certificate, inspection scheduled 11 or more days after the application","amount":"$40.00"},{"label":"Inspection scheduled 5 to 10 days after the application","amount":"$75.00"},{"label":"Inspection scheduled 1 to 4 days after the application","amount":"$130.00"}]$j$::jsonb, $t$https://main.govpilot.com/web/public/ca7813f5-211_Smoke-Detector-City-of-Elizabeth?uid=7414&ust=NJ&pu=1&id=0$t$, $t$https://www.elizabethnj.org/369/Request-an-Inspection$t$, $j$[{"url":"https://main.govpilot.com/web/public/ca7813f5-211_Smoke-Detector-City-of-Elizabeth?uid=7414&ust=NJ&pu=1&id=0","label":"Official source (main.govpilot.com)"},{"url":"https://www.elizabethnj.org/369/Request-an-Inspection","label":"Official source (elizabethnj.org)"},{"url":"https://www.elizabethnj.org/368/Office-ofthe-FireOfficial","label":"Official source (elizabethnj.org)"},{"url":"https://www.elizabethnj.org/370/Smoke-CO-Open-BurningDetector-Regulation","label":"Official source (elizabethnj.org)"},{"url":"https://www.elizabethnj.org/Directory.aspx?DID=88","label":"Official source (elizabethnj.org)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$The fee covers the initial inspection. A new application and fee is required if the initial inspection fails.$t$, $t$d0896ee3551e12ab7f53f5ff997452b614ad4ba3aa0ce0779f1786244f20a99b$t$, $t$2026-10-02T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-02","approved_on":"2026-10-02","needs_lookup":false,"flag_reasons":[],"verification":{"fees":7,"fee_ok":7,"fee_bad":0,"fee_unchecked":0,"quotes":24,"q_ok":23,"q_bad":0,"q_unchecked":1},"source":"property/data/municipal-requirements/checked/2004.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-02 and approved in the NJ Resale Certificate Tracker on 2026-10-02. Source: property/data/municipal-requirements/checked/2004.json$t$, true),
  ($t$2006$t$, $t$Garwood Borough$t$, $t$UNION$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Certificate of Compliance (Borough Code Section 106-25)$t$, $j$["Issued by: Garwood Fire Department, Bureau of Fire Prevention and Code Enforcement","Contact: Leonard Spina, Fire Official · 908.477.6752 · fireprevention@garwood.org","Apply: Apply more than 10 business days before closing for the lowest fee","How to apply: Fill out the Application for Certificate of Compliance (fillable PDF), check every box, and send it with a check or money order payable to Borough of Garwood to the Borough of Garwood, 403 South Avenue, Garwood. The Fire Department (Fire Prevention Bureau) then inspects. Questions: fireprevention@garwood.org.","Valid for: If the change of occupancy does not happen within six months, a new application fee is required","Smoke alarm on each level including the basement (not unfinished attics or crawl spaces), near the stairs, and within 10 feet of each bedroom; habitable attics need one","Carbon monoxide alarm outside each separate sleeping area within 10 feet of bedrooms if the home has a fuel-burning appliance or an attached garage","All smoke and CO alarms working; all alarms less than 10 years old; battery smoke alarms must be 10-year sealed units (since January 1, 2019)","AC powered or interconnected alarms installed after January 1977 must be kept working","The existing use must be a proper use in the zone (zoning officer certification if the use is nonconforming or by variance)","No roof drain, sump pump or other stormwater may drain into the Borough sanitary sewer; any such connection must be moved to the storm system before the certificate is issued","No open building permits; final inspections must be scheduled through the Building Department","Also: Stormwater connections: Roof drains, sump pumps and other stormwater must not drain into the Borough sanitary sewer; connections must be moved to the storm system before the certificate is issued.","Also: Open building permits: All open building permits must be closed through the Building Department before the certificate is issued.","Also: Zoning use: The certificate states the use category; a nonconforming use needs the zoning officer's certification that it is lawful."]$j$::jsonb, $j$[{"label":"Certificate of Compliance (resale certificate, includes smoke and carbon monoxide inspection), closing more than 10 business days after the Bureau receives the application","amount":"$70"},{"label":"Application received fewer than 10 but more than 4 business days before closing","amount":"$100"},{"label":"Application received 4 business days or fewer before closing","amount":"$200"},{"label":"Certificate of Compliance (resale certificate, includes smoke and carbon monoxide inspection), closing more than 10 business days after the Bureau receives the application","amount":"$70"},{"label":"Application received fewer than 10 but more than 4 business days before closing","amount":"$100"},{"label":"Application received 4 business days or fewer before closing","amount":"$200"}]$j$::jsonb, $t$https://garwood.org/vertical/sites/%7B7F1088A0-CEC9-4505-80EE-1DF1BF7DFFBD%7D/uploads/Certificate_of_Compliance_Application_Updated_-Fillable.pdf$t$, $t$https://garwood.org/index.asp?SEC=2CE33063-DD93-4CBF-9DE1-1C80EC85859A$t$, $j$[{"url":"https://garwood.org/vertical/sites/%7B7F1088A0-CEC9-4505-80EE-1DF1BF7DFFBD%7D/uploads/Certificate_of_Compliance_Application_Updated_-Fillable.pdf","label":"Official source (garwood.org)"},{"url":"https://garwood.org/index.asp?SEC=2CE33063-DD93-4CBF-9DE1-1C80EC85859A","label":"Official source (garwood.org)"},{"url":"https://garwood.org/index.asp?SEC=BFA6B573-6B23-45BE-8CBE-B64B9BB92EC1","label":"Official source (garwood.org)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$A certificate of compliance shall be required to be obtained prior to occupancy after the sale or conveyance of any residential, commercial, industrial, institutional, mixed use or other property or structure within the Borough.$t$, $t$a69e2beeb452b036ae7163d311cb615bab1854c2ac1cee1028ba62e5645985cd$t$, $t$2026-10-02T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-02","approved_on":"2026-10-02","needs_lookup":false,"flag_reasons":[],"verification":{"fees":6,"fee_ok":6,"fee_bad":0,"fee_unchecked":0,"quotes":15,"q_ok":15,"q_bad":0,"q_unchecked":0},"source":"property/data/municipal-requirements/checked/2006.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-02 and approved in the NJ Resale Certificate Tracker on 2026-10-02. Source: property/data/municipal-requirements/checked/2006.json$t$, true),
  ($t$2006$t$, $t$Garwood Borough$t$, $t$UNION$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Garwood Fire Department, Bureau of Fire Prevention and Code Enforcement (town fire bureau)","Contact: Leonard Spina, Fire Official · 908.477.6752 · fireprevention@garwood.org","Apply: Apply more than 10 business days before closing for the lowest fee. A new fee is needed if the sale does not close within six months.","How to apply: Same application as the Borough Certificate of Compliance: send the completed form with a check or money order payable to Borough of Garwood to 403 South Avenue, Garwood.","Fire official in the NJ state directory, updated 7/1/2025: Leonard Spina · (908) 789-8877 · fireprevention@garwood.org","Smoke alarm on each level including the basement (not unfinished attics or crawl spaces), near the stairs, and within 10 feet of each bedroom; habitable attics need one","Carbon monoxide alarm outside each separate sleeping area within 10 feet of bedrooms if the home has a fuel-burning appliance or an attached garage","All smoke and CO alarms working; all alarms less than 10 years old; battery smoke alarms must be 10-year sealed units (since January 1, 2019)","AC powered or interconnected alarms installed after January 1977 must be kept working","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Certificate of Compliance (resale certificate, includes smoke and carbon monoxide inspection), closing more than 10 business days after the Bureau receives the application","amount":"$70"},{"label":"Application received fewer than 10 but more than 4 business days before closing","amount":"$100"},{"label":"Application received 4 business days or fewer before closing","amount":"$200"}]$j$::jsonb, $t$https://garwood.org/vertical/sites/%7B7F1088A0-CEC9-4505-80EE-1DF1BF7DFFBD%7D/uploads/Certificate_of_Compliance_Application_Updated_-Fillable.pdf$t$, $t$https://garwood.org/index.asp?SEC=2CE33063-DD93-4CBF-9DE1-1C80EC85859A$t$, $j$[{"url":"https://garwood.org/vertical/sites/%7B7F1088A0-CEC9-4505-80EE-1DF1BF7DFFBD%7D/uploads/Certificate_of_Compliance_Application_Updated_-Fillable.pdf","label":"Official source (garwood.org)"},{"url":"https://garwood.org/index.asp?SEC=BFA6B573-6B23-45BE-8CBE-B64B9BB92EC1","label":"Official source (garwood.org)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$Bureau of Fire Prevention and Code Enforcement Garwood Fire Department 415 South Avenue, Garwood, New Jersey 07027 Telephone: (908) 789-8877$t$, $t$8247daf9856e9ce7897016f62cc68405bcf1f594b6992caf1aa96967dc6ac263$t$, $t$2026-10-02T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-02","approved_on":"2026-10-02","needs_lookup":false,"flag_reasons":[],"verification":{"fees":6,"fee_ok":6,"fee_bad":0,"fee_unchecked":0,"quotes":15,"q_ok":15,"q_bad":0,"q_unchecked":0},"source":"property/data/municipal-requirements/checked/2006.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-02 and approved in the NJ Resale Certificate Tracker on 2026-10-02. Source: property/data/municipal-requirements/checked/2006.json$t$, true),
  ($t$2007$t$, $t$Hillside Township$t$, $t$UNION$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Certificate of Continued Occupancy (current application titled Certificate of Resale)$t$, $j$["Issued by: Hillside Building and Housing Department","Contact: Artur Figueiredo, Construction Official / Building Subcode Official · (973) 926-5100 ext. 322 · afigueiredo@hillsidenj.us","How to apply: Fill out the Certificate of Resale application and pay by check or money order payable to Township of Hillside at the Building Department, 1409 Liberty Avenue. Then call (973) 926-5100 to set the inspection date; inspection request forms can be emailed to inspectionrequests@hillsidenj.us. The certificate is mailed to the applicant after approval (no pick-up, fax or copies). A buyer who takes on the repairs may file an Affidavit of Compliance promising to fix them within 30 days of closing, subject to the Construction Official's approval.","Grass cut, no snow or ice, and no trash or debris on the property, or the inspection is cancelled","Violations found at the first inspection are mailed within 2 weeks and must be fixed within 30 days of the letter; call to schedule a re-inspection","Open permits for the property must be dealt with before the certificate is issued","Smoke detectors, carbon monoxide detectors, fire extinguishers, oil tanks, grass and weeds, and litter or debris cannot be deferred to the buyer by affidavit","No one may live in the basement","If there is a third floor or full attic, the buyer's affidavit must state it will not be used as a separate unit or dwelling area (unless the attic is big enough and has proper egress)","A smoke certificate from the Fire Department is also required","Bulk trash is limited to three items a week; larger cleanouts need a private hauler and a dumpster permit","Also: Open permits: Any open permits for the property must be dealt with before the Certificate of Continued Occupancy is issued.","Also: Bulk waste before sale: Sellers may put out no more than three bulk items per week; otherwise hire a disposal company, which needs a dumpster permit."]$j$::jsonb, $j$[{"label":"Certificate of Resale (Continued Occupancy), first residential dwelling unit","amount":"$150"},{"label":"Each additional residential unit","amount":"$75.00"},{"label":"Maximum residential fee","amount":"$400"}]$j$::jsonb, $t$https://hillsidenj.us/css/hillsidenj/attachments/22985/d509341d3cbe65f53fff14f7ff6312d0.pdf$t$, $t$https://hillsidenj.us/building-and-housing-department$t$, $j$[{"url":"https://hillsidenj.us/building-and-housing-department","label":"Official source (hillsidenj.us)"},{"url":"https://hillsidenj.us/css/hillsidenj/attachments/22985/d509341d3cbe65f53fff14f7ff6312d0.pdf","label":"Official source (hillsidenj.us)"},{"url":"https://hillsidenj.us/css/hillsidenj/attachments/22985/c7da52cd689d3eeb58db8e4b5e49885b.pdf","label":"Official source (hillsidenj.us)"},{"url":"https://hillsidenj.us/css/hillsidenj/attachments/22985/5eceb48a28c59_Rules_&_Regulations_for_a_Certificate_of_Continued_Occupancy.pdf","label":"Official source (hillsidenj.us)"}]$j$::jsonb, $t$A Certificate of Continued Occupancy is required for the resale of residential and non-residential properties and change of tenants in non-residential properties.$t$, $t$8479e03438a2f865fb7718a3762a5be4d1f184f1263c38e0dd1f092ca5f65309$t$, $t$2026-10-02T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-02","approved_on":"2026-10-02","needs_lookup":false,"flag_reasons":[],"verification":{"fees":3,"fee_ok":3,"fee_bad":0,"fee_unchecked":0,"quotes":15,"q_ok":15,"q_bad":0,"q_unchecked":0},"source":"property/data/municipal-requirements/checked/2007.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-02 and approved in the NJ Resale Certificate Tracker on 2026-10-02. Source: property/data/municipal-requirements/checked/2007.json$t$, true),
  ($t$2007$t$, $t$Hillside Township$t$, $t$UNION$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Hillside Fire Department, Fire Prevention Bureau (town fire bureau)","Contact: Paul Antunes, Captain, Fire Official · 848-666-2969 · fireprevention@hillsidefire.org","How to apply: The Township's resale application says the smoke certificate must be obtained from the Fire Department at (908) 352-1700. No application form or fee schedule was found online.","Fire official in the NJ state directory, updated 1/12/2026: Paul Antunes · (973) 926-3000 · pantunes@hillsidefire.org","Township rules list smoke detectors, carbon monoxide detectors and fire extinguishers as items the seller must complete before the Certificate of Continued Occupancy (they cannot be deferred to the buyer)","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[]$j$::jsonb, null, $t$https://hillsidenj.us/fire-department$t$, $j$[{"url":"https://hillsidenj.us/fire-department","label":"Official source (hillsidenj.us)"},{"url":"https://hillsidenj.us/css/hillsidenj/attachments/22985/d509341d3cbe65f53fff14f7ff6312d0.pdf","label":"Official source (hillsidenj.us)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$Captain Paul Antunes, Fire Official fireprevention@hillsidefire.org 848-666-2969$t$, $t$ec4e561742942d9e05d39cf5c840b1d0bf7bc9d42e2a09f103e77e2c6324da66$t$, $t$2026-10-02T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-02","approved_on":"2026-10-02","needs_lookup":false,"flag_reasons":[],"verification":{"fees":3,"fee_ok":3,"fee_bad":0,"fee_unchecked":0,"quotes":15,"q_ok":15,"q_bad":0,"q_unchecked":0},"source":"property/data/municipal-requirements/checked/2007.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-02 and approved in the NJ Resale Certificate Tracker on 2026-10-02. Source: property/data/municipal-requirements/checked/2007.json$t$, true),
  ($t$2008$t$, $t$Kenilworth Borough$t$, $t$UNION$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Certificate of Compliance / Certificate of Continued Occupancy (CCO), sale of property$t$, $j$["Issued by: Kenilworth Building Department (Construction Official / Zoning Official)","Contact: Anthony Monguso, Construction Official / Building Subcode Official / Zoning Official (also Code Enforcement Official) · 908-276-5802 · zoningofficer@kenilworthnj.org","How to apply: Fill out the Borough's Application for Certificate of Compliance (check Sale of Property) and file it with the Building Department at 567 Boulevard, Kenilworth. The Building Department takes cash or a check payable to Borough of Kenilworth.","Also: Open construction permits: The Building Department follows up on all open permits with Notices of Violations and, in some cases, penalties; schedule final inspections to close them."]$j$::jsonb, $j$[{"label":"Certificate of Continued Occupancy, residential (Ordinance 2026-11, adopted April 15, 2026; the old $175/$80 is struck out and replaced)","amount":"$200.00"},{"label":"Certificate of Continued Occupancy, residential reinspection (Ordinance 2026-11; the September 2026 application form instead shows $85.00 for each additional unit)","amount":"$85.00"},{"label":"Smoke and carbon monoxide alarm inspection, sale of single-family home, requested two or more weeks in advance (Ordinance 2026-08, which sets the sale fee equal to the annual inspection fee)","amount":"$100.00"},{"label":"Smoke and carbon monoxide alarm inspection, sale of two-family home, requested two or more weeks in advance (Ordinance 2026-08)","amount":"$160.00"},{"label":"Sale of single-family home, requested less than 1 week ahead, with 1 re-inspection (application form, November 2025; not in Ordinance 2026-08)","amount":"$150.00"},{"label":"Sale of two-family home, requested less than 1 week ahead, with 1 re-inspection (application form, November 2025; not in Ordinance 2026-08)","amount":"$210.00"}]$j$::jsonb, $t$https://www.kenilworthborough.com/DocumentCenter/View/120/Certificate-of-Compliance-Application-Form-SALE-OF-PROPERTY-CCO$t$, $t$https://www.kenilworthborough.com/183/Construction-Building-Department$t$, $j$[{"url":"https://www.kenilworthborough.com/184/Forms-Applications","label":"Official source (kenilworthborough.com)"},{"url":"https://www.kenilworthborough.com/DocumentCenter/View/120/Certificate-of-Compliance-Application-Form-SALE-OF-PROPERTY-CCO","label":"Official source (kenilworthborough.com)"},{"url":"https://www.kenilworthborough.com/DocumentCenter/View/1604/2026-11-Ordinance-Amending-UCC-Fees-","label":"Official source (kenilworthborough.com)"},{"url":"https://www.kenilworthborough.com/400/FEE-CHANGES-2025","label":"Official source (kenilworthborough.com)"},{"url":"https://www.kenilworthborough.com/183/Construction-Building-Department","label":"Official source (kenilworthborough.com)"},{"url":"https://www.kenilworthborough.com/DocumentCenter/View/1605/2026-08-Fire-Prevention-Inspection-Fees","label":"Official source (kenilworthborough.com)"},{"url":"https://www.kenilworthborough.com/DocumentCenter/View/797/Fire-Prevention-Application","label":"Official source (kenilworthborough.com)"}]$j$::jsonb, $t$Certificate of Compliance Application Form (SALE OF PROPERTY, CCO)$t$, $t$a093757e360a76bda6c55044699d43a7227142439e87c3cecf2975e39839e956$t$, $t$2026-10-02T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-02","approved_on":"2026-10-02","needs_lookup":false,"flag_reasons":[],"verification":{"fees":6,"fee_ok":6,"fee_bad":0,"fee_unchecked":0,"quotes":30,"q_ok":30,"q_bad":0,"q_unchecked":0},"source":"property/data/municipal-requirements/checked/2008.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-02 and approved in the NJ Resale Certificate Tracker on 2026-10-02. Source: property/data/municipal-requirements/checked/2008.json$t$, true),
  ($t$2008$t$, $t$Kenilworth Borough$t$, $t$UNION$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Kenilworth Fire Department, Bureau of Fire Prevention (town fire bureau)","Contact: Carmen Giordino, Fire Official (state fire directory) · (908) 276-8935 · cgiordino@kenilworthfire.org","Apply: The form's base fee is for a 1 week turnaround (higher fee if requested on less than 1 week); Ordinance 2026-08 sets the base sale fee for requests made two or more weeks in advance","How to apply: Download and print the Residential Fire Prevention application, then mail it or drop it in the white mailbox at Kenilworth Fire Headquarters, 491 Washington Ave, Kenilworth NJ 07033, with a check or money order (no cash) payable to Kenilworth Fire Prevention Bureau. The fire inspector calls to review requirements before the inspection.","Fire official in the NJ state directory, updated 1/27/2026: Carmen Giordino · (908) 276-8935 · cgiordino@kenilworthfire.org","Battery-only smoke and carbon monoxide alarms must be 10-year sealed battery units (since January 1, 2019), on each level and outside all bedroom areas","Hardwired (electric) smoke and CO alarms may not be replaced with battery alarms, and must be replaced after 10 years (date of manufacture is on the underside)","Electric CO alarms or combination smoke/CO alarms are required on each level and next to any fuel-burning appliance","Homes with a permanently installed generator, solar panels, battery storage or other secondary power source need a label (not handwritten) within 18 inches of the main electrical panel and the electric meter saying there are multiple power sources","The fire inspector contacts the applicant to review requirements before the inspection","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Smoke and carbon monoxide alarm inspection, sale of single-family home, requested two or more weeks in advance (Ordinance 2026-08, which sets the sale fee equal to the annual inspection fee)","amount":"$100.00"},{"label":"Smoke and carbon monoxide alarm inspection, sale of two-family home, requested two or more weeks in advance (Ordinance 2026-08)","amount":"$160.00"},{"label":"Sale of single-family home, requested less than 1 week ahead, with 1 re-inspection (application form, November 2025; not in Ordinance 2026-08)","amount":"$150.00"},{"label":"Sale of two-family home, requested less than 1 week ahead, with 1 re-inspection (application form, November 2025; not in Ordinance 2026-08)","amount":"$210.00"}]$j$::jsonb, $t$https://www.kenilworthborough.com/DocumentCenter/View/797/Fire-Prevention-Application$t$, $t$https://www.kenilworthborough.com/185/Fire-Department$t$, $j$[{"url":"https://www.kenilworthborough.com/185/Fire-Department","label":"Official source (kenilworthborough.com)"},{"url":"https://www.kenilworthborough.com/DocumentCenter/View/797/Fire-Prevention-Application","label":"Official source (kenilworthborough.com)"},{"url":"https://www.kenilworthborough.com/DocumentCenter/View/1605/2026-08-Fire-Prevention-Inspection-Fees","label":"Official source (kenilworthborough.com)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"},{"url":"https://www.kenilworthborough.com/Directory.aspx?did=13","label":"Official source (kenilworthborough.com)"}]$j$::jsonb, $t$Smoke Detector Application Form: This form is used when there is a change of occupancy (sale or rental) for a single family, two-family, or rental apartment. This form must be download, printed, and mailed (along with the appropriate fee) to: Kenilworth Fire Department Attn: Bureau of Fire Prevention 491 Washington Avenue Kenilworth, NJ 07033$t$, $t$e9388fa444b1b3dd428deec65023f49474b2e8615ae21c75d02b994e02cc7d5a$t$, $t$2026-10-02T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-02","approved_on":"2026-10-02","needs_lookup":false,"flag_reasons":[],"verification":{"fees":6,"fee_ok":6,"fee_bad":0,"fee_unchecked":0,"quotes":30,"q_ok":30,"q_bad":0,"q_unchecked":0},"source":"property/data/municipal-requirements/checked/2008.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-02 and approved in the NJ Resale Certificate Tracker on 2026-10-02. Source: property/data/municipal-requirements/checked/2008.json$t$, true),
  ($t$2009$t$, $t$Linden City$t$, $t$UNION$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Continued Certificate of Occupancy (CCO), residential sale$t$, $j$["Issued by: Linden Health Department (residential Certificate of Occupancy inspections); the Construction Code office handles commercial CCOs","Contact: (908) 474-8409 · health@linden-nj.gov","How to apply: Apply online with the City's GovPilot 'Residential Sale CCO Application' (Residential Sale Only), linked from the City's Continued Certificate of Occupancy Application page. The form asks for the buyer, the agent and who to contact for inspections, and offers Pay Now or Submit & Pay Later. Questions go to the Health Department, 605 South Wood Avenue, (908) 474-8409.","Owner certifies the dwelling and all other structures meet the City's zoning requirements","No rubbish, debris or bulk garbage may be left on the property before the new occupancy"]$j$::jsonb, $j$[]$j$::jsonb, $t$https://main.govpilot.com/web/public/f18dd71d-989_CCO-Linden?uid=6947&ust=NJ&pu=1&id=0$t$, $t$https://linden-nj.gov/directory/health-department/$t$, $j$[{"url":"https://linden-nj.gov/documents/continued-certificate-of-occupancy-application/","label":"Official source (linden-nj.gov)"},{"url":"https://main.govpilot.com/web/public/f18dd71d-989_CCO-Linden?uid=6947&ust=NJ&pu=1&id=0","label":"Official source (main.govpilot.com)"},{"url":"https://linden-nj.gov/directory/health-department/","label":"Official source (linden-nj.gov)"},{"url":"https://linden-nj.gov/directory/construction-code/","label":"Official source (linden-nj.gov)"},{"url":"https://linden-nj.gov/wp-content/uploads/2025/09/Application-CSDCMAC-9-2025.pdf","label":"Official source (linden-nj.gov)"}]$j$::jsonb, $t$Click here for the Residential Sale CCO Application.$t$, $t$e75c36013c11fb03632e38751038a08c19496fbd41278f436ab8dcff028c2f7e$t$, $t$2026-10-02T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-02","approved_on":"2026-10-02","needs_lookup":false,"flag_reasons":[],"verification":{"fees":3,"fee_ok":3,"fee_bad":0,"fee_unchecked":0,"quotes":21,"q_ok":21,"q_bad":0,"q_unchecked":0},"source":"property/data/municipal-requirements/checked/2009.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-02 and approved in the NJ Resale Certificate Tracker on 2026-10-02. Source: property/data/municipal-requirements/checked/2009.json$t$, true),
  ($t$2009$t$, $t$Linden City$t$, $t$UNION$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: City of Linden Fire Department, Fire Prevention Bureau (town fire bureau)","Contact: Christopher Rooney, Deputy Chief/Fire Official (the Fire Prevention page's email belongs to Fire Chief William M. Hasko, Jr.) · (908)-474-4560 · whasko@lindenfd-nj.gov","Apply: Apply more than 10 business days before the change of occupancy for the lowest fee. A new application is required if the sale does not happen within six months.","How to apply: Download the Smoke Detector & Carbon Monoxide Application Form from the City website, fill it out and mail it or drop it in the bin outside the Fire Prevention entrance, 302 South Wood Avenue, Monday to Friday 9 am to 5 pm. Checks payable to City of Linden (the under-4-business-days fee is cash only). The bureau schedules the inspection as soon as possible after it gets the application.","Fire official in the NJ state directory, updated 8/12/2025: Christopher D Rooney · (908) 474-4560 · crooney@lindenfs-nj.gov","Smoke alarms must be 10-year sealed battery or hardwired, on each level including basements (not attics or crawl spaces) and outside each separate sleeping area within 10 feet of the bedrooms","Carbon monoxide alarms outside each sleeping area","All alarms must work","Hardwired (A/C-powered) smoke alarms from the original construction may not be replaced with battery alarms","Homes with a secondary power source (generator, solar panels, battery storage) need a 'CAUTION: MULTIPLE SOURCES OF POWER' label (not handwritten) within 18 inches of the main electrical panel and the electric meter","A property representative or homeowner must be present at the inspection; a no-show counts as a failure","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Certificate of smoke detector and carbon monoxide alarm compliance, request received more than 10 business days before the change of occupancy","amount":"$50.00"},{"label":"Certificate, request received 4 to 10 business days before the change of occupancy","amount":"$90.00"},{"label":"Certificate, request received fewer than 4 business days before the change of occupancy (cash only)","amount":"$170.00"}]$j$::jsonb, $t$https://linden-nj.gov/wp-content/uploads/2025/09/Application-CSDCMAC-9-2025.pdf$t$, $t$https://linden-nj.gov/directory/fire-prevention/$t$, $j$[{"url":"https://linden-nj.gov/directory/fire-prevention/","label":"Official source (linden-nj.gov)"},{"url":"https://linden-nj.gov/document-category/fire-prevention/","label":"Official source (linden-nj.gov)"},{"url":"https://linden-nj.gov/wp-content/uploads/2025/09/Application-CSDCMAC-9-2025.pdf","label":"Official source (linden-nj.gov)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$The Fire Prevention Department reports to the Fire Chief and provides inspection of business and home locations to insure fire prevention safety and Smoke Detector, Carbon Monoxide and Fire Extinguisher Inspections for building and home sales in accordance with the New Jersey State Uniform Fire Codes.$t$, $t$a5f631ff753bb40ad1757d951da0592b5bf4a713678a45dfae5a2574eb16679b$t$, $t$2026-10-02T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-02","approved_on":"2026-10-02","needs_lookup":false,"flag_reasons":[],"verification":{"fees":3,"fee_ok":3,"fee_bad":0,"fee_unchecked":0,"quotes":21,"q_ok":21,"q_bad":0,"q_unchecked":0},"source":"property/data/municipal-requirements/checked/2009.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-02 and approved in the NJ Resale Certificate Tracker on 2026-10-02. Source: property/data/municipal-requirements/checked/2009.json$t$, true),
  ($t$2010$t$, $t$Mountainside Borough$t$, $t$UNION$t$, $t$resale_cco$t$, $t$official_process_found$t$, $t$Resale / Continued Certificate of Occupancy (CCO)$t$, $j$["Not required for sales, per Mountainside Borough. Confirm with the office if the buyer's lender or title company asks.","Contact: Jerry Eger, Construction Official · 908-232-2919 · jeger@mountainside-nj.com","How to apply: No Borough resale Certificate of Occupancy. The only Borough document needed for the sale of a home is the smoke detector / carbon monoxide re-sale certification (see fire certificate)."]$j$::jsonb, $j$[]$j$::jsonb, null, $t$https://www.mountainside-nj.com/department/buildingzoningengineering/$t$, $j$[{"url":"https://www.mountainside-nj.com/department/buildingzoningengineering/","label":"Official source (mountainside-nj.com)"}]$j$::jsonb, $t$** Please note: this is the only document the Borough of Mountainside requires for sale of a home - we do not perform CO Inspections$t$, $t$50fd39e0794636cdfc98b6d7c6d857dddb44d05f4f04a95eefecc054fbee7bff$t$, $t$2026-10-02T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-02","approved_on":"2026-10-02","needs_lookup":false,"flag_reasons":[],"verification":{"fees":1,"fee_ok":1,"fee_bad":0,"fee_unchecked":0,"quotes":11,"q_ok":11,"q_bad":0,"q_unchecked":0},"source":"property/data/municipal-requirements/checked/2010.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-02 and approved in the NJ Resale Certificate Tracker on 2026-10-02. Source: property/data/municipal-requirements/checked/2010.json$t$, true),
  ($t$2010$t$, $t$Mountainside Borough$t$, $t$UNION$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Borough of Mountainside Construction Department, Smoke Detector Re-Sale Certification (fire code enforcing agency: Scotch Plains Township under a shared service) (town fire bureau)","Contact: Jerry Eger, Construction Official (Technical Assistant: Ms. Deanna Andre, dandre@mountainside-nj.com) · 908-232-2919 · jeger@mountainside-nj.com","Apply: After the fee is paid and the online form is submitted, the Borough sends an inspection date. Inspections are Tuesday 3 to 6 pm and Thursday 1:30 to 4:30 pm.","How to apply: Request the inspection online through the SDL Portal (www.sdlportal.com, Mountainside), pay the $100.00 fee and submit the form; the Borough then gives an inspection date. For online payment help call the construction office at 908.232.2919.","Fire official in the NJ state directory, updated 1/14/2025: Rutland B Paal Jr · (908) 232-6700 · spaal@scotchplainsnj.com","Smoke alarm on each level and outside each separate sleeping area","Battery-only smoke alarms must be 10-year sealed battery units (listed to ANSI/UL 217); hardwired alarms from original construction or rehabilitation may not be replaced with battery alarms","Carbon monoxide alarm in the immediate vicinity of the sleeping areas (battery, hardwired or plug-in)","Portable fire extinguisher within 10 feet of the kitchen, listed and labeled, rated at least 2A-10B:C and no more than 10 pounds (still listed on the Borough page as of October 2026, although the state dropped it from the sale certificate in February 2025)","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Smoke detector, carbon monoxide alarm and portable fire extinguisher re-sale certification (residential)","amount":"$100.00"}]$j$::jsonb, null, $t$https://www.mountainside-nj.com/department/buildingzoningengineering/$t$, $j$[{"url":"https://www.mountainside-nj.com/department/buildingzoningengineering/","label":"Official source (mountainside-nj.com)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$SMOKE DETECTOR RE-SALE/RE-LEASING CERTIFICATION (RESIDENTIAL ONLY) Smoke Detector/Carbon Monoxide and Portable Fire Extinguisher inspection requests can be made online through the SDL Portal.$t$, $t$b3b12178bfdee0a5949839a9ac07c6048ae7218804fc5ad64103cc47303bce99$t$, $t$2026-10-02T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-02","approved_on":"2026-10-02","needs_lookup":false,"flag_reasons":[],"verification":{"fees":1,"fee_ok":1,"fee_bad":0,"fee_unchecked":0,"quotes":11,"q_ok":11,"q_bad":0,"q_unchecked":0},"source":"property/data/municipal-requirements/checked/2010.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-02 and approved in the NJ Resale Certificate Tracker on 2026-10-02. Source: property/data/municipal-requirements/checked/2010.json$t$, true),
  ($t$2011$t$, $t$New Providence Borough$t$, $t$UNION$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Resale/Rental Certificate (Resale Certificate of Occupancy)$t$, $j$["Issued by: Borough of New Providence Building Department (Department of Planning and Development)","Contact: Keith J. Lynch, Construction Official, Building/Fire Subcode (Technical Assistant: Debbie Timko) · 908-665-1098","Apply: Allow at least 10 business days before closing; the Borough recommends applying as soon as the contract is signed","How to apply: Fill out the Application for Resale/Rental Certificate (on the Building Department page or at Borough Hall, 360 Elkwood Avenue) and submit it with the fee; the fee must accompany the application, check payable to Borough of New Providence. Inspections are scheduled once payment is received. Call (908) 665-1098 with questions.","Working smoke detector on each level (not attic or crawl space) and in the vicinity of each bedroom door","Carbon monoxide alarm installed and working","Hardwired interconnected smoke/CO systems installed with the house must stay in place and working","Proper covers on all switches, outlets and junction boxes","No extension or zip cords used as permanent wiring","Pressure relief discharge pipe on boilers and water heaters, ending about 6 to 8 inches off the floor","Gas piping strapped, shut-off valves near appliances, unused gas pipes capped; no aluminum gas piping","Required clearances around fuel-burning appliances","Pool fences and gates in place and working","House numbers at least 3 inches high and visible from the street","Clear sight triangle at corners (vegetation trimmed)","No sump pump, roof drain or other connections to the sanitary sewer","Sound roof; leaders discharge away from the foundation and not onto the neighbor's yard","All work has construction permits that are closed, and the use conforms to zoning","Also: Open permits and violations: No certificate is issued until outstanding permits, violations and work done without permits are cleared.","Also: Sump pump and roof drain connections: Illegal sump pump, roof drain and other connections to the sanitary sewer must be removed."]$j$::jsonb, $j$[{"label":"Resale/Rental Certificate, 1 or 2 family detached, per unit (includes 1st reinspection)","amount":"$100.00"},{"label":"Resale/Rental Certificate, multi-family dwellings, townhouses, condos, per unit","amount":"$100.00"},{"label":"Additional inspections after the first reinspection, each","amount":"$25.00"}]$j$::jsonb, $t$https://www.newprov.us/DocumentCenter/View/13406$t$, $t$https://www.newprov.us/221/Building-Department$t$, $j$[{"url":"https://www.newprov.us/221/Building-Department","label":"Official source (newprov.us)"},{"url":"https://www.newprov.us/DocumentCenter/View/13406","label":"Official source (newprov.us)"}]$j$::jsonb, $t$Selling Your Home You will need a Resale/Rental Certificate (PDF) . This application is available on this page or at Borough Hall. Failure to make application in a timely manner may delay your closing.$t$, $t$40b9ffd12f7b46112dde0219f76a5968d28f1b1bdd6b05f67cda678bc505be91$t$, $t$2026-10-02T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-02","approved_on":"2026-10-02","needs_lookup":false,"flag_reasons":[],"verification":{"fees":3,"fee_ok":3,"fee_bad":0,"fee_unchecked":0,"quotes":14,"q_ok":14,"q_bad":0,"q_unchecked":0},"source":"property/data/municipal-requirements/checked/2011.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-02 and approved in the NJ Resale Certificate Tracker on 2026-10-02. Source: property/data/municipal-requirements/checked/2011.json$t$, true),
  ($t$2011$t$, $t$New Providence Borough$t$, $t$UNION$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: New Providence Fire Official (fire code enforcing agency, based in the Borough Building Department, 360 Elkwood Avenue) (town fire bureau)","Contact: Edward E Nasto, Fire Official (state fire directory) · (908) 665-1098 · enasto@newprov.org","How to apply: The Borough's Resale/Rental Certificate application includes the smoke and carbon monoxide alarm checks; apply through the Building Department at 360 Elkwood Avenue, (908) 665-1098. Whether a separate smoke/CO certificate or fee applies is not published.","Fire official in the NJ state directory, updated 1/7/2026: Edward E Nasto · (908) 665-1098 · enasto@newprov.org","Smoke detectors on every level (not crawl spaces or unfinished attics) and outside each sleeping area; basement detectors near the bottom of the stairs","Carbon monoxide alarms in every separate sleeping area per NFPA 720 and the manufacturer","Hardwired interconnected smoke/CO systems from original construction must remain in place and working","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[]$j$::jsonb, $t$https://www.newprov.us/DocumentCenter/View/13406$t$, $t$https://www.newprov.us/221/Building-Department$t$, $j$[{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"},{"url":"https://www.newprov.us/DocumentCenter/View/13406","label":"Official source (newprov.us)"},{"url":"https://www.newprov.us/221/Building-Department","label":"Official source (newprov.us)"}]$j$::jsonb, $t$F New Providence Borough$t$, $t$99221053b2db35aa4d4f7a6d20a3ab8f96407c0dc6e96db059d718d282a3aa30$t$, $t$2026-10-02T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-02","approved_on":"2026-10-02","needs_lookup":false,"flag_reasons":[],"verification":{"fees":3,"fee_ok":3,"fee_bad":0,"fee_unchecked":0,"quotes":14,"q_ok":14,"q_bad":0,"q_unchecked":0},"source":"property/data/municipal-requirements/checked/2011.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-02 and approved in the NJ Resale Certificate Tracker on 2026-10-02. Source: property/data/municipal-requirements/checked/2011.json$t$, true),
  ($t$2012$t$, $t$Plainfield City$t$, $t$UNION$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Certificate of Compliance (sale)$t$, $j$["Issued by: City of Plainfield Division of Inspections, Property Maintenance Unit (Department of Public Works and Urban Development)","Contact: Athenee Wright, General assistance, Inspections-Property Maintenance Unit (Spanish: Stephanie Hidalgo-Mendez, 908-753-2526… · 908-753-3384 · athenee.wright@plainfieldnj.gov","Apply: Schedule the inspection before closing; inspections are 10 am to 12:30 pm and someone must be there to let the inspector in","How to apply: Complete the Certificate of Compliance for Sale Application (on the City's Get a Permit or License page, Inspections Division forms) and schedule an inspection before closing. Submit it to the Division of Inspections, 515 Watchung Avenue. The application asks about the property, legal occupancy, buyer, closing date, permits and smoke/CO detectors. An LLC applicant must also give its Certificate of Formation. To close on a temporary certificate, the buyer signs a notarized affidavit and $500 per unit escrow is posted by certified check or money order.","Exterior walls, roofs, porches, stairs, railings and accessory structures","Yards, driveways, vegetation, trash and abandoned vehicles","Kitchens, bathrooms, bedrooms and other habitable rooms","Basements, cellars and crawlspaces","Common hallways, stairs and exits","Plumbing, water and hot water service; heating equipment and required temperatures","Electrical fixtures, switches and outlets","Smoke and carbon monoxide detectors","Windows, doors, walls, ceilings and floors; signs of leaks, moisture, vermin or unsafe conditions","Legal number of units and occupancy matching zoning and construction records","Open permits or work that looks like it was done without permits","Heating system / heating unit certificate on the licensed certifier's letterhead with license number","Smoke detector, carbon monoxide and fire extinguisher certificate from the Fire Division","For 3 or more units, a current Certificate of Inspection from the NJ Bureau of Housing Inspection","Also: Heating system certification: A heating system / heating unit certificate on the licensed certifier's letterhead with license number is required for the Certificate of Compliance.","Also: Multiple dwellings: For 3 or more units, a current Certificate of Inspection from the NJ Bureau of Housing Inspection.","Also: Open permits: Permits needed for work found during inspection must be obtained and inspected by the subcode officials before a clear certificate."]$j$::jsonb, $j$[{"label":"Certificate of Compliance for sale, first residential unit","amount":"$50"},{"label":"Each additional residential unit at the same property","amount":"$25"},{"label":"Missed appointment or no-show fee","amount":"$25"},{"label":"Certificate of Compliance exemption application","amount":"$75"},{"label":"Escrow when closing with a temporary Certificate of Compliance, per unit","amount":"$500"},{"label":"One family, application received 11+ business days before the inspection","amount":"$45"},{"label":"One family, application received 4 to 10 business days before the inspection","amount":"$90"},{"label":"One family, expedited, 1 to 3 business days before the inspection","amount":"$161"},{"label":"One family, reinspection on the next available Wednesday","amount":"$45"},{"label":"Two family, application received 11+ business days before the inspection","amount":"$90"},{"label":"Two family, application received 4 to 10 business days before the inspection","amount":"$180"},{"label":"Two family, expedited inspection, application received 1 to 3 business days before","amount":"$322"},{"label":"Two family, reinspection on the next Wednesday","amount":"$90"},{"label":"Returned check charge","amount":"$20.00"}]$j$::jsonb, $t$https://www.plainfieldnj.gov/C%20OF%20C%20SALE%20APPLICATION.12.22.docx$t$, $t$https://www.plainfieldnj.gov/residents/household/code_enforcement_and_inspections_division/index.php$t$, $j$[{"url":"https://www.plainfieldnj.gov/residents/household/code_enforcement_and_inspections_division/index.php","label":"Official source (plainfieldnj.gov)"},{"url":"https://www.plainfieldnj.gov/C%20OF%20C%20SALE%20APPLICATION.12.22.docx","label":"Official source (plainfieldnj.gov)"},{"url":"https://www.plainfieldnj.gov/residents/get_a_permit_or_license.php","label":"Official source (plainfieldnj.gov)"},{"url":"https://www.govpaynow.com/gps/user/cyg/plc/a0045L","label":"Official source (govpaynow.com)"},{"url":"https://www.plainfieldnj.gov/Document_Center/Applications%20Documents/Fire/ApplicationforInspectionCertificationofSmokeAlarm.Revised12.2021.pdf","label":"Official source (plainfieldnj.gov)"}]$j$::jsonb, $t$For a sale or rental, the City verifies compliance through a Certificate of Compliance inspection conducted by the Property Maintenance Unit.$t$, $t$46b62e7be5db0835633b599728b90d7d03efe162fcf2c8dd4b6d1d8cd4dc27e3$t$, $t$2026-10-02T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-02","approved_on":"2026-10-02","needs_lookup":false,"flag_reasons":[],"verification":{"fees":14,"fee_ok":14,"fee_bad":0,"fee_unchecked":0,"quotes":24,"q_ok":24,"q_bad":0,"q_unchecked":0},"source":"property/data/municipal-requirements/checked/2012.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-02 and approved in the NJ Resale Certificate Tracker on 2026-10-02. Source: property/data/municipal-requirements/checked/2012.json$t$, true),
  ($t$2012$t$, $t$Plainfield City$t$, $t$UNION$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: City of Plainfield Fire Department, Bureau of Fire Prevention (town fire bureau)","Contact: Anthony Pineda, Fire Official (state fire directory, survey July 2026); Fire Prevention is headed by Deputy Chief Joseph Franklin… · (908) 753-3446 · fireinspection@plainfieldnj.gov","Apply: Pay 11 or more business days before the inspection for the lowest fee. Inspections are on Wednesdays. A failed or missed inspection needs a new application and full payment.","How to apply: Pay online through the City's 'Smoke Home Inspections' GovPayNow page (card or e-check; a processing fee applies) or fill out the Application for Inspection Certification of Smoke Alarm, Carbon Monoxide Alarm and Portable Fire Extinguisher Compliance and e-mail it to fireinspection@plainfieldnj.gov. Then call (908) 753-3446 to confirm payment; the bureau e-mails the inspection date. By mail or in person, checks are payable to Plainfield Fire Department (personal checks only for the $45.00 fee).","Fire official in the NJ state directory, updated 7/22/2026: Anthony Pineda · (908) 753-3446 · anthony.pineda@plainfieldnj.gov","Smoke alarm on each level including basements (not attics unless finished, or crawl spaces)","Smoke alarm and carbon monoxide alarm near any flame-producing device, outside each sleeping area and within 10 feet of all bedroom doors","Battery-only smoke alarms must be 10-year sealed battery type; combination smoke/CO 10-year sealed alarms are acceptable","Homes with a low-voltage alarm system need an alarm test report from a NJ certified fire protection contractor","Portable fire extinguisher (2A:10BC, no more than 10 pounds) in the kitchen, no more than 5 feet above the floor, new with receipt or serviced and tagged within 12 months (2021 form; the City payment notice still names the extinguisher certificate)","Only one- and two-family dwellings are inspected; inspections are on Wednesdays","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"One family, application received 11+ business days before the inspection","amount":"$45"},{"label":"One family, application received 4 to 10 business days before the inspection","amount":"$90"},{"label":"One family, expedited, 1 to 3 business days before the inspection","amount":"$161"},{"label":"One family, reinspection on the next available Wednesday","amount":"$45"},{"label":"Two family, application received 11+ business days before the inspection","amount":"$90"},{"label":"Two family, application received 4 to 10 business days before the inspection","amount":"$180"},{"label":"Two family, expedited inspection, application received 1 to 3 business days before","amount":"$322"},{"label":"Two family, reinspection on the next Wednesday","amount":"$90"},{"label":"Returned check charge","amount":"$20.00"}]$j$::jsonb, $t$https://www.govpaynow.com/gps/user/cyg/plc/a0045L$t$, $t$https://www.plainfieldnj.gov/departments/fire/index.php$t$, $j$[{"url":"https://www.plainfieldnj.gov/departments/fire/index.php","label":"Official source (plainfieldnj.gov)"},{"url":"https://www.govpaynow.com/gps/user/cyg/plc/a0045L","label":"Official source (govpaynow.com)"},{"url":"https://www.plainfieldnj.gov/Document_Center/Applications%20Documents/Fire/ApplicationforInspectionCertificationofSmokeAlarm.Revised12.2021.pdf","label":"Official source (plainfieldnj.gov)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$Fire Prevention - Deputy Chief Joseph Franklin$t$, $t$9c7a0221f8586aaec769a10107127b31a27cfdf04e8ece7ed6e6a1d1b21a3f1d$t$, $t$2026-10-02T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-02","approved_on":"2026-10-02","needs_lookup":false,"flag_reasons":[],"verification":{"fees":14,"fee_ok":14,"fee_bad":0,"fee_unchecked":0,"quotes":24,"q_ok":24,"q_bad":0,"q_unchecked":0},"source":"property/data/municipal-requirements/checked/2012.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-02 and approved in the NJ Resale Certificate Tracker on 2026-10-02. Source: property/data/municipal-requirements/checked/2012.json$t$, true),
  ($t$2013$t$, $t$Rahway City$t$, $t$UNION$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Certificate of Approval for Continued Occupancy (CACO)$t$, $j$["Issued by: City of Rahway Department of Code Enforcement, Division of Property Maintenance","Contact: Frank Spallone, Director of Code Enforcement / Construction Official (Property Maintenance Division office phone and email shown) · 732-827-2199 · propertymaintenance@cityofrahway.com","Apply: Submit a complete application at least 2 to 3 weeks before closing; an inspector calls within 7 business days to schedule, and the report follows within about 5 business days","How to apply: Fill out the Application for Certificates of Approval for Continued Occupancy (check Change of Ownership and Purchase/Sale) and e-mail a copy to propertymaintenance@cityofrahway.com or bring it to the office at One City Hall Plaza. Pay by check or money order to the City of Rahway before the inspection date. Two-family homes need a Zoning Permit first. If the home fails, the buyer can close with a Temporary CACO by signing a notarized affidavit and paying the TCACO fee, once all fire safety items pass.","Exterior surfaces, foundation walls and roof sound and weather-tight","Stairs, porches, balconies and decks structurally sound; handrails on stairs over 4 risers and guardrails over 30 inches","Windows work and are glazed without cracks; insect screens on ventilation openings","Interior walls, ceilings and surfaces maintained (no peeling paint, loose plaster or decayed wood)","Sidewalks, driveways and aprons in good repair","Basements, cellars and crawl spaces reasonably dry","Plumbing installed and working without leaks","At least 2 outlets in each habitable room, kitchen outlets, light fixtures in halls, stairs, kitchen, bath, laundry and furnace room; GFCI within 6 feet of water","Smoke alarm on every level (including basements and finished attics), within 10 feet of bedroom doors; battery alarms 10-year sealed; hardwired not replaced with battery; alarms no more than 10 years old","Carbon monoxide alarm within 10 feet of sleeping areas; hardwired not replaced with battery","One portable fire extinguisher (2A:10BC, no more than 10 pounds, no more than 12 years old) within 10 feet of the kitchen (Rahway checklist)","Single family: building permits closed or resolved; two family: also a zoning permit before the CACO","Also: Open building permits: Building permits must be closed or resolved before a CACO is issued (single and two family).","Also: Zoning permit (two family and up): Residential properties with 2 or more units must get a Zoning Permit before applying for a CACO."]$j$::jsonb, $j$[{"label":"CACO, residential, per unit (includes the smoke and CO inspection for 1 and 2 unit homes)","amount":"$100.00"},{"label":"Temporary CACO (TCACO), residential, per unit (additional fee when closing on a temporary certificate)","amount":"$100.00"},{"label":"Included in the residential CACO fee, per unit (1 and 2 unit homes)","amount":"$100.00"}]$j$::jsonb, $t$https://rahwaynj.gov/DocumentCenter/View/2655$t$, $t$https://rahwaynj.gov/359/Division-of-Property-Maintenance$t$, $j$[{"url":"https://rahwaynj.gov/359/Division-of-Property-Maintenance","label":"Official source (rahwaynj.gov)"},{"url":"https://rahwaynj.gov/DocumentCenter/View/2655","label":"Official source (rahwaynj.gov)"},{"url":"https://rahwaynj.gov/DocumentCenter/View/1492","label":"Official source (rahwaynj.gov)"},{"url":"https://rahwaynj.gov/DocumentCenter/View/3149","label":"Official source (rahwaynj.gov)"},{"url":"https://rahwaynj.gov/Directory.aspx","label":"Official source (rahwaynj.gov)"}]$j$::jsonb, $t$The inspection for Smoke and CO detectors is included with the CACO inspection of residential properties with 1&2 units.$t$, $t$d5fb7a466b4dfff7ce519b98d2a965d015e594e10b7ea20d0812993fdb3db39a$t$, $t$2026-10-02T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-02","approved_on":"2026-10-02","needs_lookup":false,"flag_reasons":[],"verification":{"fees":3,"fee_ok":3,"fee_bad":0,"fee_unchecked":0,"quotes":20,"q_ok":20,"q_bad":0,"q_unchecked":0},"source":"property/data/municipal-requirements/checked/2013.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-02 and approved in the NJ Resale Certificate Tracker on 2026-10-02. Source: property/data/municipal-requirements/checked/2013.json$t$, true),
  ($t$2013$t$, $t$Rahway City$t$, $t$UNION$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: City of Rahway Division of Property Maintenance (smoke and CO inspection included in the CACO inspection for 1 and 2 unit homes; fire code enforcing agency is the Rahway Fire Department) (town fire bureau)","Contact: Frank Spallone, Director of Code Enforcement / Construction Official · 732-827-2199 · propertymaintenance@cityofrahway.com","Apply: Same as the CACO: apply 2 to 3 weeks before closing","How to apply: Apply for the CACO with the Division of Property Maintenance (propertymaintenance@cityofrahway.com); the smoke and CO inspection is part of that inspection for 1 and 2 unit homes.","Fire official in the NJ state directory, updated 1/9/2026: Steven P Niro · (732) 827-2133 · sniro@cityofrahway.com","Smoke alarm on every level including basements and finished attics, within 10 feet of bedroom doors; basement alarm at the base of the stairs","Battery smoke alarms must be 10-year sealed; hardwired alarms may not be replaced with battery alarms; alarms no more than 10 years old","Carbon monoxide alarm within 10 feet of any sleeping area (in the common area between bedrooms or in every bedroom)","One portable fire extinguisher (2A:10BC, no more than 10 pounds, no more than 12 years old, charged) visible within 10 feet of the kitchen (City checklist, undated)","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Included in the residential CACO fee, per unit (1 and 2 unit homes)","amount":"$100.00"}]$j$::jsonb, $t$https://rahwaynj.gov/DocumentCenter/View/2655$t$, $t$https://rahwaynj.gov/359/Division-of-Property-Maintenance$t$, $j$[{"url":"https://rahwaynj.gov/359/Division-of-Property-Maintenance","label":"Official source (rahwaynj.gov)"},{"url":"https://rahwaynj.gov/DocumentCenter/View/3149","label":"Official source (rahwaynj.gov)"},{"url":"https://rahwaynj.gov/Directory.aspx","label":"Official source (rahwaynj.gov)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"},{"url":"https://rahwaynj.gov/DocumentCenter/View/2655","label":"Official source (rahwaynj.gov)"}]$j$::jsonb, $t$The inspection for Smoke and CO detectors is included with the CACO inspection of residential properties with 1&2 units.$t$, $t$309f6672e4137f8bbfe92b7124db6cd459cb8366e4776979e512ce23695ca409$t$, $t$2026-10-02T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-02","approved_on":"2026-10-02","needs_lookup":false,"flag_reasons":[],"verification":{"fees":3,"fee_ok":3,"fee_bad":0,"fee_unchecked":0,"quotes":20,"q_ok":20,"q_bad":0,"q_unchecked":0},"source":"property/data/municipal-requirements/checked/2013.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-02 and approved in the NJ Resale Certificate Tracker on 2026-10-02. Source: property/data/municipal-requirements/checked/2013.json$t$, true),
  ($t$2014$t$, $t$Roselle Borough$t$, $t$UNION$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Residential Occupancy Certificate (ROC)$t$, $j$["Issued by: Borough of Roselle Division of Code Enforcement","Contact: (908) 259-3023","Apply: Open construction permits must be finaled before the ROC inspection is scheduled; if no violations are found the certificate can be issued within 10 business days","How to apply: Fill out the Application for Residential Occupancy Certificate (Borough forms page, Local Code Enforcement) and return it with the fee to the Division of Code Enforcement, 210 Chestnut Street, Roselle. Company checks or money orders only; personal checks are not accepted. Confirm with the Building Department that all construction permits have final inspections, then schedule the ROC inspection. The buyer's name must be given before the certificate is issued.","Valid for: Temporary certificate: up to 60 days (instructions page 1) or 90 days (checklist item 23)","10-year sealed battery smoke detectors on all levels including basements and attics over 7 feet high, within 10 feet outside bedrooms; existing hardwired alarms kept","Carbon monoxide detectors in basements and within 10 feet outside bedrooms, plus inside any bedroom directly above a garage","2A10BC fire extinguisher within 10 feet of the kitchen (1 and 2 family)","Bedroom windows open and close; windows and doors in good repair with proper hardware","Holes in walls, floors and ceilings repaired; missing tiles replaced and grouted","Hot and cold water with shut-off valves at kitchen and bath fixtures; toilets secure with shut-offs","GFI outlets within 6 feet of water and in all bathrooms; cover plates on all outlets, switches and junction boxes; dead wiring removed","Main electrical service line strapped to the building","Fireplaces and wood stoves with proper clearances and screens","Water heaters, boilers and furnaces working; relief valve discharge pipe within 4 inches of the floor; vents secured; gas shut-off in the same room","Sump pumps discharge outside, not into sanitary lines; garage door openers plugged directly into an outlet","Roofs, gutters and downspouts in good repair; handrails on stairs with 3 or more risers","House numbers at least 4 inches high, contrasting and visible from the curb","Yard cut, trimmed and free of debris; all utilities on","All open construction permits finalized; work done without permits must get permits","Also: Open construction permits: All open construction permits must be finalized before the ROC inspection; unpermitted work needs permits."]$j$::jsonb, $j$[{"label":"Residential Occupancy Certificate, 1 and 2 family","amount":"$100.00"},{"label":"Temporary Residential Occupancy Certificate (at the inspector's discretion)","amount":"$200.00"},{"label":"Each inspection beyond the second","amount":"$75.00"}]$j$::jsonb, $t$https://www.boroughofroselle.com/Document%20Center/How%20do%20i/Form/Local%20Code%20Enforcement/RCO%20Application.pdf$t$, $t$https://www.boroughofroselle.com/departments/local_code_enforcement.php$t$, $j$[{"url":"https://www.boroughofroselle.com/_how_do_i/apply_for/forms.php","label":"Official source (boroughofroselle.com)"},{"url":"https://www.boroughofroselle.com/Document%20Center/How%20do%20i/Form/Local%20Code%20Enforcement/Instructions-and-Checklist-for-CO.pdf","label":"Official source (boroughofroselle.com)"},{"url":"https://www.boroughofroselle.com/Document%20Center/How%20do%20i/Form/Local%20Code%20Enforcement/RCO%20Application.pdf","label":"Official source (boroughofroselle.com)"}]$j$::jsonb, $t$Residential Occupancy Certificate Application$t$, $t$231463d9ffe7f589b8e25f73b1828f88a3d72c87f1fb83613b0baa0d8c1e6127$t$, $t$2026-10-02T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-02","approved_on":"2026-10-02","needs_lookup":false,"flag_reasons":[],"verification":{"fees":3,"fee_ok":3,"fee_bad":0,"fee_unchecked":0,"quotes":15,"q_ok":15,"q_bad":0,"q_unchecked":0},"source":"property/data/municipal-requirements/checked/2014.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-02 and approved in the NJ Resale Certificate Tracker on 2026-10-02. Source: property/data/municipal-requirements/checked/2014.json$t$, true),
  ($t$2014$t$, $t$Roselle Borough$t$, $t$UNION$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Roselle Fire Department, Fire Official (fire code enforcing agency) (town fire bureau)","Contact: Jarelle Benjamin, Fire Official · 908-245-8600, ex. 3106 · jbenjamin@boroughofroselle.com","How to apply: No smoke / CO certificate application or fee is published on the Borough site; contact the Fire Official.","Fire official in the NJ state directory, updated 1/12/2026: Jarell Benjamin · (908) 245-8600 · jbenjamin@boroughofroselle.com","The Borough ROC checklist covers 10-year sealed battery smoke alarms, CO alarms and a 2A10BC extinguisher within 10 feet of the kitchen; whether this replaces a separate fire certificate is not stated","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[]$j$::jsonb, null, $t$https://www.boroughofroselle.com/departments/fire_department.php$t$, $j$[{"url":"https://www.boroughofroselle.com/departments/fire_department.php","label":"Official source (boroughofroselle.com)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$Fire Official Jarelle Benjamin (Email) jbenjamin@boroughofroselle.com (Office) 908-245-8600, ex. 3106 (Fax) 908-245-7260$t$, $t$274f2a40c4387223ed8b193bb7a28a20d4f05b5d3769a29167904531154be262$t$, $t$2026-10-02T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-02","approved_on":"2026-10-02","needs_lookup":false,"flag_reasons":[],"verification":{"fees":3,"fee_ok":3,"fee_bad":0,"fee_unchecked":0,"quotes":15,"q_ok":15,"q_bad":0,"q_unchecked":0},"source":"property/data/municipal-requirements/checked/2014.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-02 and approved in the NJ Resale Certificate Tracker on 2026-10-02. Source: property/data/municipal-requirements/checked/2014.json$t$, true),
  ($t$2015$t$, $t$Roselle Park Borough$t$, $t$UNION$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Resale Certificate (residential)$t$, $j$["Issued by: Borough Code Enforcement Officer (Department of Code Enforcement)","Contact: Judy Mack, Deputy Code Enforcement Officer · 908-245-6222 Ext 1201","Apply: Inspections are normally scheduled within 10 days after the application is submitted and the fee is paid","How to apply: The Borough website still posts the 2024 'Application for Resale Certificate (Residential Sales Only)' from the Department of Code Enforcement: fill in the closing date, block and lot, property type and owner details, and pay by check, money order or exact cash to 'Borough of Roselle Park'. Inspections are scheduled Monday to Thursday. Code Enforcement is on the 2nd floor of the Municipal Complex, 110 E Westfield Ave, phone 908-245-2721. Ordinance 2863 (August 2026) says new forms may be set up, including online submission, so call to confirm which form and fee apply now.","All open construction permits closed and any Construction Code Official violation notice fully resolved","Compliance with the Borough Property Maintenance Code (Chapter 19) and Fire Prevention and Protection chapter (Chapter 22)","Compliance with the Borough lead-based paint inspection and rental housing sections where they apply to the building","Smoke alarm and carbon monoxide alarm certificate from the Fire Prevention Official","Sump pumps must discharge outside the home or into the street gutter line, never into the sanitary sewer","House numbers clearly visible from the street, at least 4 inches high, block numbers (no script), on a contrasting background","A temporary resale certificate (up to 90 days) is possible when the buyer signs an affidavit agreeing to fix listed deficiencies","Also: Open building permits closed: All building permits must be closed by scheduling the final inspection with the Building Department (908-245-2721); the 2024 form says all building permits must be closed before the certificate is issued.","Also: Sump pump discharge: Sump pumps must discharge outside or into the street gutter, never into the sanitary sewer."]$j$::jsonb, $j$[{"label":"Resale Certificate (residential), first dwelling unit (Ordinance 2863, adopted August 20, 2026)","amount":"$60"},{"label":"Resale Certificate (residential), each additional dwelling unit (Ordinance 2863)","amount":"$20"},{"label":"Smoke detector certificate, single family (Fire Department fee schedule, Ordinance 2863)","amount":"$70"},{"label":"Smoke detector certificate, multi-family, up to 4 dwelling units (applies to a two-family home)","amount":"$100"},{"label":"Smoke detector certificate, each additional unit above 4","amount":"$25"}]$j$::jsonb, $t$https://www.rosellepark.gov/DocumentCenter/View/134/Residential-Resale-Certificate-Application-PDF$t$, $t$https://www.rosellepark.gov/directory.aspx?did=16$t$, $j$[{"url":"https://www.rosellepark.gov/DocumentCenter/View/795/Posted-08-26-2026-Notice-of-Adoption-Ordinance-No-2863","label":"Official source (rosellepark.gov)"},{"url":"https://www.rosellepark.gov/DocumentCenter/View/134/Residential-Resale-Certificate-Application-PDF","label":"Official source (rosellepark.gov)"},{"url":"https://www.rosellepark.gov/DocumentCenter/View/723/Resale-Certificate-Requirements-Smoke-Detectors-PDF","label":"Official source (rosellepark.gov)"},{"url":"https://www.rosellepark.gov/directory.aspx?did=16","label":"Official source (rosellepark.gov)"}]$j$::jsonb, $t$Resale Certificate required. Unless otherwise exempted pursuant to this Chapter, no property owner shall sell any building or structure within the Borough of Roselle Park unless that property owner first obtains a resale certificate pursuant to the procedures established in this Chapter.$t$, $t$570abbd7eaaedaf6689edb41229ad1e55431c396c3fda73aea05229588219e3b$t$, $t$2026-10-02T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-02","approved_on":"2026-10-02","needs_lookup":false,"flag_reasons":[],"verification":{"fees":5,"fee_ok":5,"fee_bad":0,"fee_unchecked":0,"quotes":20,"q_ok":20,"q_bad":0,"q_unchecked":0},"source":"property/data/municipal-requirements/checked/2015.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-02 and approved in the NJ Resale Certificate Tracker on 2026-10-02. Source: property/data/municipal-requirements/checked/2015.json$t$, true),
  ($t$2015$t$, $t$Roselle Park Borough$t$, $t$UNION$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Roselle Park Fire Prevention Bureau (Fire Official) (town fire bureau)","Contact: Joseph Kopf, Fire Official · 908-245-6222 x1200 · jkopf@rosellepark.net","How to apply: Call the Fire Prevention Clerk at 908-245-6222 x1200; Fire Prevention Bureau staff are part-time and have no set office hours, so leave a message if routed to voicemail. Until a new form is posted, the Borough's posted resale application (Department of Code Enforcement, 2024) is the form that covers the smoke, CO and extinguisher requirement; pay by check, money order or exact cash to 'Borough of Roselle Park'.","Fire official in the NJ state directory, updated 6/3/2026: Joseph E. Kopf III · (908) 245-6222 · jkopf@rosellepark.net","Ten-year sealed battery or hardwired interconnected smoke alarms on each level and in the bedroom area, including basements and finished attics","CO detection outside all sleeping areas; with any fuel-burning appliance, also on the floor below, the floor where the appliance is, and the floor above","Fire extinguisher still listed on the Borough's May 2026 requirements sheet: at least one 2A:10BC, no more than 10 pounds, visible within 10 feet of the kitchen near an exit path, mounted no more than 5 feet off the floor, not in a cabinet or behind a closed door","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Smoke detector certificate, single family (Fire Department fee schedule, Ordinance 2863)","amount":"$70"},{"label":"Smoke detector certificate, multi-family, up to 4 dwelling units (applies to a two-family home)","amount":"$100"},{"label":"Smoke detector certificate, each additional unit above 4","amount":"$25"}]$j$::jsonb, $t$https://www.rosellepark.gov/DocumentCenter/View/134/Residential-Resale-Certificate-Application-PDF$t$, $t$https://www.rosellepark.gov/193/Fire-Prevention-Bureau$t$, $j$[{"url":"https://www.rosellepark.gov/DocumentCenter/View/795/Posted-08-26-2026-Notice-of-Adoption-Ordinance-No-2863","label":"Official source (rosellepark.gov)"},{"url":"https://www.rosellepark.gov/193/Fire-Prevention-Bureau","label":"Official source (rosellepark.gov)"},{"url":"https://www.rosellepark.gov/194/Permit-Forms-Public-Documents","label":"Official source (rosellepark.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"},{"url":"https://www.rosellepark.gov/DocumentCenter/View/723/Resale-Certificate-Requirements-Smoke-Detectors-PDF","label":"Official source (rosellepark.gov)"}]$j$::jsonb, $t$Certificate of Smoke Alarm and Carbon Monoxide Alarm Compliance (generally known as a “smoke detector certificate”) where required, to be issued by the Fire Prevention Official.$t$, $t$8990ddc076b23f2d14ff7c26b997de075376b826b9fdf884da61d3db7f99722a$t$, $t$2026-10-02T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-02","approved_on":"2026-10-02","needs_lookup":false,"flag_reasons":[],"verification":{"fees":5,"fee_ok":5,"fee_bad":0,"fee_unchecked":0,"quotes":20,"q_ok":20,"q_bad":0,"q_unchecked":0},"source":"property/data/municipal-requirements/checked/2015.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-02 and approved in the NJ Resale Certificate Tracker on 2026-10-02. Source: property/data/municipal-requirements/checked/2015.json$t$, true),
  ($t$2018$t$, $t$Summit City$t$, $t$UNION$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Zoning Certificate of Occupancy (ZCO)$t$, $j$["Issued by: Department of Community Services (Zoning / Code Administration)","Contact: Roger Dornbierer, Zoning Officer · (908) 273-6407 · rdornbierer@cityofsummit.org","Apply: Submit the application at least 10 days before the requested inspection date; the certificate is issued no earlier than 5 business days after the inspection (the form's statement of understanding says 48 hours)","How to apply: Complete the Zoning Certificate of Occupancy Application (all 5 steps, including the new owner's name before the certificate is issued) and submit it with a check payable to 'CITY OF SUMMIT' to the Department of Community Services, 512 Springfield Avenue, at least 10 days before the inspection date. 1-2 family inspections are Tuesdays, Wednesdays and Thursdays, 9am to 11am; someone 18 or older must let the inspector in. A temporary C/O is issued only for weather or 'as is' sales, and repairs over $200 need an escrow.","Sidewalks, curbs and driveway apron in need of replacement must be replaced (Engineering permit)","Permanent house number at least 3 inches high, visible from the street","Roof, fencing, entrance steps, porches and railings in good repair; clear sightline within 10 feet of the curb","48-inch pool fence with self-closing, latching gates","Property cleared of trash, debris and hazardous materials; recreational vehicles or trailers removed or garaged; shrubs and lawn trimmed","Code compliant smoke detectors near each bedroom door and on each level including the basement; sealed 10-year smoke detectors since January 2019","Mounted 2A:10B:C fire extinguisher within 10 feet of the kitchen, no more than 5 feet above the floor (still on the September 2025 checklist)","Sump pump discharge removed from the sanitary sewer and routed outside","Flue pipes and chimney connections at furnace and water heater sound; water heater and boiler relief valve discharge pipe to within 6 inches of the floor","Handrails 34 to 38 inches high on at least one side of stairs; guardrails on open sides","Working plumbing fixtures, switches and outlets with cover plates; no interior key locks on rooms","Only one kitchen per dwelling; work done without permits must be permitted; zoning violations corrected","Also: Sidewalk, curb and apron repairs: Sidewalks, curbs and driveway aprons marked for replacement must be fixed; curb and sidewalk work needs an Engineering Division permit and inspection.","Also: Open or missing permits: Work done without a permit must be permitted; questions go to the Construction Division at 908-273-6408."]$j$::jsonb, $j$[{"label":"1 or 2 family detached dwelling, per unit","amount":"$100.00"},{"label":"Attached 1-family dwelling unit (and multi-family), per unit","amount":"$150.00"},{"label":"Zoning Certificate of Occupancy, 1 or 2 family detached dwelling, per unit (smoke detector check is part of the ZCO inspection; no separate smoke certificate fee found)","amount":"$100.00"}]$j$::jsonb, $t$https://www.cityofsummit.org/DocumentCenter/View/78$t$, $t$https://www.cityofsummit.org/164/Zoning-Certificates-of-Occupancy$t$, $j$[{"url":"https://www.cityofsummit.org/164/Zoning-Certificates-of-Occupancy","label":"Official source (cityofsummit.org)"},{"url":"https://www.cityofsummit.org/DocumentCenter/View/78","label":"Official source (cityofsummit.org)"},{"url":"https://cityofsummit.org/DocumentCenter/View/86","label":"Official source (cityofsummit.org)"},{"url":"https://www.cityofsummit.org/m/directory/department?did=9","label":"Official source (cityofsummit.org)"}]$j$::jsonb, $t$Zoning Certificates of Occupancy (ZCOs) (PDF) are required to be obtained by the Development Regulations Zoning Ordinance for the sale or rental, or for change of occupant or occupancy type for all buildings or for individual units within buildings.$t$, $t$1356b067e284532194feb3d555e53cf0b9d92031795b9c548360dba4d511dead$t$, $t$2026-10-02T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-02","approved_on":"2026-10-02","needs_lookup":false,"flag_reasons":[],"verification":{"fees":3,"fee_ok":3,"fee_bad":0,"fee_unchecked":0,"quotes":16,"q_ok":16,"q_bad":0,"q_unchecked":0},"source":"property/data/municipal-requirements/checked/2018.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-02 and approved in the NJ Resale Certificate Tracker on 2026-10-02. Source: property/data/municipal-requirements/checked/2018.json$t$, true),
  ($t$2018$t$, $t$Summit City$t$, $t$UNION$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: City of Summit Department of Community Services, Code Administration and Construction Office (smoke detector certificate inspections for home sales, done as part of the Zoning Certificate of… (town fire bureau)","Contact: Ralph Maritato, Construction Official · (908) 273-6408 · rmaritato@cityofsummit.org","Apply: Apply with the ZCO at least 10 days before the requested inspection date","How to apply: Apply for the Zoning Certificate of Occupancy at the Department of Community Services, 512 Springfield Avenue; the smoke detector requirements are enforced during the ZCO inspection. Questions: Code & Administration, 908-273-6408.","Fire official in the NJ state directory, updated 3/25/2026: Lt. Matthew K. Lemons · (908) 277-9353 · mlemons@cityofsummit.org","Sealed unit 10-year smoke detectors in all required locations for any residential ZCO for sale or rental since 2019, even if the home has working battery detectors (no change for hardwired AC-powered detectors)","Smoke detectors near each bedroom door and on each level including the basement, not in an unheated attic","Mounted 2A:10B:C fire extinguisher within 10 feet of the kitchen, no more than 5 feet above the floor (September 2025 checklist)","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Zoning Certificate of Occupancy, 1 or 2 family detached dwelling, per unit (smoke detector check is part of the ZCO inspection; no separate smoke certificate fee found)","amount":"$100.00"}]$j$::jsonb, $t$https://www.cityofsummit.org/DocumentCenter/View/78$t$, $t$https://www.cityofsummit.org/238/Fire-Prevention-Bureau-Inspections$t$, $j$[{"url":"https://www.cityofsummit.org/238/Fire-Prevention-Bureau-Inspections","label":"Official source (cityofsummit.org)"},{"url":"https://cityofsummit.org/DocumentCenter/View/5532/Smoke-Detector-Change-2019","label":"Official source (cityofsummit.org)"},{"url":"https://cityofsummit.org/DocumentCenter/View/86","label":"Official source (cityofsummit.org)"},{"url":"https://www.cityofsummit.org/m/directory/department?did=8","label":"Official source (cityofsummit.org)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"},{"url":"https://www.cityofsummit.org/DocumentCenter/View/78","label":"Official source (cityofsummit.org)"}]$j$::jsonb, $t$Smoke detector certificate inspections, required for the sale of a home, are done by the Department of Community Services Code Administration and Construction Office. They can be reached at 908-273-6408.$t$, $t$8c3297948ff380d2af11691f61bb4c8630e1fc23d5ee57b33b42a5aa84be131d$t$, $t$2026-10-02T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-02","approved_on":"2026-10-02","needs_lookup":false,"flag_reasons":[],"verification":{"fees":3,"fee_ok":3,"fee_bad":0,"fee_unchecked":0,"quotes":16,"q_ok":16,"q_bad":0,"q_unchecked":0},"source":"property/data/municipal-requirements/checked/2018.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-02 and approved in the NJ Resale Certificate Tracker on 2026-10-02. Source: property/data/municipal-requirements/checked/2018.json$t$, true),
  ($t$2019$t$, $t$Union Township$t$, $t$UNION$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Residential Resale Certificate (Certificate of Continued Occupancy, CCO)$t$, $j$["Issued by: Building Department (Construction Code Official; Housing Inspector schedules re-inspections)","Contact: Anthony Monguso, Construction Code Official · 908.851.8509 · building@uniontownship.com","Apply: Request at least 10 business days before the inspection date; the certificate is issued 2 full business days after final approval","How to apply: Apply online with the Township's GovPilot 'Certificate of Continued Occupancy Application' (choose Resale), enter the closing date and contact for the inspection, and pay the $175.00 fee by debit or credit card. Inspections are Monday to Friday between 10:00 a.m. and 2:00 p.m.; the owner or a representative must be home. For a re-inspection, call the office (do not re-apply) and a payment link for $80.00 will be emailed.","Valid for: 3 months from the date of issue, unless occupancy or ownership changes in the meantime; not transferable","Smoke detectors on each level and within 10 feet of each separate sleeping area; battery alarms must be 10-year sealed units since January 1, 2019","Two-family homes also need a smoke detector at the highest level of each common stairwell","Existing hardwired smoke and CO systems must be kept to the level of the original certificate of occupancy; battery alarms are not acceptable replacements","No double-sided tape for mounting detectors","CO alarms outside each sleeping area, within 10 feet of bedroom doors","Portable fire extinguisher within 10 feet of the kitchen area: at least 2A:10B:C, no larger than 10 lbs, on a hanger or bracket, top no more than 5 feet above the floor, visible, near an exit path","All open permits closed out with the proper inspections","Sheds, fences, pools, decks and garages must have permits on file for the CCO application to be accepted","Owner certifies the property meets zoning and that no rubbish, debris or bulk garbage will be left before the new occupancy","Also: Open permits closed: All open permits must be closed out with the proper inspections before the resale inspection; existing sheds, fences, pools, decks and garages need permits on file.","Also: No debris left: The owner certifies no rubbish, debris or bulk garbage will be left on the property before new occupancy; otherwise the CCO can be retracted and a summons issued."]$j$::jsonb, $j$[{"label":"Residential resale certificate (Certificate of Continued Occupancy) inspection","amount":"$175.00"},{"label":"Each re-inspection","amount":"$80.00"},{"label":"Residential resale certificate (Certificate of Continued Occupancy) inspection","amount":"$175.00"},{"label":"Each re-inspection","amount":"$80.00"}]$j$::jsonb, $t$https://main.govpilot.com/web/public/45e3dda3-916_CCO-Application-uniontownship?uid=6840&ust=NJ&pu=1&id=0$t$, $t$https://www.uniontownship.com/134/Building-Department$t$, $j$[{"url":"https://www.uniontownship.com/DocumentCenter/View/78","label":"Official source (uniontownship.com)"},{"url":"https://www.uniontownship.com/134/Building-Department","label":"Official source (uniontownship.com)"},{"url":"https://main.govpilot.com/web/public/45e3dda3-916_CCO-Application-uniontownship?uid=6840&ust=NJ&pu=1&id=0","label":"Official source (main.govpilot.com)"},{"url":"https://ecode360.com/40914438","label":"Official source (ecode360.com)"},{"url":"https://www.uniontownship.com/Directory.aspx?DID=7","label":"Official source (uniontownship.com)"}]$j$::jsonb, $t$Procedure for Obtaining Residential Resale Certificate$t$, $t$41d6fd05cbd895bb9736e27d6aaa42da34287010d5ab780c0a7932c25c1775bd$t$, $t$2026-10-02T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-02","approved_on":"2026-10-02","needs_lookup":false,"flag_reasons":[],"verification":{"fees":4,"fee_ok":4,"fee_bad":0,"fee_unchecked":0,"quotes":19,"q_ok":18,"q_bad":0,"q_unchecked":1},"source":"property/data/municipal-requirements/checked/2019.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-02 and approved in the NJ Resale Certificate Tracker on 2026-10-02. Source: property/data/municipal-requirements/checked/2019.json$t$, true),
  ($t$2019$t$, $t$Union Township$t$, $t$UNION$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Township of Union Building Department (Residential Resale Certificate / CCO inspection checks smoke detectors, CO alarms and fire extinguishers) (town fire bureau)","Contact: Anthony Monguso, Construction Code Official · 908.851.8509 · building@uniontownship.com","Apply: At least 10 business days before the inspection date","How to apply: Same application as the resale certificate: the Township's online GovPilot Certificate of Continued Occupancy Application, paid by debit or credit card.","Fire official in the NJ state directory, updated 3/27/2026: Orland Guzman · (908) 851-5422 · oguzman@uniontownship.com","Battery smoke alarms must be 10-year sealed units (since January 1, 2019)","Two-family homes need a smoke detector at the highest level of each common stairwell","Hardwired smoke and CO systems must be maintained as originally approved; no battery replacements","Portable fire extinguisher still required on the Township's 2024 sheet: at least 2A:10B:C, no more than 10 lbs, within 10 feet of the kitchen, mounted with the top no more than 5 feet above the floor","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Residential resale certificate (Certificate of Continued Occupancy) inspection","amount":"$175.00"},{"label":"Each re-inspection","amount":"$80.00"}]$j$::jsonb, $t$https://main.govpilot.com/web/public/45e3dda3-916_CCO-Application-uniontownship?uid=6840&ust=NJ&pu=1&id=0$t$, $t$https://www.uniontownship.com/134/Building-Department$t$, $j$[{"url":"https://www.uniontownship.com/DocumentCenter/View/78","label":"Official source (uniontownship.com)"},{"url":"https://www.uniontownship.com/165/Fire-Prevention-Bureau","label":"Official source (uniontownship.com)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$N.J.A.C 5:l70-2.3 REQUIREMENTS FOR THE INSTALLATION OF SMOKE AND CARBON MONOXIDE DETECTORS IN ONE AND TWO FAMILY DWELLING$t$, $t$8e46735858bc85da4e902be55ab4eea8e9c8115fd2b9d853467baffc5f46b77c$t$, $t$2026-10-02T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-02","approved_on":"2026-10-02","needs_lookup":false,"flag_reasons":[],"verification":{"fees":4,"fee_ok":4,"fee_bad":0,"fee_unchecked":0,"quotes":19,"q_ok":18,"q_bad":0,"q_unchecked":1},"source":"property/data/municipal-requirements/checked/2019.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-02 and approved in the NJ Resale Certificate Tracker on 2026-10-02. Source: property/data/municipal-requirements/checked/2019.json$t$, true),
  ($t$2020$t$, $t$Westfield Town$t$, $t$UNION$t$, $t$resale_cco$t$, $t$official_process_found$t$, $t$Resale / Continued Certificate of Occupancy (CCO)$t$, $j$["Not required for sales, per Westfield Town. Confirm with the office if the buyer's lender or title company asks.","Contact: Frank Vuoso, Construction Official · 908-789-4125 · fvuoso@westfieldnj.gov","How to apply: No town Certificate of Occupancy or Continued Certificate of Occupancy is needed to sell a home in Westfield. The seller only needs the Certificate of Smoke Detector and Carbon Monoxide Alarm Compliance from the Fire Prevention Bureau.","Also: Open construction permits: The Fire Prevention Bureau notifies the Building Department of open permits; they must be closed before the smoke/CO certificate is issued."]$j$::jsonb, $j$[]$j$::jsonb, null, $t$https://www.westfieldnj.gov/547/Building-Construction$t$, $j$[{"url":"https://www.westfieldnj.gov/Faq.aspx?QID=224","label":"Official source (westfieldnj.gov)"},{"url":"https://www.westfieldnj.gov/547/Building-Construction","label":"Official source (westfieldnj.gov)"}]$j$::jsonb, $t$Westfield does not require these items to sell a home or to open/transfer a business. There is a requirement to have a Certificate of Smoke Detector & Carbon Monoxide Alarm Compliance Inspection completed for a home sale$t$, $t$e3a4b1ff8099a5a79d5cb6b5f4fd23f8a9af802c1db1e41eabc99d31130547a9$t$, $t$2026-10-02T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-02","approved_on":"2026-10-02","needs_lookup":false,"flag_reasons":[],"verification":{"fees":3,"fee_ok":3,"fee_bad":0,"fee_unchecked":0,"quotes":10,"q_ok":10,"q_bad":0,"q_unchecked":0},"source":"property/data/municipal-requirements/checked/2020.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-02 and approved in the NJ Resale Certificate Tracker on 2026-10-02. Source: property/data/municipal-requirements/checked/2020.json$t$, true),
  ($t$2020$t$, $t$Westfield Town$t$, $t$UNION$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Westfield Fire Department, Bureau of Fire Prevention (town fire bureau)","Contact: Thomas Bottini, Fire Official · 908-789-4145 · fireprevention@westfieldnj.gov","Apply: Lowest fee when the inspection is scheduled more than 10 business days after payment is received; inspections Tuesdays and Thursdays, 9:00am to 12:00pm","How to apply: Apply online with the Town's Smoke Detector Application form, or download the PDF application and send it with a check payable to 'WESTFIELD FIRE DEPARTMENT' to the Bureau of Fire Prevention, 1029 Central Ave., Westfield, NJ 07090. Online payment by credit card or e-check is also accepted. An adult (18 or older) must be present; the engine company arrives between 9am and 12pm on Tuesday or Thursday. The certificate is emailed to the one email address given on the application.","Fire official in the NJ state directory, updated 1/8/2026: Thomas Bottini · (908) 789-4146 · tbottini@westfieldnj.gov","Ten-year sealed battery smoke alarms; A/C-powered alarms from original construction may not be replaced with battery alarms","Smoke detectors on every level (basement, first floor, second floor, excluding crawl spaces and unfinished attics) and outside sleeping areas","CO detectors outside each sleeping area in the hallway; two are needed if bedrooms are on different levels or wings; plug-in CO detectors are allowed","Homes with a central station fire alarm need a letter from the monitoring company stating the system works","Open construction permits must be closed before the certificate is issued","Fire extinguisher no longer required as of March 14, 2025","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Inspection scheduled more than 10 business days after payment received","amount":"$100.00"},{"label":"Inspection scheduled 4 to 10 business days after payment received","amount":"$125.00"},{"label":"Inspection scheduled fewer than 4 business days after payment received","amount":"$150.00"}]$j$::jsonb, $t$https://www.westfieldnj.gov/FormCenter/Fire-Department-Forms-22/Smoke-Detector-Application-134$t$, $t$https://www.westfieldnj.gov/2041/Smoke-Detector-Application$t$, $j$[{"url":"https://www.westfieldnj.gov/2041/Smoke-Detector-Application","label":"Official source (westfieldnj.gov)"},{"url":"https://www.westfieldnj.gov/DocumentCenter/View/8456/Smoke-Detector-Application","label":"Official source (westfieldnj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$before any one- or two-family dwelling is sold, leased, or otherwise made subject to change in occupancy for residential purposes, the owner shall obtain a certificate of compliance from the Westfield Fire Department, Bureau of Fire Prevention. Failure to obtain this certificate prior to change in occupancy shall result in a $200.00 fine.$t$, $t$bdce7b43037e14f1c113b9fafacc9e35b4f0562a2c00671d8a0f9faca93664a6$t$, $t$2026-10-02T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-02","approved_on":"2026-10-02","needs_lookup":false,"flag_reasons":[],"verification":{"fees":3,"fee_ok":3,"fee_bad":0,"fee_unchecked":0,"quotes":10,"q_ok":10,"q_bad":0,"q_unchecked":0},"source":"property/data/municipal-requirements/checked/2020.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-02 and approved in the NJ Resale Certificate Tracker on 2026-10-02. Source: property/data/municipal-requirements/checked/2020.json$t$, true)
